/// Deterministic canonicalization for rejected-value matching (#849):
/// 1. If the value is valid JSON, re-serialize it compactly with serde_json so
///    that structural whitespace/formatting cannot launder a rejected value.
/// 2. Collapse all whitespace runs to single spaces.
/// 3. Lowercase (ASCII-equivalent case folding for the common case).
/// The rejected value itself is never stored — only the SHA-256 of this
/// canonical form — so raw rejected content cannot leak into the store.
fn normalize_rejected_value(value: &str) -> String {
    let canonical = match serde_json::from_str::<serde_json::Value>(value) {
        Ok(mut v) => {
            // Admission/provenance is hash-only write metadata added by the
            // durable-write boundary. It must not change the semantic value
            // digest used by rejected-value tombstones (#849/#863).
            if let Some(object) = v.as_object_mut() {
                object.remove("provenance");
                object.remove("admission");
            }
            v.to_string()
        }
        Err(_) => value.to_string(),
    };
    canonical
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}

fn rejected_value_digest(value: &str) -> String {
    let normalized = normalize_rejected_value(value);
    format!("{:x}", Sha256::digest(normalized.as_bytes()))
}

/// #999: visibility lattice — private < fleet < workspace/tenant < public
/// (most → least restrictive). Intersection of a set = its most restrictive
/// member; mirrors `can_read`'s tier semantics so the lattice and the
/// enforcement agree. Unknown values are treated as open (historical rows).
fn more_restrictive_visibility(a: &str, b: &str) -> String {
    fn rank(v: &str) -> u8 {
        match v {
            "private" => 0,
            "fleet" => 1,
            "workspace" | "tenant" => 2,
            _ => 3,
        }
    }
    if rank(a) <= rank(b) {
        a.to_string()
    } else {
        b.to_string()
    }
}

/// Hex sha256 of raw bytes (no normalization) — used for hash-only audit
/// evidence of identifiers (contract §6.2/§6.4 in
/// docs/specs/data-boundaries-retention-lifecycle.md).
/// #1060: raw-bytes SHA-256 hex (seal helper; entity bodies hash as UTF-8 via
/// `sha256_hex` so the sealed bytes are exactly the stored string).
pub(crate) fn seal_sha256_bytes(bytes: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    digest_to_hex(&Sha256::digest(bytes))
}

pub(crate) fn sha256_hex(value: &str) -> String {
    format!("{:x}", Sha256::digest(value.as_bytes()))
}

fn selection_json<T: serde::Serialize>(value: &T) -> String {
    serde_json::to_string(value).unwrap_or_else(|_| "null".to_string())
}

/// #868: extract the retention expiry (unix ms) from an entity body's
/// `expires_at` field, if present. Accepts an integer (unix ms), a numeric
/// string (unix ms), or an ISO 8601 UTC timestamp (util::parse_iso8601_ms).
/// `None` means "never expires" (the column default). Written to
/// `entities.expires_at_unix_ms` on every remember/update so the lifecycle
/// sweep and the recall filters agree on one value.
pub fn entity_expiry_ms(body_json: &str) -> Option<i64> {
    let v: serde_json::Value = serde_json::from_str(body_json).ok()?;
    match v.get("expires_at") {
        Some(serde_json::Value::Number(n)) => n.as_i64(),
        Some(serde_json::Value::String(s)) => {
            let t = s.trim();
            if !t.is_empty() && t.bytes().all(|c| c.is_ascii_digit()) {
                t.parse().ok()
            } else {
                crate::util::parse_iso8601_ms(t)
            }
        }
        _ => None,
    }
}

/// #868: evidence relationships marking a link as "derived content cites its
/// source" (mirrors claim_card.rs EVIDENCE_RELS and beliefs.rs).
const ERASE_EVIDENCE_RELS: [&str; 3] = ["evidence_for", "derived_from", "promoted_to"];

/// #868: derived categories whose rows are QUARANTINED (not deleted) when a
/// cited source is erased: the content aggregates evidence and an operator
/// must decide keep/refine/delete (contract §5.6).
const ERASE_DERIVED_CATEGORIES: [&str; 3] = ["beliefs", "observation", "synthesis"];

/// #868: remove `erased_id` from every community membership in the workspace;
/// delete communities left empty; clear `summary_entity_id` that pointed at
/// the erased row and invalidate `member_digest` so the summary recomputes on
/// the next maintenance pass (communities are derived, regenerable artifacts).
/// With `apply=false` this only counts what the real run would change.
fn erase_cleanup_communities(
    conn: &rusqlite::Connection,
    erased_id: &str,
    workspace_hash: &str,
    apply: bool,
) -> Result<(i64, i64), Box<dyn std::error::Error>> {
    let mut stmt = conn.prepare(
        "SELECT id, member_ids, summary_entity_id FROM communities
         WHERE workspace_hash = ?1",
    )?;
    let rows = stmt.query_map(params![workspace_hash], |r| {
        Ok((
            r.get::<_, String>(0)?,
            r.get::<_, String>(1)?,
            r.get::<_, String>(2)?,
        ))
    })?;
    let mut memberships_cleaned = 0i64;
    let mut rows_deleted = 0i64;
    for row in rows {
        let (cid, member_ids_json, summary_entity_id) = row?;
        let mut members: Vec<String> = serde_json::from_str(&member_ids_json).unwrap_or_default();
        let before = members.len();
        members.retain(|m| m != erased_id);
        if members.len() == before {
            continue;
        }
        memberships_cleaned += 1;
        if !apply {
            continue;
        }
        if members.is_empty() {
            conn.execute("DELETE FROM communities WHERE id = ?1", params![cid])?;
            rows_deleted += 1;
        } else {
            let summary_entity_id = if summary_entity_id == erased_id {
                String::new()
            } else {
                summary_entity_id
            };
            conn.execute(
                "UPDATE communities SET member_ids = ?1, member_digest = '',
                 summary_entity_id = ?2
                 WHERE id = ?3",
                params![serde_json::to_string(&members)?, summary_entity_id, cid],
            )?;
        }
    }
    Ok((memberships_cleaned, rows_deleted))
}

/// #868: sweep inbound link edges pointing at the erased id from all other
/// rows in the workspace; QUARANTINE derived-category rows that cited the
/// erased source via an evidence relationship (contract §5.6 — derived
/// content must not keep serving as if its source still existed). Returns
/// (inbound_links_cleaned, derived_quarantined). With `apply=false` this
/// only counts what the real run would change.
fn erase_sweep_inbound_links(
    conn: &rusqlite::Connection,
    erased_id: &str,
    workspace_hash: &str,
    reason: &str,
    apply: bool,
) -> Result<(i64, i64), Box<dyn std::error::Error>> {
    let mut stmt = conn.prepare(
        "SELECT id, category, links FROM entities
         WHERE workspace_hash = ?1 AND id != ?2",
    )?;
    let rows = stmt.query_map(params![workspace_hash, erased_id], |r| {
        Ok((
            r.get::<_, String>(0)?,
            r.get::<_, String>(1)?,
            r.get::<_, String>(2)?,
        ))
    })?;
    let mut links_cleaned = 0i64;
    let mut derived_quarantined = 0i64;
    for row in rows {
        let (eid, category, links_json) = row?;
        let mut links: Vec<crate::models::MemoryLink> =
            serde_json::from_str(&links_json).unwrap_or_default();
        let before = links.len();
        let mut cited_evidence = false;
        links.retain(|l| {
            if l.target_id == erased_id {
                if ERASE_EVIDENCE_RELS.contains(&l.relationship.as_str()) {
                    cited_evidence = true;
                }
                false
            } else {
                true
            }
        });
        if links.len() == before {
            continue;
        }
        links_cleaned += 1;
        if !apply {
            continue;
        }
        conn.execute(
            "UPDATE entities SET links = ?1 WHERE id = ?2",
            params![serde_json::to_string(&links)?, eid],
        )?;
        // Quarantine only when the erased edge was an evidence relationship:
        // a derived row must not keep serving as if its cited source still
        // existed. Plain 'related'-style edges just lose the edge.
        if cited_evidence && ERASE_DERIVED_CATEGORIES.contains(&category.as_str()) {
            conn.execute(
                "UPDATE entities SET status = 'quarantined', archive_reason = ?1
                 WHERE id = ?2",
                params![reason, eid],
            )?;
            derived_quarantined += 1;
        }
    }
    Ok((links_cleaned, derived_quarantined))
}

/// Durable-write authority is explicit at the database boundary. Public and
/// unverified writers cannot elevate trust; internal derived/maintenance paths
/// use a named crate-private authority; only an evidence-backed admission may
/// activate an authoritative record.
#[derive(Debug, Clone)]
pub(crate) enum DurableWriteAuthority {
    Unverified,
    InternalTrusted(&'static str),
    Admission(crate::trust_admission::AdmissionEvidence),
    ReviewTransition(crate::trust_admission::AdmissionEvidence),
}

fn ensure_durable_write_provenance(entity: Entity, authority: &DurableWriteAuthority) -> Entity {
    match authority {
        DurableWriteAuthority::Admission(_) => {
            // Admission evidence is independently validated immediately before
            // this function is called. Preserve an explicit operator label but
            // elevate the default candidate trust state only for that path.
            let mut admitted = entity;
            if !crate::models::EPISTEMIC_STATES.contains(&admitted.epistemic_state.as_str()) {
                admitted.epistemic_state = "candidate".to_string();
            }
            if admitted.epistemic_state == "candidate" {
                admitted.epistemic_state = "verified".to_string();
            }
            admitted
        }
        DurableWriteAuthority::InternalTrusted(_writer) => {
            let mut trusted = entity;
            if !crate::models::EPISTEMIC_STATES.contains(&trusted.epistemic_state.as_str()) {
                trusted.epistemic_state = "candidate".to_string();
            }
            if trusted.epistemic_state == "candidate" {
                trusted.epistemic_state = "verified".to_string();
            }
            trusted
        }
        DurableWriteAuthority::ReviewTransition(_) => entity,
        DurableWriteAuthority::Unverified => {
            #[cfg(test)]
            if entity.source != "cli-write" {
                // Historical in-module fixtures use many source labels. Keep
                // those read-path fixtures active; production/public writes do
                // not receive this test-only compatibility branch.
                return entity;
            }
            let mut enriched = entity;
            if enriched.status == "active" {
                enriched.status = "proposed".to_string();
                enriched.always_on = false;
            }
            if enriched.epistemic_state != "rejected"
                && enriched.epistemic_state != "defensively_recalled"
            {
                enriched.epistemic_state = "candidate".to_string();
            }
            enriched
        }
    }
}

/// A connection checked out from the pool. Derefs to `rusqlite::Connection`, so
/// every existing `conn.prepare/execute/query_row/...` call works unchanged once
/// a method binds `let conn = self.conn()?;`. (#210)
