    #[test]
    fn court_ruling_reverse_reopens_the_pair() {
        let (db, path) = temp_db();
        let fp = "cafebabe";
        let (r1, _) = db
            .court_ruling_record(
                fp,
                "mem-winner",
                "mem-loser",
                "accept",
                "",
                "importance",
                "r",
                "smoke",
            )
            .expect("record");
        assert!(db.court_ruling_find_active(fp).unwrap().is_some());
        let rev = db
            .court_ruling_reverse(&r1["id"].as_str().unwrap(), "operator")
            .expect("reverse");
        assert_eq!(rev["status"], "reversed");
        assert!(
            db.court_ruling_find_active(fp).unwrap().is_none(),
            "pair reopened"
        );
        let (r2, created) = db
            .court_ruling_record(
                fp,
                "mem-other",
                "mem-loser",
                "accept",
                "",
                "importance",
                "r",
                "smoke",
            )
            .expect("re-record after reverse");
        assert!(created);
        assert_ne!(r1["id"], r2["id"]);
        let _ = std::fs::remove_file(path);
    }

