    #[test]
    fn authority_intent_rejections_are_self_explanatory() {
        let (db, path) = temp_db();
        db.agent_upsert("agent-aar-msg", "AAR Messages", 3, "perseus")
            .unwrap();
        let manifest = crate::models::AuthorityManifestInput {
            agent_id: "agent-aar-msg".to_string(),
            workspace_hash: "ws-aar-msg".to_string(),
            allowed_capabilities: vec!["git_push".to_string(), "issue_closure".to_string()],
            approval_required_capabilities: vec![],
            scope_anchors: vec!["Perseus-Computing-LLC/perseus".to_string()],
            approver_principals: vec![],
            allowed_inbound_principals: vec![],
            permitted_external_ref_prefixes: vec![
                "https://github.com/Perseus-Computing-LLC/perseus".to_string(),
            ],
            max_parallel_actions: 1,
            mode: "enforce".to_string(),
            expires_at_unix_ms: None,
            capability_constraints_json: "{}".to_string(),
        };
        let _ = db.authority_set(&manifest, "admin").unwrap();

        // Capability denial names the capability and lists the allowed set.
        let err = db
            .action_intent(
                "agent-aar-msg",
                "ws-aar-msg",
                "Perseus-Computing-LLC/perseus",
                "https://github.com/Perseus-Computing-LLC/perseus",
                "deploy",
                "act-1",
                &"a".repeat(64),
                Some("{}"),
                &[],
                None,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.to_string().contains("deploy"),
            "denial should name the capability: {err}"
        );
        assert!(
            err.to_string().contains("git_push"),
            "denial should list allowed capabilities: {err}"
        );

        // Anchor denial names the offending anchor, states exact-match
        // semantics, and lists the allowed anchors.
        let err = db
            .action_intent(
                "agent-aar-msg",
                "ws-aar-msg",
                "Perseus-Computing-LLC/perseus branch feat/x", // lookalike anchor
                "https://github.com/Perseus-Computing-LLC/perseus",
                "git_push",
                "act-2",
                &"a".repeat(64),
                Some("{}"),
                &[],
                None,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.to_string().contains("branch feat/x"),
            "denial should name the anchor: {err}"
        );
        assert!(
            err.to_string().contains("exactly"),
            "denial should state exact-match semantics: {err}"
        );
        assert!(
            err.to_string().contains("Perseus-Computing-LLC/perseus"),
            "denial should list allowed anchors: {err}"
        );

        // External-ref denial names the reference and lists the prefixes.
        let err = db
            .action_intent(
                "agent-aar-msg",
                "ws-aar-msg",
                "Perseus-Computing-LLC/perseus",
                "https://github.com/Other-Org/other",
                "git_push",
                "act-3",
                &"a".repeat(64),
                Some("{}"),
                &[],
                None,
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.to_string().contains("Other-Org"),
            "denial should name the reference: {err}"
        );
        assert!(
            err.to_string()
                .contains("https://github.com/Perseus-Computing-LLC/perseus"),
            "denial should list permitted prefixes: {err}"
        );

        // Exact anchor + permitted prefix passes without approval required.
        let ok = db
            .action_intent(
                "agent-aar-msg",
                "ws-aar-msg",
                "Perseus-Computing-LLC/perseus",
                "https://github.com/Perseus-Computing-LLC/perseus/pull/931",
                "git_push",
                "act-4",
                &"a".repeat(64),
                Some("{}"),
                &[],
                None,
            )
            .unwrap();
        assert_eq!(ok.status, "intent");
        assert!(!ok.approval_required);
        let _ = std::fs::remove_file(&path);
    }

    // ─── #1034: deterministic grounding verification ───

    #[test]
    fn grounding_admit_is_fail_closed_on_missing_entity_and_short_content() {
        let (db, _path) = temp_db();
        // Never invent node ids: anchoring a nonexistent entity is refused.
        let err = db
            .grounding_admit(
                "ws-g1",
                "no-such-entity",
                "/src/a.rs",
                "file",
                &"x".repeat(200),
            )
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("never invent node ids"),
            "unexpected error: {err}"
        );

        db.remember(&make_entity("e-g1", "evidence", "g1", r#"{"v":1}"#))
            .unwrap();
        // Fail-closed authoring rule: trustworthy ground facts unavailable.
        let err = db
            .grounding_admit("ws-g1", "e-g1", "/src/a.rs", "file", "tiny content")
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("insufficient_content"),
            "unexpected error: {err}"
        );

        // Bad kind refused.
        let err = db
            .grounding_admit("ws-g1", "e-g1", "/src/a.rs", "url", &"x".repeat(200))
            .unwrap_err()
            .to_string();
        assert!(err.contains("kind must be"), "unexpected error: {err}");
    }

    #[test]
    fn grounding_reconcile_detects_drift_moved_gone_ambiguous() {
        let (db, _path) = temp_db();
        db.remember(&make_entity("e-g2a", "evidence", "g2a", r#"{"v":1}"#))
            .unwrap();
        db.remember(&make_entity("e-g2b", "evidence", "g2b", r#"{"v":2}"#))
            .unwrap();
        db.remember(&make_entity("e-g2c", "evidence", "g2c", r#"{"v":3}"#))
            .unwrap();
        let content_x = "fn compute_total(items: &[u32]) -> u64 { items.iter().map(|i| *i as u64).sum() } // evidence body";
        let content_y = "fn unrelated_impl() -> String { let parts = vec![\"a\",\"b\",\"c\",\"d\"]; parts.join(\"-\") } // other file body";

        db.grounding_admit("ws-g2", "e-g2a", "/src/a.rs", "file", content_x)
            .unwrap();
        db.grounding_admit("ws-g2", "e-g2b", "/src/b.rs", "file", content_y)
            .unwrap();

        // All match -> ok.
        let report = db
            .grounding_reconcile(
                "ws-g2",
                &[
                    ("/src/a.rs".to_string(), content_x.to_string()),
                    ("/src/b.rs".to_string(), content_y.to_string()),
                ],
            )
            .unwrap();
        assert_eq!(report.checked, 2);
        assert_eq!(report.ok, 2);

        // In-place mutation -> drift.
        let mutated_x = format!("{content_x} // edited tail");
        let report = db
            .grounding_reconcile(
                "ws-g2",
                &[
                    ("/src/a.rs".to_string(), mutated_x.clone()),
                    ("/src/b.rs".to_string(), content_y.to_string()),
                ],
            )
            .unwrap();
        assert_eq!(report.drift, 1, "in-place change is drift, not moved");

        // Content moved from a.rs to b.rs: G1's baseline is found at b ->
        // MOVED auto-rewrites the anchor; G2's baseline is gone from b but
        // the target still exists with different content -> drift.
        let report = db
            .grounding_reconcile("ws-g2", &[("/src/b.rs".to_string(), content_x.to_string())])
            .unwrap();
        assert_eq!(report.moved, 1, "move must auto-migrate the anchor");
        assert_eq!(report.drift, 1, "other grounding sees changed content");
        let migrated = db
            .grounding_get("ws-g2", "e-g2a", "/src/b.rs")
            .unwrap()
            .expect("migrated grounding must live at the new target");
        assert_eq!(migrated.status, "ok");
        assert!(
            migrated.provenance_json.contains("moved"),
            "provenance trail must record the move: {}",
            migrated.provenance_json
        );

        // Nothing present -> gone (no plausible candidate).
        let report = db.grounding_reconcile("ws-g2", &[]).unwrap();
        assert_eq!(report.gone, 2);

        // Two equally strong candidates -> ambiguous (surface both).
        db.grounding_admit("ws-g2", "e-g2c", "/src/c.rs", "file", content_x)
            .unwrap();
        let report = db
            .grounding_reconcile(
                "ws-g2",
                &[
                    ("/src/d.rs".to_string(), content_x.to_string()),
                    ("/src/e.rs".to_string(), content_x.to_string()),
                ],
            )
            .unwrap();
        assert!(
            report.ambiguous >= 1,
            "two HI candidates must surface as ambiguous"
        );
        let conn = db.conn().unwrap();
        let candidates: String = conn
            .query_row(
                "SELECT candidates_json FROM grounding_fingerprints WHERE target_ref = '/src/c.rs'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert!(
            candidates.contains("/src/d.rs") && candidates.contains("/src/e.rs"),
            "candidates must list both: {candidates}"
        );
    }

    // ─── #1035: deterministic drift-check → repair → verify loop ───

    #[test]
    fn drift_check_scores_and_repair_loop_verifies() {
        let (db, _path) = temp_db();
        // Conflicting evidence values for the same keyed claim.
        db.remember(&make_entity(
            "e-d1",
            "evidence",
            "d1",
            r#"{"version":"2.23.0"}"#,
        ))
        .unwrap();
        db.remember(&make_entity(
            "e-d2",
            "evidence",
            "d2",
            r#"{"version":"2.22.1"}"#,
        ))
        .unwrap();
        // Dangling derived_from citation: link then archive the target.
        db.remember(&make_entity("e-d3", "evidence", "d3", r#"{"x":1}"#))
            .unwrap();
        db.remember(&make_entity("e-d4", "evidence", "d4", r#"{"z":1}"#))
            .unwrap();
        db.link("evidence", "d3", "e-d4", "derived_from").unwrap();
        db.forget("evidence", "d4", "test").unwrap();
        // Grounding gone (reconcile with an empty scan) + missing path.
        db.remember(&make_entity("e-d5", "evidence", "d5", r#"{"w":1}"#))
            .unwrap();
        let content = "fn grounded_fact() -> u64 { let v = vec![1,2,3,4,5,6]; v.iter().sum::<u64>() } // grounded";
        db.grounding_admit(
            "ws-drift",
            "e-d5",
            "/opt/data/nonexistent-grounding-file-xyz.rs",
            "file",
            content,
        )
        .unwrap();
        db.grounding_reconcile("ws-drift", &[]).unwrap();
        // A second, still-'ok' grounding whose path has since disappeared
        // (never reconciled) → PATH_EXISTENCE error.
        db.grounding_admit(
            "ws-drift",
            "e-d5",
            "/opt/data/another-missing-grounding-file.rs",
            "file",
            content,
        )
        .unwrap();
        // Stale entity (last accessed far in the past).
        db.remember(&make_entity("e-d6", "evidence", "d6", r#"{"y":1}"#))
            .unwrap();
        db.conn()
            .unwrap()
            .execute(
                "UPDATE entities SET last_accessed_unix_ms = 1 WHERE id = 'e-d6'",
                [],
            )
            .unwrap();

        let report = crate::drift_check::drift_check(&db, None, 90).unwrap();
        let codes: Vec<&str> = report.issues.iter().map(|i| i.code.as_str()).collect();
        assert!(codes.contains(&"REFERENCE_INTEGRITY"), "missing: {codes:?}");
        assert!(codes.contains(&"CROSS_FILE_CONFLICT"), "missing: {codes:?}");
        assert!(codes.contains(&"GROUNDING_STATUS"), "missing: {codes:?}");
        assert!(codes.contains(&"PATH_EXISTENCE"), "missing: {codes:?}");
        assert!(codes.contains(&"STALE_ENTITY"), "missing: {codes:?}");
        // errors: ref(1) + conflict(1) + grounding-gone(1) + path(1); warnings: stale(1)
        assert_eq!(report.errors, 4, "report: {report:?}");
        assert_eq!(report.warnings, 1);
        assert_eq!(report.health_score, 57, "score math: {report:?}");

        // Targeted repair: unlink dangling ref + acknowledge grounding;
        // conflicts/staleness/paths stay review-only.
        let repair = crate::drift_check::drift_repair(&db, None, 90).unwrap();
        assert_eq!(repair.before_score, 57);
        assert_eq!(repair.after_score, 77, "repair: {repair:?}");
        assert!(
            repair
                .repaired
                .iter()
                .any(|k| k.starts_with("REFERENCE_INTEGRITY:")),
            "repaired: {:?}",
            repair.repaired
        );
        assert!(
            repair
                .requires_review
                .iter()
                .any(|k| k.starts_with("CROSS_FILE_CONFLICT:")),
            "conflicts must be review-only: {:?}",
            repair.requires_review
        );
        assert!(
            repair
                .requires_review
                .iter()
                .any(|k| k.starts_with("STALE_ENTITY:")),
            "staleness must be review-only: {:?}",
            repair.requires_review
        );

        // Verify leg: the repaired store no longer reports the fixed issues.
        let after = crate::drift_check::drift_check(&db, None, 90).unwrap();
        assert!(
            !after.issues.iter().any(|i| i.code == "REFERENCE_INTEGRITY"),
            "dangling ref must be unlinked"
        );
        let links: String = db
            .conn()
            .unwrap()
            .query_row("SELECT links FROM entities WHERE id = 'e-d3'", [], |r| {
                r.get(0)
            })
            .unwrap();
        assert_eq!(links, "[]", "dangling citation removed: {links}");
        assert_eq!(after.health_score, repair.after_score);
    }

    // ─── #1033: compensation admission (fail-closed, stable reason codes) ───

    fn comp_manifest(
        agent: &str,
        ws: &str,
        caps: &[&str],
    ) -> crate::models::AuthorityManifestInput {
        crate::models::AuthorityManifestInput {
            agent_id: agent.to_string(),
            workspace_hash: ws.to_string(),
            allowed_capabilities: caps.iter().map(|s| s.to_string()).collect(),
            approval_required_capabilities: vec![],
            scope_anchors: vec!["trace-scope".to_string()],
            approver_principals: vec![],
            allowed_inbound_principals: vec![],
            permitted_external_ref_prefixes: vec!["trace-ref".to_string()],
            max_parallel_actions: 4,
            mode: "enforce".to_string(),
            expires_at_unix_ms: None,
            capability_constraints_json: "{}".to_string(),
        }
    }

    fn comp_intent(
        db: &Database,
        agent: &str,
        ws: &str,
        capability: &str,
        action_key: &str,
        linkage: Option<crate::models::CompensationLinkage>,
    ) -> Result<AuthorizedAction, Box<dyn std::error::Error>> {
        db.action_intent(
            agent,
            ws,
            "trace-scope",
            "trace-ref",
            capability,
            action_key,
            &"c".repeat(64),
            Some("{}"),
            &[],
            linkage.as_ref(),
        )
    }

    fn execute_effect(db: &Database, agent: &str, ws: &str, key: &str) -> AuthorizedAction {
        let action = comp_intent(db, agent, ws, "execute_action", key, None).unwrap();
        db.action_complete(&action.id, agent, "executed", &"d".repeat(64))
            .unwrap()
    }

    #[test]
    fn compensation_requires_authenticated_finding_linkage() {
        let (db, _path) = temp_db();
        db.agent_upsert("agent-comp-a", "Trace", 3, "trace")
            .unwrap();
        db.authority_set(
            &comp_manifest("agent-comp-a", "ws-comp", &["execute_action"]),
            "admin",
        )
        .unwrap();
        let effect = execute_effect(&db, "agent-comp-a", "ws-comp", "effect-E");

        // Self-claimed undo: compensates_for without finding linkage.
        let err = comp_intent(
            &db,
            "agent-comp-a",
            "ws-comp",
            "execute_action",
            "undo-1",
            Some(crate::models::CompensationLinkage {
                compensates_for: effect.id.clone(),
                ..Default::default()
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("compensation_requires_finding_linkage"),
            "unexpected error: {err}"
        );

        // Forged finding reference.
        let err = comp_intent(
            &db,
            "agent-comp-a",
            "ws-comp",
            "execute_action",
            "undo-2",
            Some(crate::models::CompensationLinkage {
                compensates_for: effect.id.clone(),
                finding_ref: "fnd-forged".to_string(),
                superseding_head: "head-0001".to_string(),
                ..Default::default()
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("finding_unauthenticated"),
            "unexpected error: {err}"
        );

        // Original effect must exist.
        let err = comp_intent(
            &db,
            "agent-comp-a",
            "ws-comp",
            "execute_action",
            "undo-3",
            Some(crate::models::CompensationLinkage {
                compensates_for: "act-nonexistent".to_string(),
                finding_ref: "fnd-any".to_string(),
                superseding_head: "head-0001".to_string(),
                ..Default::default()
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("original_effect_not_found"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn compensation_verifies_finding_coverage_and_head() {
        let (db, _path) = temp_db();
        db.agent_upsert("agent-comp-b", "Trace", 3, "trace")
            .unwrap();
        db.authority_set(
            &comp_manifest("agent-comp-b", "ws-comp", &["execute_action"]),
            "admin",
        )
        .unwrap();
        let effect = execute_effect(&db, "agent-comp-b", "ws-comp", "effect-E");

        // A finding that does NOT cover the effect.
        db.finding_record(
            "ws-comp",
            "agent-comp-b",
            "fnd-unrelated",
            "insight",
            "other",
            "",
            "head-0001",
            &[],
            "supersession",
        )
        .unwrap();
        let err = comp_intent(
            &db,
            "agent-comp-b",
            "ws-comp",
            "execute_action",
            "undo-4",
            Some(crate::models::CompensationLinkage {
                compensates_for: effect.id.clone(),
                finding_ref: "fnd-unrelated".to_string(),
                superseding_head: "head-0001".to_string(),
                ..Default::default()
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("finding_does_not_cover_effect"),
            "unexpected error: {err}"
        );

        // A valid finding with a mismatched presented head.
        db.finding_record(
            "ws-comp",
            "agent-comp-b",
            "fnd-covering",
            "insight",
            "fact",
            "",
            "head-superseding-0001",
            &[effect.id.clone()],
            "supersession",
        )
        .unwrap();
        let err = comp_intent(
            &db,
            "agent-comp-b",
            "ws-comp",
            "execute_action",
            "undo-5",
            Some(crate::models::CompensationLinkage {
                compensates_for: effect.id.clone(),
                finding_ref: "fnd-covering".to_string(),
                superseding_head: "head-wrong".to_string(),
                ..Default::default()
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("superseding_head_mismatch"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn compensation_requires_receipted_handoff_when_original_revoked() {
        let (db, _path) = temp_db();
        db.agent_upsert("agent-comp-c", "Trace", 3, "trace")
            .unwrap();
        db.authority_set(
            &comp_manifest(
                "agent-comp-c",
                "ws-comp",
                &["execute_action", "remediation_handoff"],
            ),
            "admin",
        )
        .unwrap();
        let manifest_a = db
            .authority_get("agent-comp-c", "ws-comp", false)
            .unwrap()
            .unwrap();
        let effect = execute_effect(&db, "agent-comp-c", "ws-comp", "effect-E");
        db.finding_record(
            "ws-comp",
            "agent-comp-c",
            "fnd-covering",
            "insight",
            "fact",
            "",
            "head-superseding-0001",
            &[effect.id.clone()],
            "supersession",
        )
        .unwrap();

        // A valid handoff: receipted under the revoker's still-active
        // authority, naming B as beneficiary and covering E.
        let handoff = db
            .action_intent(
                "agent-comp-c",
                "ws-comp",
                "trace-scope",
                "trace-ref",
                "remediation_handoff",
                "handoff-E",
                &"e".repeat(64),
                Some(&format!(
                    r#"{{"beneficiary_agent_id":"agent-comp-d","original_effects":["{}"]}}"#,
                    effect.id
                )),
                &[],
                None,
            )
            .unwrap();
        let handoff = db
            .action_complete(&handoff.id, "agent-comp-c", "executed", &"f".repeat(64))
            .unwrap();

        // Revoke the original grant.
        db.authority_revoke(&manifest_a.id, "operator", "trace revoke")
            .unwrap();

        // B holds current authority.
        db.agent_upsert("agent-comp-d", "Trace", 3, "trace")
            .unwrap();
        db.authority_set(
            &comp_manifest("agent-comp-d", "ws-comp", &["execute_action"]),
            "admin",
        )
        .unwrap();

        // B without a handoff -> rejected.
        let err = comp_intent(
            &db,
            "agent-comp-d",
            "ws-comp",
            "execute_action",
            "comp-1",
            Some(crate::models::CompensationLinkage {
                compensates_for: effect.id.clone(),
                finding_ref: "fnd-covering".to_string(),
                superseding_head: "head-superseding-0001".to_string(),
                ..Default::default()
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("requires_receipted_handoff"),
            "unexpected error: {err}"
        );

        // A nonexistent handoff receipt -> rejected.
        let err = comp_intent(
            &db,
            "agent-comp-d",
            "ws-comp",
            "execute_action",
            "comp-2",
            Some(crate::models::CompensationLinkage {
                compensates_for: effect.id.clone(),
                finding_ref: "fnd-covering".to_string(),
                superseding_head: "head-superseding-0001".to_string(),
                handoff_receipt_ref: "act-nonexistent".to_string(),
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("handoff_not_receipted"),
            "unexpected error: {err}"
        );

        // The revoked principal cannot compensate its own past effect:
        // no current action authority (authority is never inherited).
        let err = comp_intent(
            &db,
            "agent-comp-c",
            "ws-comp",
            "execute_action",
            "comp-3",
            Some(crate::models::CompensationLinkage {
                compensates_for: effect.id.clone(),
                finding_ref: "fnd-covering".to_string(),
                superseding_head: "head-superseding-0001".to_string(),
                handoff_receipt_ref: handoff.id.clone(),
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("no active authority manifest"),
            "unexpected error: {err}"
        );

        // The legitimate path: B cites E + finding + head + the receipted
        // handoff -> accepted, with the linkage stored on the row.
        let compensation = comp_intent(
            &db,
            "agent-comp-d",
            "ws-comp",
            "execute_action",
            "comp-4",
            Some(crate::models::CompensationLinkage {
                compensates_for: effect.id.clone(),
                finding_ref: "fnd-covering".to_string(),
                superseding_head: "head-superseding-0001".to_string(),
                handoff_receipt_ref: handoff.id.clone(),
            }),
        )
        .unwrap();
        assert_eq!(compensation.status, "intent");
        assert_eq!(compensation.compensates_for, effect.id);
        assert_eq!(compensation.finding_ref, "fnd-covering");
        assert_eq!(compensation.superseding_head, "head-superseding-0001");
        assert_eq!(compensation.handoff_receipt_ref, handoff.id);

        // The original effect receipt still verifies historically.
        let original = db.action_receipt_get(&effect.id).unwrap().unwrap();
        assert_eq!(original.status, "action_executed");
    }

    #[test]
    fn compensation_handoff_must_name_beneficiary_and_cover_effect() {
        let (db, _path) = temp_db();
        db.agent_upsert("agent-comp-e", "Trace", 3, "trace")
            .unwrap();
        db.authority_set(
            &comp_manifest(
                "agent-comp-e",
                "ws-comp",
                &["execute_action", "remediation_handoff"],
            ),
            "admin",
        )
        .unwrap();
        let manifest_a = db
            .authority_get("agent-comp-e", "ws-comp", false)
            .unwrap()
            .unwrap();
        let effect = execute_effect(&db, "agent-comp-e", "ws-comp", "effect-E");
        db.finding_record(
            "ws-comp",
            "agent-comp-e",
            "fnd-covering",
            "insight",
            "fact",
            "",
            "head-0001",
            &[effect.id.clone()],
            "supersession",
        )
        .unwrap();

        // Handoff naming a different beneficiary.
        let handoff_wrong_beneficiary = db
            .action_intent(
                "agent-comp-e",
                "ws-comp",
                "trace-scope",
                "trace-ref",
                "remediation_handoff",
                "handoff-E",
                &"e".repeat(64),
                Some(&format!(
                    r#"{{"beneficiary_agent_id":"agent-comp-other","original_effects":["{}"]}}"#,
                    effect.id
                )),
                &[],
                None,
            )
            .unwrap();
        let handoff_wrong_beneficiary = db
            .action_complete(
                &handoff_wrong_beneficiary.id,
                "agent-comp-e",
                "executed",
                &"f".repeat(64),
            )
            .unwrap();

        // Handoff that does not cover the effect.
        let handoff_wrong_cover = db
            .action_intent(
                "agent-comp-e",
                "ws-comp",
                "trace-scope",
                "trace-ref",
                "remediation_handoff",
                "handoff-other",
                &"e".repeat(64),
                Some(r#"{"beneficiary_agent_id":"agent-comp-f","original_effects":["act-other"]}"#),
                &[],
                None,
            )
            .unwrap();
        let handoff_wrong_cover = db
            .action_complete(
                &handoff_wrong_cover.id,
                "agent-comp-e",
                "executed",
                &"f".repeat(64),
            )
            .unwrap();

        // An intent-status (not executed) handoff.
        let handoff_not_executed = db
            .action_intent(
                "agent-comp-e",
                "ws-comp",
                "trace-scope",
                "trace-ref",
                "remediation_handoff",
                "handoff-pending",
                &"e".repeat(64),
                Some(&format!(
                    r#"{{"beneficiary_agent_id":"agent-comp-f","original_effects":["{}"]}}"#,
                    effect.id
                )),
                &[],
                None,
            )
            .unwrap();

        db.authority_revoke(&manifest_a.id, "operator", "trace revoke")
            .unwrap();
        db.agent_upsert("agent-comp-f", "Trace", 3, "trace")
            .unwrap();
        db.authority_set(
            &comp_manifest("agent-comp-f", "ws-comp", &["execute_action"]),
            "admin",
        )
        .unwrap();

        let linkage_base = crate::models::CompensationLinkage {
            compensates_for: effect.id.clone(),
            finding_ref: "fnd-covering".to_string(),
            superseding_head: "head-0001".to_string(),
            handoff_receipt_ref: String::new(),
        };

        let err = comp_intent(
            &db,
            "agent-comp-f",
            "ws-comp",
            "execute_action",
            "comp-1",
            Some(crate::models::CompensationLinkage {
                handoff_receipt_ref: handoff_wrong_beneficiary.id.clone(),
                ..linkage_base.clone()
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("handoff_beneficiary_mismatch"),
            "unexpected error: {err}"
        );

        let err = comp_intent(
            &db,
            "agent-comp-f",
            "ws-comp",
            "execute_action",
            "comp-2",
            Some(crate::models::CompensationLinkage {
                handoff_receipt_ref: handoff_wrong_cover.id.clone(),
                ..linkage_base.clone()
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("handoff_does_not_cover_effect"),
            "unexpected error: {err}"
        );

        let err = comp_intent(
            &db,
            "agent-comp-f",
            "ws-comp",
            "execute_action",
            "comp-3",
            Some(crate::models::CompensationLinkage {
                handoff_receipt_ref: handoff_not_executed.id.clone(),
                ..linkage_base.clone()
            }),
        )
        .unwrap_err()
        .to_string();
        assert!(
            err.contains("handoff_not_receipted"),
            "unexpected error: {err}"
        );
    }

