    #[test]
    fn decay_and_recall_never_resurrect_superseded_or_invalidated_history() {
        // Invariant guard (D5): superseded versions (D2) and conflict-invalidated
        // losers (D4) live in entity_history, which decay_tick and recall never
        // touch — so a history-only fact must never resurface. This locks in the
        // architecture so a future change that scanned entity_history in those
        // paths would fail here.
        let (db, path) = temp_db();

        // (a) D2 supersession: v1's unique token survives only in history.
        let v1 = make_entity(
            "e-d5a",
            "facts",
            "k",
            r#"{"note":"zylophone marker alpha unique"}"#,
        );
        db.remember(&v1).unwrap();
        let v2 = make_entity(
            "ignored",
            "facts",
            "k",
            r#"{"note":"completely replaced content beta"}"#,
        );
        db.remember(&v2).unwrap();
        assert_eq!(db.history_versions("facts", "k").unwrap().len(), 1);

        // (b) D4 invalidation: a low-certainty conflicting belief moved to history.
        let mut keep = make_entity(
            "keep-id",
            "beliefs",
            "keep",
            r#"{"note":"the moon orbits the earth roughly monthly"}"#,
        );
        keep.certainty = 0.9;
        remember_fixture(&db, &keep).unwrap();
        let mut drop_e = make_entity(
            "drop-id",
            "beliefs",
            "drop",
            r#"{"note":"qwertyx distinct sushi friday marker token"}"#,
        );
        drop_e.certainty = 0.1;
        db.remember(&drop_e).unwrap();
        let r = db
            .resolve_conflicts("beliefs", 0.4, 10, 0, 0.2, false)
            .unwrap();
        assert_eq!(r["resolved"], serde_json::json!(1));

        // Decay must run cleanly (it scans only live entities).
        db.decay_tick().unwrap();

        // Recall (keyword) for tokens that now live ONLY in history returns nothing.
        for token in ["zylophone", "qwertyx"] {
            let params = RecallParams {
                query: token.to_string(),
                limit: 20,
                ..RecallParams::default()
            };
            let hits = db.recall(&params).unwrap();
            assert!(
                hits.iter().all(|e| !e.body_json.contains(token)),
                "history-only content ({token}) must never resurface in recall"
            );
        }

        // The history rows survived decay intact.
        let conn = db.conn().unwrap();
        let hist_alpha: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM entity_history WHERE body_json LIKE '%zylophone%'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(hist_alpha, 1, "superseded version must remain in history");
        let hist_drop: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM entity_history WHERE body_json LIKE '%qwertyx%'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(hist_drop, 1, "invalidated loser must remain in history");
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn remember_creates_and_updates_entity() {
        let (db, path) = temp_db();

        let entity = make_entity(
            "mem-test-1",
            "decision",
            "use-postgres",
            r#"{"decision": "Use PostgreSQL"}"#,
        );
        let (id, action) = db.remember(&entity).unwrap();
        assert_eq!(action, "created");
        assert_eq!(id, "mem-test-1");

        // Verify retrieval
        let found = db.get_entity("decision", "use-postgres").unwrap();
        assert!(found.is_some());
        assert_eq!(
            found.unwrap().body_json,
            r#"{"decision": "Use PostgreSQL"}"#
        );

        // Update the same entity (idempotent)
        let mut updated = entity.clone();
        updated.body_json = r#"{"decision": "Use PostgreSQL 16"}"#.to_string();
        let (id2, action2) = db.remember(&updated).unwrap();
        assert_eq!(action2, "updated");
        assert_eq!(id2, "mem-test-1");

        let found2 = db.get_entity("decision", "use-postgres").unwrap();
        assert_eq!(
            found2.unwrap().body_json,
            r#"{"decision": "Use PostgreSQL 16"}"#
        );

        let _ = fs::remove_file(&path);
    }

    // #228: the lossless length prefilter must never change which entities are
    // treated as near-duplicates. We assert find_near_duplicate (prefilter on)
    // agrees with an exhaustive trigram scan (the un-prefiltered reference) for a
    // spread of probe bodies, including ones that exercise the short-candidate
    // prune path.
    #[test]
    fn find_near_duplicate_length_prefilter_matches_exhaustive_scan() {
        let (db, path) = temp_db();
        let threshold = 0.7;

        // Same-category corpus with deliberately varied body lengths.
        let bodies = [
            (
                "c1",
                r#"{"note":"the quick brown fox jumps over the lazy dog"}"#,
            ),
            (
                "c2",
                r#"{"note":"the quick brown fox jumps over the lazy cat"}"#,
            ),
            ("c3", r#"{"x":"tiny"}"#),
            (
                "c4",
                r#"{"note":"completely unrelated content about databases"}"#,
            ),
            (
                "c5",
                r#"{"note":"the quick brown fox jumps over the lazy dog!!"}"#,
            ),
        ];
        for (key, body) in bodies {
            db.remember(&make_entity(key, "insight", key, body))
                .unwrap();
        }

        // Some corpus bodies are near-duplicates of each other and so dedup on
        // insert; read back what actually landed rather than assuming all five.
        let stored: Vec<String> = {
            let conn = db.conn().unwrap();
            let mut stmt = conn
                .prepare(
                    "SELECT body_json FROM entities WHERE category = 'insight' AND archived = 0",
                )
                .unwrap();
            stmt.query_map([], |r| r.get::<_, String>(0))
                .unwrap()
                .map(|r| r.unwrap())
                .collect()
        };

        // Exhaustive reference: any stored same-category body whose trigram
        // similarity to the probe meets the threshold. This is exactly what
        // find_near_duplicate computes without the length prefilter.
        let reference_has_dup = |probe: &str| -> bool {
            stored
                .iter()
                .any(|b| Database::trigram_similarity(b, probe) >= threshold)
        };

        let probes = [
            r#"{"note":"the quick brown fox jumps over the lazy dog"}"#, // exact match
            r#"{"note":"the quick brown fox jumps over the lazy dog."}"#, // near match
            r#"{"x":"tiny"}"#,                                           // exact short match
            r#"{"y":"no"}"#,                                             // short, no match
            r#"{"note":"a totally different sentence with no overlap xyz"}"#, // long, no match
        ];
        for probe in probes {
            let got = db
                .find_near_duplicate("insight", "", probe, threshold)
                .unwrap()
                .is_some();
            assert_eq!(
                got,
                reference_has_dup(probe),
                "length prefilter changed dedup outcome for probe: {}",
                probe
            );
        }

        let _ = fs::remove_file(&path);
    }

    // v17 (#476): the lossy #228 FTS prefilter is retired — the signature-
    // driven scan is exact AND cheap, so the near-duplicate the prefilter
    // was documented to miss (one sharing no FTS token) is now found by the
    // one and only scan path. Both probe shapes pinned.
    #[test]
    fn find_near_duplicate_is_exact_without_prefilter_tradeoff() {
        let (db, path) = temp_db();
        let threshold = 0.7;

        // Token-sharing near-duplicate: the common case.
        db.remember(&make_entity(
            "f1",
            "insight",
            "f1",
            r#"{"content":"hello world foo bar"}"#,
        ))
        .unwrap();
        let token_sharing_probe = r#"{"content":"hello world foo baz"}"#;
        assert!(
            Database::trigram_similarity(
                r#"{"content":"hello world foo bar"}"#,
                token_sharing_probe
            ) >= threshold,
            "probe must be a genuine near-duplicate"
        );
        assert!(
            db.find_near_duplicate("insight", "", token_sharing_probe, threshold)
                .unwrap()
                .is_some(),
            "token-sharing near-duplicate must be found"
        );

        // No-shared-token near-duplicate: the whole body is a single token, so
        // a one-character difference yields disjoint FTS tokens despite >=0.7
        // trigram overlap — exactly the case the retired prefilter missed.
        db.remember(&make_entity("f2", "insight", "f2", "abcabcabcabc"))
            .unwrap();
        let no_shared_token_probe = "abcabcabcabd";
        assert!(
            Database::trigram_similarity("abcabcabcabc", no_shared_token_probe) >= threshold,
            "probe must be a genuine near-duplicate"
        );
        assert!(
            db.find_near_duplicate("insight", "", no_shared_token_probe, threshold)
                .unwrap()
                .is_some(),
            "the exact scan must find the no-shared-token near-duplicate the \
             retired FTS prefilter missed"
        );

        let _ = fs::remove_file(&path);
    }

    // ─── #392/#476: stored dedup signatures — equivalence proof ──────────
    //
    // The signature-driven scan (v17) must agree with the pre-#392 exhaustive
    // trigram-Jaccard scan on the VERDICT for every candidate: a probe matches
    // iff the exhaustive scan finds at least one qualifying row, and any id
    // the scan returns must be one the exhaustive scan would accept. (Which of
    // SEVERAL qualifying ids is returned follows signature-index order since
    // v17, so the ground truth is the match SET, not the first-match.)
    // `reference_match_set` below is the pre-#392 implementation kept verbatim
    // (same HashSet trigram rebuild, same length prefilter, same float
    // comparisons), collecting every qualifying id.

    fn reference_match_set(
        conn: &rusqlite::Connection,
        category: &str,
        workspace_hash: &str,
        body_json: &str,
        threshold: f64,
    ) -> std::collections::HashSet<String> {
        let mut out = std::collections::HashSet::new();
        if body_json.is_empty() {
            return out;
        }
        let target = Database::trigrams(body_json);
        let mut stmt = conn
            .prepare(
                "SELECT id, body_json FROM entities \
                 WHERE category = ?1 AND workspace_hash = ?2 AND archived = 0",
            )
            .unwrap();
        let rows = stmt
            .query_map(params![category, workspace_hash], |r| {
                Ok((r.get::<_, String>(0)?, r.get::<_, String>(1)?))
            })
            .unwrap();
        let target_len = target.len() as f64;
        for row in rows {
            let (id, existing_body) = row.unwrap();
            let sim = if existing_body.is_empty() {
                0.0
            } else if existing_body == body_json {
                1.0
            } else {
                let cand_max_trigrams = existing_body.chars().count().saturating_sub(2);
                if (cand_max_trigrams as f64) < threshold * target_len {
                    continue;
                }
                Database::trigram_overlap(&target, &Database::trigrams(&existing_body))
            };
            if sim >= threshold {
                out.insert(id);
            }
        }
        out
    }

    /// First-match reference for tests with a SINGLE possible match — where
    /// the set has at most one element and Option equality is the clearer
    /// assertion.
    fn reference_find_near_duplicate(
        conn: &rusqlite::Connection,
        category: &str,
        workspace_hash: &str,
        body_json: &str,
        threshold: f64,
    ) -> Option<String> {
        reference_match_set(conn, category, workspace_hash, body_json, threshold)
            .into_iter()
            .next()
    }

    /// Deterministic xorshift64* — no rand dependency in tests.
    struct XorShift(u64);
    impl XorShift {
        fn new(seed: u64) -> Self {
            XorShift(seed.wrapping_mul(2654435761).max(1))
        }
        fn next(&mut self) -> u64 {
            let mut x = self.0;
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            self.0 = x;
            x.wrapping_mul(0x2545F4914F6CDD1D)
        }
        fn below(&mut self, n: usize) -> usize {
            (self.next() % n.max(1) as u64) as usize
        }
    }

    const DEDUP_WORD_POOL: &[&str] = &[
        "alpha",
        "bravo",
        "charlie",
        "delta",
        "echo",
        "foxtrot",
        "golf",
        "hotel",
        "india",
        "juliet",
        "kilo",
        "lima",
        "mike",
        "november",
        "oscar",
        "papa",
        "quebec",
        "romeo",
        "café",
        "naïve",
        "日本語",
        "🌍",
        "données",
        "vault",
        "perseus",
        "memory",
        "trigram",
    ];

    fn dedup_random_body(rng: &mut XorShift, words: usize) -> String {
        let mut s = String::from("{\"note\":\"");
        for _ in 0..words {
            s.push_str(DEDUP_WORD_POOL[rng.below(DEDUP_WORD_POOL.len())]);
            s.push(' ');
        }
        s.push_str("\"}");
        s
    }

    /// `body` with `edits` random single-character substitutions.
    fn dedup_mutate(rng: &mut XorShift, body: &str, edits: usize) -> String {
        let mut chars: Vec<char> = body.chars().collect();
        if chars.is_empty() {
            return body.to_string();
        }
        for _ in 0..edits {
            let i = rng.below(chars.len());
            chars[i] = (b'a' + (rng.below(26) as u8)) as char;
        }
        chars.into_iter().collect()
    }

    /// Insert a row bypassing remember() entirely — the row gets NO stored
    /// signature, exercising the lazy rebuild-from-body path.
    fn dedup_raw_insert(conn: &rusqlite::Connection, id: &str, category: &str, body: &str) {
        conn.execute(
            "INSERT INTO entities (id, category, key, body_json, created_at_unix_ms, last_accessed_unix_ms)
             VALUES (?1, ?2, ?1, ?3, 0, 0)",
            params![id, category, body],
        )
        .unwrap();
        conn.execute(
            "INSERT INTO entities_fts (rowid, body_json)
             VALUES ((SELECT rowid FROM entities WHERE id = ?1), ?2)",
            params![id, body],
        )
        .unwrap();
    }

    // The randomized equivalence property: over corpora of clones, near-clones,
    // unrelated bodies, tiny bodies, unicode bodies and threshold-boundary
    // pairs — stored half via remember_skip_dedup (signature written in-tx)
    // and half via raw SQL, then signed by the v17 migration backfill exactly
    // as an upgraded store's rows are — the signature-driven scan must agree
    // with the pre-#392 exhaustive reference on every probe: Some iff the
    // reference match set is non-empty, and any returned id must be IN that
    // set (which member is returned follows signature-index order since v17).
    #[test]
    fn find_near_duplicate_signature_path_matches_exhaustive_scan_property() {
        // WAL fixture (#1031 follow-up, same class as #379/#400/#971): this
        // test runs remember_skip_dedup (read-decide-write) and raw-conn
        // inserts/reads on the same file concurrently. Under the
        // DELETE-journaling default a writer waiting for EXCLUSIVE starves
        // past busy_timeout while fresh SHARED readers keep arriving — the
        // documented "database is locked after busy_timeout" flake on
        // Windows CI (observed 2026-08-14). WAL lets the readers and writer
        // proceed concurrently; the test's dedup/property semantics are
        // unchanged.
        let (db, path) = temp_db_wal();
        let threshold = 0.7;
        let mut boundary_hits = 0usize;

        // Seed count is env-tunable so review/CI can run a wider sweep
        // (e.g. PERSEUS_VAULT_DEDUP_PROP_SEEDS=50) without slowing the default suite.
        let seeds: u64 = std::env::var("PERSEUS_VAULT_DEDUP_PROP_SEEDS")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(8);
        for seed in 0..seeds {
            let mut rng = XorShift::new(seed + 1);
            let category = format!("prop-{seed}");
            let conn = db.conn().unwrap();

            // Corpus: bases plus derived near-clones, tiny and unicode rows.
            let mut stored_bodies: Vec<String> = Vec::new();
            for w in [4usize, 8, 12, 20, 20, 32] {
                stored_bodies.push(dedup_random_body(&mut rng, w));
            }
            let base = stored_bodies[3].clone();
            stored_bodies.push(dedup_mutate(&mut rng, &base, 1)); // near-clone
            stored_bodies.push(dedup_mutate(&mut rng, &base, 6)); // farther clone
            stored_bodies.push(base.clone()); // exact clone of a stored row
            for tiny in ["", "a", "ab", "abc", "日本"] {
                stored_bodies.push(tiny.to_string());
            }
            for (i, body) in stored_bodies.iter().enumerate() {
                let id = format!("p{seed}-{i}");
                if i % 2 == 0 {
                    db.remember_skip_dedup(&make_entity(&id, &category, &id, body))
                        .unwrap();
                } else {
                    dedup_raw_insert(&conn, &id, &category, body);
                }
            }
            // Sign the raw rows the way an upgraded store's rows are signed:
            // the v17 migration backfill (roll the stamp back, re-run the
            // migration path). Post-v17, "every active row has a signature"
            // is an invariant the scan relies on — rows written behind the
            // engine's back between migrations are invisible to dedup by
            // documented design (see the raw-rows contract test below).
            conn.pragma_update(None, "user_version", 16i64).unwrap();
            crate::schema::initialize_schema(&conn).expect("v17 backfill must succeed");

            // Probes: exact copies, near-clones at varying edit distances,
            // unrelated bodies, tiny/unicode probes, and a boundary sweep
            // (progressively longer regenerated tails of a stored body).
            let mut probes: Vec<String> = Vec::new();
            probes.push(stored_bodies[0].clone());
            probes.push(String::new());
            probes.push("ab".to_string());
            probes.push("abc".to_string());
            probes.push("日本".to_string());
            probes.push(dedup_random_body(&mut rng, 24));
            for edits in [1usize, 2, 4, 8, 16] {
                probes.push(dedup_mutate(&mut rng, &base, edits));
            }
            let base_chars: Vec<char> = base.chars().collect();
            for keep_pct in [50usize, 60, 70, 75, 80, 85, 90, 95] {
                let keep = base_chars.len() * keep_pct / 100;
                let mut p: String = base_chars[..keep].iter().collect();
                while p.chars().count() < base_chars.len() {
                    p.push((b'a' + (rng.below(26) as u8)) as char);
                }
                probes.push(p);
            }

            for probe in &probes {
                // Count probes that land near the threshold, so the sweep is
                // provably exercising the decision boundary.
                if stored_bodies.iter().any(|b| {
                    let s = Database::trigram_similarity(b, probe);
                    (s - threshold).abs() < 0.05
                }) {
                    boundary_hits += 1;
                }
                // Twice: signature reads must be stable run-to-run (the scan
                // self-heals as it goes, so round 2 also proves the healing
                // wrote nothing that changes verdicts).
                for round in 0..2 {
                    let want = reference_match_set(&conn, &category, "", probe, threshold);
                    let got = db
                        .find_near_duplicate(&category, "", probe, threshold)
                        .unwrap();
                    match &got {
                        Some(id) => assert!(
                            want.contains(id),
                            "scan returned {id} which the exhaustive reference rejects \
                             (seed {seed}, round {round}) for probe: {probe:?}"
                        ),
                        None => assert!(
                            want.is_empty(),
                            "scan missed a genuine near-duplicate {want:?} \
                             (seed {seed}, round {round}) for probe: {probe:?}"
                        ),
                    }
                }
            }

            // The raw-inserted rows must have been signed by the v17
            // migration backfill, with signatures describing their stored
            // bodies exactly.
            for (i, body) in stored_bodies.iter().enumerate() {
                if i % 2 == 1 {
                    let id = format!("p{seed}-{i}");
                    let (blen, cnt, sig): (i64, i64, Vec<u8>) = conn
                        .query_row(
                            "SELECT s.body_len, s.tg_count, b.sig FROM dedup_signatures s \
                             JOIN dedup_signature_blobs b ON b.entity_id = s.entity_id \
                             WHERE s.entity_id = ?1",
                            params![id],
                            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
                        )
                        .unwrap_or_else(|e| panic!("raw row {id} must be backfilled: {e}"));
                    let rs = crate::dedup::build_row_signature(body);
                    assert_eq!((blen, cnt, sig), (rs.body_len, rs.tg_count, rs.sig));
                }
            }
        }

        assert!(
            boundary_hits > 0,
            "probe sweep never landed near the threshold — boundary untested"
        );
        let _ = fs::remove_file(&path);
    }

    // v17 (#476) contract: a row inserted behind the engine's back (direct
    // SQL, no signature) is INVISIBLE to the signature-driven scan until the
    // next migration backfill or a write through the engine re-signs it. The
    // pre-v17 scan lazily found+signed such rows at O(N·body_size) per write
    // for everyone; the documented trade is that a signature-unaware writer
    // now costs a benign missed dedup instead. Never a false positive.
    #[test]
    fn raw_rows_are_invisible_to_dedup_until_signed() {
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        let body = r#"{"note":"the quick brown fox jumps over the lazy dog"}"#;
        dedup_raw_insert(&conn, "raw-1", "note", body);

        // Invisible: even a byte-identical probe finds nothing.
        assert_eq!(db.find_near_duplicate("note", "", body, 0.7).unwrap(), None);

        // The migration backfill signs it; the same probe now matches.
        conn.pragma_update(None, "user_version", 16i64).unwrap();
        crate::schema::initialize_schema(&conn).expect("backfill");
        assert_eq!(
            db.find_near_duplicate("note", "", body, 0.7).unwrap(),
            Some("raw-1".to_string())
        );
        let _ = fs::remove_file(&path);
    }

    // #392: signatures are maintained through the write paths — written on
    // create, refreshed on update (describing the STORED value), and removed
    // when the entity row is deleted (FK cascade).
    #[test]
    fn dedup_signature_rows_track_create_update_delete() {
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();

        db.remember(&make_entity(
            "sig-e1",
            "note",
            "k1",
            r#"{"v":"first body content"}"#,
        ))
        .unwrap();
        let stored: String = conn
            .query_row(
                "SELECT body_json FROM entities WHERE id='sig-e1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        let (blen, cnt, sig): (i64, i64, Vec<u8>) = conn
            .query_row(
                "SELECT s.body_len, s.tg_count, b.sig FROM dedup_signatures s                  JOIN dedup_signature_blobs b ON b.entity_id = s.entity_id                  WHERE s.entity_id='sig-e1'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .expect("create must write a signature");
        let rs = crate::dedup::build_row_signature(&stored);
        assert_eq!((blen, cnt, sig), (rs.body_len, rs.tg_count, rs.sig));

        // Update (same key, new content): the signature must describe the NEW
        // stored body.
        db.remember(&make_entity(
            "sig-e1b",
            "note",
            "k1",
            r#"{"v":"completely different second body, much longer than before"}"#,
        ))
        .unwrap();
        let stored2: String = conn
            .query_row(
                "SELECT body_json FROM entities WHERE id='sig-e1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        let (blen2, cnt2, sig2): (i64, i64, Vec<u8>) = conn
            .query_row(
                "SELECT s.body_len, s.tg_count, b.sig FROM dedup_signatures s                  JOIN dedup_signature_blobs b ON b.entity_id = s.entity_id                  WHERE s.entity_id='sig-e1'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .expect("update must keep the signature row");
        let rs2 = crate::dedup::build_row_signature(&stored2);
        assert_eq!((blen2, cnt2, sig2), (rs2.body_len, rs2.tg_count, rs2.sig));

        // Delete cascades (pool connections run with foreign_keys=ON).
        conn.execute("DELETE FROM entities WHERE id='sig-e1'", [])
            .unwrap();
        let left: i64 = conn
            .query_row(
                "SELECT (SELECT COUNT(*) FROM dedup_signatures WHERE entity_id='sig-e1')                  + (SELECT COUNT(*) FROM dedup_signature_blobs WHERE entity_id='sig-e1')",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(left, 0, "entity delete must cascade to its signature");
        let _ = fs::remove_file(&path);
    }

    // #392: a STALE signature (body_len disagrees with the stored body) and a
    // MALFORMED signature blob must both fall back to the rebuild-from-body
    // path — same verdict as the reference — and be repaired in place.
    #[test]
    fn dedup_signature_stale_or_malformed_falls_back_and_repairs() {
        let (db, path) = temp_db();
        let threshold = 0.7;
        let conn = db.conn().unwrap();
        let body = r#"{"note":"the quick brown fox jumps over the lazy dog"}"#;
        let probe = r#"{"note":"the quick brown fox jumps over the lazy cat"}"#;
        db.remember_skip_dedup(&make_entity("st-1", "note", "st-1", body))
            .unwrap();
        assert!(
            Database::trigram_similarity(body, probe) >= threshold,
            "precondition: probe is a genuine near-duplicate"
        );

        // Stale: recorded length no longer matches the stored body.
        conn.execute(
            "UPDATE dedup_signatures SET body_len = body_len + 7 WHERE entity_id='st-1'",
            [],
        )
        .unwrap();
        assert_eq!(
            db.find_near_duplicate("note", "", probe, threshold)
                .unwrap(),
            reference_find_near_duplicate(&conn, "note", "", probe, threshold),
            "stale signature must not change the verdict"
        );
        let blen: i64 = conn
            .query_row(
                "SELECT body_len FROM dedup_signatures WHERE entity_id='st-1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(blen, body.len() as i64, "stale signature must be repaired");

        // Malformed: blob truncated so it cannot decode to tg_count elements.
        conn.execute(
            "UPDATE dedup_signature_blobs SET sig = X'80' WHERE entity_id='st-1'",
            [],
        )
        .unwrap();
        assert_eq!(
            db.find_near_duplicate("note", "", probe, threshold)
                .unwrap(),
            reference_find_near_duplicate(&conn, "note", "", probe, threshold),
            "malformed signature must not change the verdict"
        );
        let sig: Vec<u8> = conn
            .query_row(
                "SELECT sig FROM dedup_signature_blobs WHERE entity_id='st-1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            sig,
            crate::dedup::build_row_signature(body).sig,
            "malformed signature must be repaired"
        );
        let _ = fs::remove_file(&path);
    }

    // #392 review defect 1 (lazy-backfill flush race): a scan on connection A
    // rebuilds a signature for row X, but before A's write-back lands, a
    // remember() update rewrites X to a DIFFERENT body of the SAME byte
    // length and commits row + fresh signature atomically. A's stale flush
    // arrives LAST and must LOSE — an unconditional INSERT OR REPLACE would
    // overwrite the fresh signature with one describing the old body, and
    // with body_len still matching, the stale signature would be trusted
    // forever (no self-heal), silently changing dedup verdicts.
    #[test]
    fn dedup_sig_backfill_flush_loses_to_concurrent_rewrite() {
        let (db, path) = temp_db();
        let threshold = 0.7;
        let conn = db.conn().unwrap();
        // Same byte length, very different trigram content.
        let body_old = r#"{"note":"alpha bravo charlie delta echo foxtrot golf"}"#;
        let body_new = r#"{"memo":"zulu yankee xray whiskey victor uniform tan"}"#;
        assert_eq!(
            body_old.len(),
            body_new.len(),
            "precondition: same-length bodies"
        );

        db.remember_skip_dedup(&make_entity("race-1", "note", "race-k", body_old))
            .unwrap();
        // The interleaved update: rewrites the row to body_new, committing the
        // fresh signature in the same transaction.
        db.remember_skip_dedup(&make_entity("race-1b", "note", "race-k", body_new))
            .unwrap();

        // Connection A's delayed flush, carrying the signature it rebuilt
        // from the OLD body during its (now outdated) scan.
        Database::flush_dedup_sig_backfill(
            &conn,
            &[(
                "race-1".to_string(),
                crate::dedup::build_row_signature(body_old),
            )],
        );

        // The fresh signature must have survived.
        let sig: Vec<u8> = conn
            .query_row(
                "SELECT sig FROM dedup_signature_blobs WHERE entity_id='race-1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            sig,
            crate::dedup::build_row_signature(body_new).sig,
            "a stale delayed flush must not overwrite a fresh signature"
        );

        // And the verdict for a near-duplicate of the CURRENT body must match
        // the exhaustive reference (pre-fix: signature described body_old, so
        // the new path missed the near-duplicate the old scan finds).
        let probe = {
            let mut p: Vec<char> = body_new.chars().collect();
            let last = p.len() - 3;
            p[last] = 'q';
            p.into_iter().collect::<String>()
        };
        let want = reference_find_near_duplicate(&conn, "note", "", &probe, threshold);
        assert!(
            want.is_some(),
            "precondition: probe is a genuine near-duplicate"
        );
        assert_eq!(
            db.find_near_duplicate("note", "", &probe, threshold)
                .unwrap(),
            want,
            "verdict after a lost flush race must match the exhaustive scan"
        );
        let _ = fs::remove_file(&path);
    }

    // #392 review defect 2 (rollback safety), v17 (#476) contract: a
    // signature-unaware writer (rolled-back pre-v10 binary, direct SQL)
    // rewrites body_json in place, same byte length, signature untouched.
    // The verify-on-hit guard must guarantee two things:
    //   1. NEVER a false positive — a probe that matches the STALE signature
    //      but not the CURRENT body is rejected against the current body,
    //      and the encounter repairs the signature in place.
    //   2. After the repair (self-heal), probes match the current body again.
    // What v17 deliberately gives up: a probe matching the CURRENT body but
    // not the stale signature is missed until the row self-heals — the old
    // scan bought that case by hashing EVERY candidate body on EVERY write
    // (the #474 quadratic load curve). Missed dedup = one extra row; the
    // trade is pinned here.
    #[test]
    fn dedup_sig_hash_guard_catches_same_length_rewrite() {
        let (db, path) = temp_db();
        let threshold = 0.7;
        let conn = db.conn().unwrap();
        let body_old = r#"{"note":"alpha bravo charlie delta echo foxtrot golf"}"#;
        let body_new = r#"{"memo":"zulu yankee xray whiskey victor uniform tan"}"#;
        assert_eq!(
            body_old.len(),
            body_new.len(),
            "precondition: same-length bodies"
        );

        db.remember_skip_dedup(&make_entity("rb-1", "note", "rb-1", body_old))
            .unwrap();
        // Simulate the old binary: direct row rewrite, signature untouched.
        conn.execute(
            "UPDATE entities SET body_json = ?1 WHERE id = 'rb-1'",
            params![body_new],
        )
        .unwrap();

        // 1. A near-duplicate of the OLD body hits the stale signature; the
        //    verify-on-hit re-check against the CURRENT body must reject it
        //    (no false positive) and repair the signature.
        let old_probe = {
            let mut p: Vec<char> = body_old.chars().collect();
            let last = p.len() - 3;
            p[last] = 'q';
            p.into_iter().collect::<String>()
        };
        assert!(
            Database::trigram_similarity(body_old, &old_probe) >= threshold
                && Database::trigram_similarity(body_new, &old_probe) < threshold,
            "precondition: probe matches the stale signature only"
        );
        assert_eq!(
            db.find_near_duplicate("note", "", &old_probe, threshold)
                .unwrap(),
            None,
            "a stale signature must never produce a false positive"
        );
        let sig: Vec<u8> = conn
            .query_row(
                "SELECT sig FROM dedup_signature_blobs WHERE entity_id='rb-1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(
            sig,
            crate::dedup::build_row_signature(body_new).sig,
            "the verify-on-hit encounter must repair the stale signature"
        );

        // 2. Self-healed: a near-duplicate of the CURRENT body now matches,
        //    agreeing with the exhaustive reference.
        let new_probe = {
            let mut p: Vec<char> = body_new.chars().collect();
            let last = p.len() - 3;
            p[last] = 'q';
            p.into_iter().collect::<String>()
        };
        let want = reference_find_near_duplicate(&conn, "note", "", &new_probe, threshold);
        assert!(
            want.is_some(),
            "precondition: probe is a genuine near-duplicate"
        );
        assert_eq!(
            db.find_near_duplicate("note", "", &new_probe, threshold)
                .unwrap(),
            want,
            "verdicts must match the exhaustive scan once the row has self-healed"
        );
        let _ = fs::remove_file(&path);
    }

    // #392 + encryption: signatures derive from the STORED column value —
    // ciphertext when encryption is on. Two consequences pinned here: the
    // signature reveals nothing about the plaintext (it differs from the
    // plaintext-derived one), and dedup verdicts are UNCHANGED relative to
    // the pre-#392 scan (which compared the plaintext probe against stored
    // ciphertext and so effectively never matched — preserved, not "fixed").
    #[test]
    fn dedup_signatures_under_encryption_derive_from_ciphertext() {
        use crate::encryption::EncryptionManager;
        use std::io::Write;

        let (mut db, path) = temp_db();
        let key = EncryptionManager::generate_key();
        let key_path = std::env::temp_dir().join(format!(
            "perseus_vault-test-key-{}.key",
            uuid::Uuid::new_v4()
        ));
        let mut f = std::fs::File::create(&key_path).unwrap();
        f.write_all(key.as_bytes()).unwrap();
        drop(f);
        db.set_encryption(key_path.to_str().unwrap()).unwrap();

        let plain = r#"{"note":"the quick brown fox jumps over the lazy dog"}"#;
        let near = r#"{"note":"the quick brown fox jumps over the lazy cat"}"#;
        db.remember(&make_entity("enc-1", "note", "enc-1", plain))
            .unwrap();

        let conn = db.conn().unwrap();
        let stored: String = conn
            .query_row("SELECT body_json FROM entities WHERE id='enc-1'", [], |r| {
                r.get(0)
            })
            .unwrap();
        assert_ne!(stored, plain, "precondition: body is encrypted at rest");

        let (blen, cnt, sig): (i64, i64, Vec<u8>) = conn
            .query_row(
                "SELECT s.body_len, s.tg_count, b.sig FROM dedup_signatures s                  JOIN dedup_signature_blobs b ON b.entity_id = s.entity_id                  WHERE s.entity_id='enc-1'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .unwrap();
        let from_cipher = crate::dedup::build_row_signature(&stored);
        let from_plain = crate::dedup::build_row_signature(plain);
        assert_eq!(
            (blen, cnt, &sig),
            (from_cipher.body_len, from_cipher.tg_count, &from_cipher.sig)
        );
        assert_ne!(
            sig, from_plain.sig,
            "signature must not be derived from plaintext"
        );

        // Verdict equivalence on the encrypted store: for both a near-dup and
        // an exact plaintext re-send, new == reference (both effectively no
        // match — the historical encrypted-dedup behavior).
        for probe in [plain, near] {
            let want = reference_find_near_duplicate(&conn, "note", "", probe, 0.7);
            let got = db.find_near_duplicate("note", "", probe, 0.7).unwrap();
            assert_eq!(
                got, want,
                "encrypted-store verdict divergence for {probe:?}"
            );
        }

        let _ = std::fs::remove_file(&key_path);
        let _ = fs::remove_file(&path);
    }

    // ---- Encryption canary: fail-fast wrong-key detection at startup ----

    /// Write a freshly generated key to a temp file and return (path_string, b64).
    fn temp_key_file() -> (String, String) {
        use std::io::Write;
        let key = EncryptionManager::generate_key();
        let path = std::env::temp_dir().join(format!(
            "perseus_vault-canary-key-{}.key",
            uuid::Uuid::new_v4()
        ));
        let mut f = std::fs::File::create(&path).unwrap();
        f.write_all(key.as_bytes()).unwrap();
        drop(f);
        (path.to_str().unwrap().to_string(), key)
    }

    /// Regression: `encryption_storage_state()` used to test for the EXISTENCE
    /// of the `encryption_canary` table. The schema creates that table
    /// unconditionally, so every database — including a brand-new plaintext one
    /// — was reported as "encrypted", and `doctor` printed
    /// "[ENCRYPTED] AES-256-GCM canary present — bodies are ciphertext"
    /// over a database whose bodies were readable with plain `sqlite3`.
    #[test]
    fn storage_state_is_plaintext_until_a_canary_row_exists() {
        let (mut db, path) = temp_db();

        // Fresh DB: canary TABLE exists (schema), canary ROW does not.
        let table_exists: i64 = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='encryption_canary'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(table_exists, 1, "schema always creates the canary table");

        db.remember(&make_entity("s-1", "note", "s-1", r#"{"x":1}"#))
            .unwrap();
        assert_eq!(
            db.encryption_storage_state(),
            "plaintext",
            "an unencrypted database must not report itself as encrypted"
        );

        // Enabling encryption writes the canary row — only then "encrypted".
        let (key_path, _) = temp_key_file();
        db.set_encryption(&key_path).unwrap();
        assert_eq!(db.encryption_storage_state(), "encrypted");

        let _ = std::fs::remove_file(&key_path);
        drop(db);
        let _ = fs::remove_file(&path);
    }

