    #[test]
    fn wrong_key_still_rejected_on_legacy_rebrand_canary() {
        let (mut db, path) = temp_db();
        let (key_a, _) = temp_key_file();
        db.set_encryption(&key_a).unwrap();
        db.remember(&make_entity(
            "r-2",
            "note",
            "r-2",
            r#"{"vault":"pre-rebrand"}"#,
        ))
        .unwrap();
        rewrite_canary_to_legacy_rebrand_aad(&db, &key_a);
        drop(db);

        // A genuinely wrong key must STILL fail loudly: the legacy fallback
        // only accepts the key that authenticates the canary.
        let (key_b, _) = temp_key_file();
        let mut db2 = Database::open(&path).unwrap();
        let err = db2.set_encryption(&key_b).unwrap_err();
        assert!(
            err.contains("canary"),
            "wrong key must fail loudly on a legacy-rebrand canary, got: {err}"
        );
        let _ = std::fs::remove_file(&key_a);
        let _ = std::fs::remove_file(&key_b);
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn rekey_aad_migrates_legacy_rebrand_canary() {
        let (mut db, path) = temp_db();
        let (key_path, _) = temp_key_file();
        db.set_encryption(&key_path).unwrap();
        db.remember(&make_entity(
            "r-3",
            "note",
            "r-3",
            r#"{"vault":"pre-rebrand"}"#,
        ))
        .unwrap();
        rewrite_canary_to_legacy_rebrand_aad(&db, &key_path);

        // rekey-aad is the deliberate migration path: it must also bring the
        // canary onto the current AAD.
        let report = db.rekey_aad().unwrap();
        assert_eq!(report.0, 0, "entity rows were already on the current AAD");
        assert_eq!(report.1, 1, "the single entity row is already current");
        assert_eq!(report.2, 0, "nothing may fail to authenticate");
        assert_eq!(report.3, 1, "the legacy-rebrand canary must be migrated");

        // The canary must now authenticate under the CURRENT AAD alone.
        let enc = crate::encryption::EncryptionManager::from_key_file(&key_path).unwrap();
        let stored: String = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT ciphertext FROM encryption_canary WHERE id = 1",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert!(
            matches!(
                enc.decrypt_body(&stored, Database::canary_aad().as_bytes()),
                crate::encryption::BodyDecrypt::Plaintext(_)
            ),
            "migrated canary must authenticate under the current AAD"
        );

        // Idempotent: a second run must not re-migrate the canary.
        let report2 = db.rekey_aad().unwrap();
        assert_eq!(report2.0, 0);
        assert_eq!(report2.1, 1);
        assert_eq!(report2.2, 0);
        assert_eq!(
            report2.3, 0,
            "re-running rekey-aad must not re-migrate the canary"
        );
        let _ = std::fs::remove_file(&key_path);
        let _ = fs::remove_file(&path);
    }

    // #849: scoped rejected-value tombstones — db-level contract tests.
    #[test]
    fn rejected_value_does_not_flow_through_maintenance_derived_writes() {
        let (db, path) = temp_db();
        let rejected =
            r#"{"note":"the deployment uses postgres as the primary datastore rejected-source"}"#;
        let safe_a = r#"{"note":"the deployment uses postgres as the primary datastore safe-a"}"#;
        let safe_b = r#"{"note":"the deployment uses postgres as the primary datastore safe-b"}"#;
        let safe_c = r#"{"note":"the deployment uses postgres as the primary datastore safe-c"}"#;

        for (id, workspace, body) in [
            ("rejected-a", "ws-a", rejected),
            ("safe-a", "ws-a", safe_a),
            ("safe-b", "ws-b", safe_b),
            ("safe-c", "ws-c", safe_c),
        ] {
            let mut entity = make_entity(id, "facts", id, body);
            entity.workspace_hash = workspace.to_string();
            db.remember_skip_dedup(&entity)
                .expect("seed maintenance source");
        }

        db.reject_value(
            "ws-a",
            "rejected-a",
            "facts",
            rejected,
            "maintenance canary",
            "test:maintenance-canary",
            "test-agent",
            None,
        )
        .expect("record rejection");

        let mut laundering = make_entity("reingested-a", "facts", "reingested-a", rejected);
        laundering.workspace_hash = "ws-a".to_string();
        assert!(
            db.remember_skip_dedup(&laundering).is_err(),
            "a rejected value must remain blocked through another writer key"
        );

        let consolidate = crate::models::ConsolidateParams {
            category: "facts".to_string(),
            similarity_threshold: 0.3,
            limit: 50,
            offset: 0,
            dry_run: false,
            cold_first: false,
            archive_sources: false,
            workspace_hash: Some("ws-a".to_string()),
            global: false,
            requesting_agent_id: String::new(),
            refine_existing: true,
            quote_cap_chars: 512,
            force: false,
        };
        let consolidated = db.consolidate(&consolidate).expect("consolidate canary");
        assert_eq!(
            consolidated.observations_created, 0,
            "consolidation must not derive content from a rejected source"
        );

        let mut dream = dream_params("facts");
        dream.workspace_hash = Some("ws-a".to_string());
        let dreamed = db
            .dream_with_llm(&dream, &|prompt| {
                assert!(
                    !prompt.contains("rejected-source"),
                    "rejected source reached the dream prompt"
                );
                Ok(r#"{"insights":[]}"#.to_string())
            })
            .expect("dream canary");
        assert_eq!(
            dreamed.clusters_dreamed, 0,
            "dream must not cluster a rejected source"
        );

        let cohere = db
            .cohere(&crate::models::CohereParams {
                cross_scope_promote: true,
                cross_scope_k: 4,
                cross_scope_similarity: 0.3,
                max_links: 0,
                ..Default::default()
            })
            .expect("cohere canary");
        assert_eq!(
            cohere.cross_scope_clusters, 0,
            "cross-scope promotion must not generalize a rejected source"
        );

        drop(db);
        let _ = fs::remove_file(path.clone());
        let _ = fs::remove_file(format!("{path}.governance.db"));
    }

    #[test]
    fn rejected_value_tombstone_blocks_same_value_under_any_key_in_scope() {
        let (db, path) = temp_db();
        let body = r#"{"note":"db-level rejected body"}"#;
        db.reject_value(
            "ws-a",
            "subject-x",
            "convention",
            body,
            "user correction",
            "",
            "test-agent",
            None,
        )
        .unwrap();

        // Same (subject, predicate, value) in ws-a: blocked.
        let mut ent = make_entity("k1", "convention", "k1", body);
        ent.workspace_hash = "ws-a".to_string();
        let same = db.remember(&ent);
        assert!(same.is_err(), "same-key re-ingestion must be rejected");
        assert!(
            same.err().unwrap().to_string().contains("tombstone"),
            "error must name the tombstone"
        );

        // Different key, same value (laundering): still blocked.
        let mut ent2 = make_entity("k2", "convention", "k2", body);
        ent2.workspace_hash = "ws-a".to_string();
        let laundered = db.remember(&ent2);
        assert!(
            laundered.is_err(),
            "laundered write under a new key must be rejected"
        );

        // Different value, same key in ws-a: allowed.
        let mut ent3 = make_entity("k2", "convention", "k2", r#"{"note":"other"}"#);
        ent3.workspace_hash = "ws-a".to_string();
        let distinct = db.remember(&ent3);
        if !(distinct.is_ok()) {
            panic!("test assertion failed");
        };

        // Different predicate: allowed (the tombstone is scoped by predicate).
        let mut ent4 = make_entity("k3", "preference", "k3", body);
        ent4.workspace_hash = "ws-a".to_string();
        let other_pred = db.remember(&ent4);
        if !(other_pred.is_ok()) {
            panic!("test assertion failed");
        };

        // Trusted override writes through and leaves the tombstone in place.
        let mut ent5 = make_entity("k4", "convention", "k4", body);
        ent5.workspace_hash = "ws-a".to_string();
        let over = db.remember_with_options(&ent5, false, None, None, true);
        if !(over.is_ok()) {
            panic!("test assertion failed");
        };
        assert!(
            db.is_value_rejected("ws-a", "k4", "convention", body)
                .unwrap(),
            "tombstone must survive the override"
        );

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn rejected_value_tombstone_scopes_isolate_workspaces() {
        let (db, path) = temp_db();
        let body = r#"{"note":"workspace-scoped rejection"}"#;
        db.reject_value(
            "ws-a",
            "s",
            "convention",
            body,
            "rejected in ws-a only",
            "",
            "test-agent",
            None,
        )
        .unwrap();

        // Same value in a different workspace is not poisoned.
        let mut ent = make_entity("b1", "convention", "b1", body);
        ent.workspace_hash = "ws-b".to_string();
        let other = db.remember(&ent);
        if !(other.is_ok()) {
            panic!("test assertion failed");
        };

        // Same value in ws-a is blocked.
        let mut ent_a = make_entity("a1", "convention", "a1", body);
        ent_a.workspace_hash = "ws-a".to_string();
        let same = db.remember(&ent_a);
        if !(same.is_err()) {
            panic!("test assertion failed");
        };

        // A global tombstone (empty workspace) blocks every workspace.
        db.reject_value(
            "",
            "g",
            "convention",
            body,
            "global",
            "",
            "test-agent",
            None,
        )
        .unwrap();
        let mut ent_c = make_entity("c1", "convention", "c1", body);
        ent_c.workspace_hash = "ws-c".to_string();
        let global = db.remember(&ent_c);
        if !(global.is_err()) {
            panic!("test assertion failed");
        };

        let _ = fs::remove_file(&path);
    }

    /// #898: the batched suppression filter must return EXACTLY what the
    /// per-row reference implementation returns, across global/workspace/
    /// predicate-scoped tombstones, sidecar erasure mandates, expiry, and a
    /// multi-workspace candidate set.
    #[test]
    fn suppression_batched_matches_per_row_reference() {
        let (db, path) = temp_db();
        let bodies: Vec<String> = (0..6)
            .map(|i| format!(r#"{{"note":"eq-body-{i}"}}"#))
            .collect();
        // (workspace, category, body-index) per entity.
        let spec = [
            ("ws-a", "cat-x", 0),
            ("ws-a", "cat-y", 1),
            ("ws-b", "cat-x", 2),
            ("ws-b", "cat-y", 3),
            ("ws-a", "cat-x", 4),
            ("ws-c", "cat-z", 5),
        ];
        let mut entities = Vec::new();
        for (i, (ws, cat, bi)) in spec.iter().enumerate() {
            let mut e = make_entity(&format!("key-{i}"), cat, &format!("k{i}"), &bodies[*bi]);
            e.workspace_hash = ws.to_string();
            db.remember(&e).unwrap();
            entities.push(e);
        }
        // Tombstones: global, workspace-scoped, predicate-scoped,
        // workspace+predicate-scoped, and expired (far in the past so
        // now_ms() drift cannot flip it).
        db.reject_value("", "g", "", &bodies[0], "global", "", "t", None)
            .unwrap();
        db.reject_value("ws-a", "k", "", &bodies[1], "ws", "", "t", None)
            .unwrap();
        db.reject_value("", "k", "cat-x", &bodies[2], "cat", "", "t", None)
            .unwrap();
        db.reject_value("ws-b", "k", "cat-y", &bodies[3], "ws+cat", "", "t", None)
            .unwrap();
        db.reject_value(
            "ws-a",
            "k",
            "",
            &bodies[4],
            "expired",
            "",
            "t",
            Some(now_ms() - 100_000),
        )
        .unwrap();
        // Sidecar erasure mandates: global (body5) and ws-a-scoped (body0 —
        // already tombstoned globally; same outcome).
        db.assert_erasure(&bodies[5], "", "erased-global", "")
            .unwrap();
        db.assert_erasure(&bodies[0], "", "erased-ws-a", "ws-a")
            .unwrap();

        // Per-row reference oracle.
        let conn = db.conn().unwrap();
        let now = now_ms();
        let expected: Vec<&Entity> = entities
            .iter()
            .filter(|e| !db.entity_suppressed_with_conn(&conn, e, now).unwrap())
            .collect();
        // Only entity 4 (expired tombstone) survives.
        assert_eq!(expected.len(), 1, "oracle: exactly one survivor");
        assert_eq!(expected[0].key, "k4");

        // Batched path must agree exactly (content AND order).
        let got = db.filter_suppressed(entities.clone()).unwrap();
        let got_keys: Vec<String> = got.iter().map(|e| e.key.clone()).collect();
        let exp_keys: Vec<String> = expected.iter().map(|e| e.key.clone()).collect();
        assert_eq!(got_keys, exp_keys);

        // Scored variant agrees too.
        let scored: Vec<(Entity, f64)> = entities
            .iter()
            .cloned()
            .enumerate()
            .map(|(i, e)| (e, i as f64))
            .collect();
        let got_s = db.filter_suppressed_scored(scored).unwrap();
        assert_eq!(got_s.len(), 1);
        assert_eq!(got_s[0].0.key, "k4");

        let _ = fs::remove_file(&path);
    }

    /// #898: chunk boundaries (512 per IN-list) must not change results.
    #[test]
    fn suppression_batched_chunk_boundaries_match_reference() {
        let (db, path) = temp_db();
        // 1300 entities in ONE (ws, cat) pair → three IN-chunks (512/512/276).
        let mut entities = Vec::new();
        for i in 0..1300 {
            let body = format!(r#"{{"note":"chunk-{i}"}}"#);
            let mut e = make_entity(&format!("ck-{i}"), "cat-x", &format!("c{i}"), &body);
            e.workspace_hash = "ws-a".to_string();
            db.remember(&e).unwrap();
            entities.push(e);
        }
        // Suppress one body in chunk 2 (index 700) and one in chunk 3 (1299).
        db.reject_value(
            "ws-a",
            "k",
            "cat-x",
            &format!(r#"{{"note":"chunk-700"}}"#),
            "r",
            "",
            "t",
            None,
        )
        .unwrap();
        db.reject_value(
            "ws-a",
            "k",
            "cat-x",
            &format!(r#"{{"note":"chunk-1299"}}"#),
            "r",
            "",
            "t",
            None,
        )
        .unwrap();
        let conn = db.conn().unwrap();
        let now = now_ms();
        let expected: Vec<String> = entities
            .iter()
            .filter(|e| !db.entity_suppressed_with_conn(&conn, e, now).unwrap())
            .map(|e| e.key.clone())
            .collect();
        assert_eq!(expected.len(), 1298);
        let got: Vec<String> = db
            .filter_suppressed(entities)
            .unwrap()
            .into_iter()
            .map(|e| e.key)
            .collect();
        assert_eq!(got, expected);
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn rejected_value_tombstone_normalization_and_expiry() {
        let (db, path) = temp_db();
        db.reject_value(
            "ws-a",
            "s",
            "convention",
            r#"{"note": "ALWAYS  Use  X"}"#,
            "reject",
            "",
            "test-agent",
            None,
        )
        .unwrap();

        // Case/whitespace/JSON-formatting variants of the value are equivalent.
        for (i, variant) in [
            r#"{"note": "always use x"}"#,
            "{ \"note\": \"always use x\" }",
            r#"{"note":  "ALWAYS USE X"}"#,
        ]
        .iter()
        .enumerate()
        {
            let mut ent = make_entity(&format!("v{i}"), "convention", &format!("v{i}"), variant);
            ent.workspace_hash = "ws-a".to_string();
            let r = db.remember(&ent);
            assert!(
                r.is_err(),
                "normalized-equivalent variant must be blocked: {variant}"
            );
        }

        // An expired tombstone is ignored (and lazily removed).
        let now = now_ms();
        db.reject_value(
            "ws-a",
            "s2",
            "convention",
            r#"{"note":"expiring value"}"#,
            "reject with horizon",
            "",
            "test-agent",
            Some(now - 1000),
        )
        .unwrap();
        let mut ent_e = make_entity("e", "convention", "e", r#"{"note":"expiring value"}"#);
        ent_e.workspace_hash = "ws-a".to_string();
        let after_expiry = db.remember(&ent_e);
        if !(after_expiry.is_ok()) {
            panic!("test assertion failed");
        };

        // The expired row is lazily purged on the next lookup.
        db.is_value_rejected("ws-a", "e", "convention", "x")
            .unwrap();
        let remaining: i64 = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT COUNT(*) FROM rejected_value_tombstones WHERE subject='s2'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(remaining, 0, "expired tombstone must be lazily removed");

        let _ = fs::remove_file(&path);
    }

    // #392 perf regression bench (ignored; run explicitly). Compares the
    // stored-signature scan against the pre-#392 exhaustive reference on the
    // SAME store — same harness, same probes — and times the issue's
    // bulk-import scenario on the new path. Scale via PERSEUS_VAULT_DEDUP_BENCH_N /
    // PERSEUS_VAULT_DEDUP_BENCH_BULK. Numbers are medians over the probe set;
    // concurrent load on the host makes single runs noisy.
    #[test]
    #[ignore]
    fn bench_dedup_scan_stored_signatures_vs_exhaustive() {
        use std::time::Instant;

        let n: usize = std::env::var("PERSEUS_VAULT_DEDUP_BENCH_N")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(10_000);
        let bulk: usize = std::env::var("PERSEUS_VAULT_DEDUP_BENCH_BULK")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(1_000);
        let (mut db, path) = temp_db();
        // Isolate the dedup scan: auto-embed on write is a per-insert ONNX
        // model run (several ms) that would swamp what this bench measures.
        // The issue's baselines were likewise embedding-free.
        db.embedding_config.enabled = false;
        let mut rng = XorShift::new(4242);

        // ~1KB bodies of uniform length — the length prefilter's worst case —
        // with a diverse trigram space (random letter words, like real prose;
        // the small word pool the property test uses would make every pair
        // hover near the threshold, which is not the bulk-import shape).
        let kb_body = |rng: &mut XorShift| -> String {
            let mut s = String::from("{\"note\":\"");
            while s.len() < 990 {
                let wlen = 3 + rng.below(6);
                for _ in 0..wlen {
                    s.push((b'a' + (rng.below(26) as u8)) as char);
                }
                s.push(' ');
            }
            s.truncate(998);
            s.push_str("\"}");
            s
        };

        let t0 = Instant::now();
        for i in 0..n {
            let body = kb_body(&mut rng);
            db.remember_skip_dedup(&make_entity(
                &format!("bench-{i}"),
                "bench",
                &format!("bench-{i}"),
                &body,
            ))
            .unwrap();
        }
        eprintln!("populate {n} rows: {:?}", t0.elapsed());

        let probes: Vec<String> = (0..15).map(|_| kb_body(&mut rng)).collect();
        let median = |mut v: Vec<f64>| -> f64 {
            v.sort_by(|a, b| a.partial_cmp(b).unwrap());
            v[v.len() / 2]
        };

        let conn = db.conn().unwrap();
        // Warm the page cache so both paths are measured hot.
        for p in probes.iter().take(3) {
            let _ = db.find_near_duplicate("bench", "", p, 0.7).unwrap();
            let _ = reference_find_near_duplicate(&conn, "bench", "", p, 0.7);
        }
        let mut new_ms = Vec::new();
        let mut old_ms = Vec::new();
        for p in &probes {
            let t = Instant::now();
            let got = db.find_near_duplicate("bench", "", p, 0.7).unwrap();
            new_ms.push(t.elapsed().as_secs_f64() * 1e3);
            let t = Instant::now();
            let want = reference_find_near_duplicate(&conn, "bench", "", p, 0.7);
            old_ms.push(t.elapsed().as_secs_f64() * 1e3);
            assert_eq!(got, want);
        }
        let new_med = median(new_ms.clone());
        let old_med = median(old_ms.clone());
        eprintln!(
            "single-insert dedup scan @{n} rows (1KB uniform bodies): \
             signature path median {new_med:.2}ms (min {:.2} max {:.2}), \
             exhaustive reference median {old_med:.2}ms (min {:.2} max {:.2}), {:.1}x",
            new_ms.iter().cloned().fold(f64::MAX, f64::min),
            new_ms.iter().cloned().fold(0.0, f64::max),
            old_ms.iter().cloned().fold(f64::MAX, f64::min),
            old_ms.iter().cloned().fold(0.0, f64::max),
            old_med / new_med.max(1e-9),
        );

        // Bulk import (the issue's headline scenario): M unique remember()
        // calls into one category of a FRESH store (the scan walks the
        // archived=0 partition, so a shared store would charge this phase for
        // the phase-1 corpus too). New path always; the pre-#392 path is
        // emulated (reference scan before each insert) only at small M — it
        // is quadratic, which is the point of the issue.
        let (mut bdb, bpath) = temp_db();
        bdb.embedding_config.enabled = false;
        let t0 = Instant::now();
        for i in 0..bulk {
            let body = kb_body(&mut rng);
            bdb.remember(&make_entity(
                &format!("bulk-{i}"),
                "bulkbench",
                &format!("bulk-{i}"),
                &body,
            ))
            .unwrap();
        }
        eprintln!(
            "bulk import {bulk} inserts (dedup ON, fresh store, NEW path): {:?} total, {:.2}ms/insert avg",
            t0.elapsed(),
            t0.elapsed().as_secs_f64() * 1e3 / bulk as f64
        );
        let _ = fs::remove_file(&bpath);

        if bulk <= 1500 {
            let (mut odb, opath) = temp_db();
            odb.embedding_config.enabled = false;
            let oconn = odb.conn().unwrap();
            let t0 = Instant::now();
            for i in 0..bulk {
                let body = kb_body(&mut rng);
                let dup = reference_find_near_duplicate(&oconn, "bulkbench", "", &body, 0.7);
                if dup.is_none() {
                    odb.remember_skip_dedup(&make_entity(
                        &format!("bulk-{i}"),
                        "bulkbench",
                        &format!("bulk-{i}"),
                        &body,
                    ))
                    .unwrap();
                }
            }
            eprintln!(
                "bulk import {bulk} inserts (dedup ON, fresh store, OLD-path emulation): {:?} total, {:.2}ms/insert avg",
                t0.elapsed(),
                t0.elapsed().as_secs_f64() * 1e3 / bulk as f64
            );
            let _ = fs::remove_file(&opath);
        }

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn recall_with_category_filter() {
        let (db, path) = temp_db();

        let e1 = make_entity("e1", "decision", "use-pg", r#"{"d": "pg"}"#);
        let e2 = make_entity("e2", "architecture", "app-stack", r#"{"a": "stack"}"#);
        db.remember(&e1).unwrap();
        db.remember(&e2).unwrap();

        // Recall with category filter
        let params = RecallParams {
            category: Some("decision".to_string()),
            limit: 10,
            ..RecallParams::default()
        };
        let results = db.recall(&params).unwrap();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].category, "decision");

        // Recall without filter
        let params2 = RecallParams::default();
        let results2 = db.recall(&params2).unwrap();
        assert_eq!(results2.len(), 2);

        let _ = fs::remove_file(&path);
    }

    // ─── #562: deterministic keyset enumeration ──────────────────────────
    // scan_entities must walk a whole category exactly once via the id
    // cursor, even while reinforcing recalls mutate the ranking keys
    // (retrieval_count / last_accessed) that make recall's offset paging
    // skip or repeat rows. Also pins the scope rules: archived rows are
    // excluded unless requested, and workspace_hash keeps the strict #408
    // semantics (Some("") = only global rows).
    #[test]
    fn scan_entities_enumerates_exactly_once_with_cursor() {
        let (db, path) = temp_db();

        for i in 0..25 {
            let e = make_entity(
                &format!("scan-{:02}", i),
                "scan-cat",
                &format!("k{:02}", i),
                &format!(r#"{{"d": "unique scan body row {} filler {}"}}"#, i, i * 31),
            );
            db.remember_skip_dedup(&e).unwrap();
        }
        // Out-of-scope rows: another category, another workspace, archived.
        db.remember_skip_dedup(&make_entity(
            "other-1",
            "other-cat",
            "ok",
            r#"{"d": "row in a different category entirely"}"#,
        ))
        .unwrap();
        let mut ws_row = make_entity(
            "scan-ws",
            "scan-cat",
            "kws",
            r#"{"d": "row scoped to a non-global workspace"}"#,
        );
        ws_row.workspace_hash = "ws-x".to_string();
        db.remember_skip_dedup(&ws_row).unwrap();
        db.remember_skip_dedup(&make_entity(
            "scan-arch",
            "scan-cat",
            "karch",
            r#"{"d": "archived row that default scans must skip"}"#,
        ))
        .unwrap();
        db.conn()
            .unwrap()
            .execute(
                "UPDATE entities SET archived = 1 WHERE id = 'scan-arch'",
                [],
            )
            .unwrap();

        // Page through the category (unscoped: 25 global + 1 ws-x = 26 live
        // rows), interleaving a reinforcing recall between every page.
        let mut seen: Vec<String> = Vec::new();
        let mut cursor: Option<String> = None;
        loop {
            let page = db
                .scan_entities(Some("scan-cat"), None, false, cursor.as_deref(), 10)
                .unwrap();
            let recall_params = RecallParams {
                category: Some("scan-cat".to_string()),
                limit: 10,
                ..RecallParams::default()
            };
            db.recall(&recall_params).unwrap();
            if page.is_empty() {
                break;
            }
            cursor = page.last().map(|e| e.id.clone());
            let short = (page.len() as i64) < 10;
            seen.extend(page.into_iter().map(|e| e.id));
            if short {
                break;
            }
        }
        assert_eq!(
            seen.len(),
            26,
            "every live in-category row exactly once: {seen:?}"
        );
        let unique: std::collections::HashSet<&String> = seen.iter().collect();
        assert_eq!(unique.len(), 26, "no row may repeat across pages: {seen:?}");
        let mut sorted = seen.clone();
        sorted.sort();
        assert_eq!(seen, sorted, "pages must be ordered by immutable id ASC");
        assert!(
            !seen.iter().any(|id| id == "scan-arch" || id == "other-1"),
            "archived and cross-category rows must not appear: {seen:?}"
        );

        // Strict workspace scoping: Some("") targets only the global rows.
        let global = db
            .scan_entities(Some("scan-cat"), Some(""), false, None, 1000)
            .unwrap();
        assert_eq!(global.len(), 25, "Some(\"\") = global rows only (#408)");

        // Public scans never materialize archived bodies, even when the
        // historical include_archived flag is supplied. Audit markers must be
        // queried through their dedicated terminal-audit surfaces.
        let with_archived = db
            .scan_entities(Some("scan-cat"), None, true, None, 1000)
            .unwrap();
        assert_eq!(with_archived.len(), 26);
        assert!(
            !with_archived.iter().any(|entity| entity.id == "scan-arch"),
            "include_archived must not re-expose archived bodies"
        );

        let _ = fs::remove_file(&path);
    }

    // #467: the semantic (Dense/Hybrid) recall paths must honor the `category`
    // filter just like the FTS path. dense_search/graph_expand rank without the
    // metadata predicates, so before retain_metadata_filters a category-scoped
    // Dense or Hybrid recall leaked cross-category hits.
    #[test]
    fn dense_and_hybrid_recall_apply_category_filter() {
        let (db, path) = temp_db();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let insert = |id: &str, category: &str, key: &str, emb: &[f32]| {
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, archived)
                     VALUES (?1, ?2, ?3, ?4, 'insight', 'active', 0, 0, 0, 1.0, 'working', ?5, 0)",
                    params![
                        id,
                        category,
                        key,
                        format!("{{\"k\":\"{}\"}}", key),
                        blob(emb)
                    ],
                )
                .unwrap();
        };
        // Two near-identical embeddings in different categories: a naive dense
        // ranking would surface both, so the category filter is what matters.
        insert("op-1", "opportunity", "grant", &[1.0, 0.0, 0.0]);
        insert("infra-1", "infrastructure", "server", &[0.99, 0.01, 0.0]);

        let q = vec![1.0f32, 0.0, 0.0];
        for mode in [
            crate::models::SearchMode::Dense,
            crate::models::SearchMode::Hybrid,
        ] {
            let params = RecallParams {
                query: "server grant".to_string(),
                category: Some("opportunity".to_string()),
                embedding: Some(q.clone()),
                mode: mode.clone(),
                limit: 10,
                ..RecallParams::default()
            };
            let results = db.recall(&params).unwrap();
            assert!(
                !results.is_empty(),
                "{:?}: category-scoped recall should still return the matching entity",
                mode
            );
            assert!(
                results.iter().all(|e| e.category == "opportunity"),
                "{:?}: recall must not leak other categories, got {:?}",
                mode,
                results
                    .iter()
                    .map(|e| e.category.clone())
                    .collect::<Vec<_>>()
            );
        }

        let _ = fs::remove_file(&path);
    }

    // #856: the bounded dense pool must not silently drop in-scope results —
    // the recall path adaptively over-fetches until `limit` in-scope hits are
    // found, the scan is known exhausted, or the pool ceiling is reached, and
    // reports exact/bounded/partial completeness + the candidate scope.
    fn seed_deep_scope_corpus(db: &Database, fillers_drown_hits: bool) -> (Vec<f32>, String) {
        // Direction-based similarity (cosine is scale-invariant, so scalar
        // magnitudes can't control rank). all-ones vectors score cos=1.0 vs
        // the query; half-positive vectors score cos=0.707.
        //   fillers_drown_hits=true  → 300 fillers (1.0) above 2 hits (0.707)
        //   fillers_drown_hits=false → 2 hits (1.0) above 300 fillers (0.707)
        let dim = 16usize;
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let all_ones: Vec<f32> = vec![1.0; dim];
        let half_pos: Vec<f32> = (0..dim)
            .map(|d| if d < dim / 2 { 1.0 } else { 0.0 })
            .collect();
        let (filler_v, hit_v) = if fillers_drown_hits {
            (all_ones.clone(), half_pos.clone())
        } else {
            (half_pos.clone(), all_ones.clone())
        };
        let conn = db.conn().unwrap();
        let tx = conn.unchecked_transaction().unwrap();
        {
            let mut stmt = tx
                .prepare(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, workspace_hash, archived)
                     VALUES (?1, 'insight', ?2, ?3, 'insight', 'active', 0, 0, 0,
                             1.0, 'working', ?4, ?5, 0)",
                )
                .unwrap();
            for i in 1..=300u32 {
                stmt.execute(params![
                    format!("filler-{:05}", i),
                    format!("filler-key-{:05}", i),
                    format!("{{\"k\":\"filler-key-{:05}\"}}", i),
                    blob(&filler_v),
                    "ws-other"
                ])
                .unwrap();
            }
            for (id, key) in [("hit-1", "hit-key-1"), ("hit-2", "hit-key-2")] {
                stmt.execute(params![
                    id,
                    key,
                    format!("{{\"k\":\"{key}\"}}"),
                    blob(&hit_v),
                    "ws-target"
                ])
                .unwrap();
            }
        }
        tx.commit().unwrap();
        (vec![1.0f32; dim], "hit-key-1".to_string())
    }

    #[test]
    fn chain_sensitive_recall_filters_before_visible_limit() {
        let (db, path) = temp_db();
        let dim = 16usize;
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let high = vec![1.0f32; dim];
        let low: Vec<f32> = (0..dim)
            .map(|index| if index < dim / 2 { 1.0 } else { 0.0 })
            .collect();
        let conn = db.conn().unwrap();
        let tx = conn.unchecked_transaction().unwrap();
        let mut stmt = tx
            .prepare(
                "INSERT INTO entities (id, category, key, body_json, type, status,
                    retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                    decay_score, layer, embedding, workspace_hash, archived)
                 VALUES (?1, 'insight', ?2, ?3, 'insight', 'active', 0, 0, 0,
                         1.0, 'working', ?4, 'ws-target', 0)",
            )
            .unwrap();
        for index in 0..4u32 {
            let key = format!("chain-b-{index}");
            let body = format!(
                "{{\"content\":\"red herring {index}\",\"source_chain\":{{\"schema_version\":1,\"chain_id\":\"chain-b\"}}}}"
            );
            stmt.execute(params![key, key, body, blob(&high)]).unwrap();
        }
        for index in 0..6u32 {
            let key = format!("chain-a-{index}");
            let body = format!(
                "{{\"content\":\"coherent record {index}\",\"source_chain\":{{\"schema_version\":1,\"chain_id\":\"chain-a\"}}}}"
            );
            stmt.execute(params![key, key, body, blob(&low)]).unwrap();
        }
        drop(stmt);
        tx.commit().unwrap();

        let (results, _completeness) = db
            .recall_with_completeness(&RecallParams {
                query: "lineage chain".to_string(),
                embedding: Some(high),
                mode: crate::models::SearchMode::Dense,
                limit: 1,
                workspace_hash: Some("ws-target".to_string()),
                skip_side_effects: true,
                ..RecallParams::default()
            })
            .unwrap();
        assert_eq!(results.len(), 1);
        assert!(
            results[0].key.starts_with("chain-a-"),
            "returned keys: {:?}",
            results
                .iter()
                .map(|entity| entity.key.clone())
                .collect::<Vec<_>>()
        );
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn dense_recall_adaptive_overfetch_finds_deep_scoped_hits() {
        // 300 closer fillers in ws-other drown the ws-target hits inside the
        // historical pool (limit*5 = 5). Adaptive over-fetch must expand the
        // pool until the scan is exhausted (302 rows < pool) and the in-scope
        // hits surface — with completeness=exact and the true population.
        let (db, path) = temp_db();
        let (query, hit_key) = seed_deep_scope_corpus(&db, true);

        let (results, rc) = db
            .recall_with_completeness(&RecallParams {
                query: "deep hit".to_string(),
                embedding: Some(query),
                mode: crate::models::SearchMode::Dense,
                limit: 1,
                workspace_hash: Some("ws-target".to_string()),
                skip_side_effects: true,
                ..RecallParams::default()
            })
            .unwrap();

        assert!(
            results.iter().any(|e| e.key == hit_key),
            "adaptive over-fetch must recover in-scope hits beyond the historical pool, got {:?}",
            results.iter().map(|e| e.key.clone()).collect::<Vec<_>>()
        );
        assert_eq!(
            rc.completeness,
            crate::models::Completeness::Exact,
            "scan exhausted at 302 embedded rows → exact"
        );
        let scope = rc.scope.expect("candidate scope reported");
        assert_eq!(scope.scanned, 302, "all embedded rows examined");
        assert_eq!(scope.embedded_population, Some(302));
        assert_eq!(scope.pool_bound, None, "no bound bit when exhausted");

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn dense_recall_bounded_completeness_when_pool_fills() {
        // In-scope hits rank at the TOP (fillers less similar): the first pass
        // fills `limit` but the scan is NOT exhausted — completeness=bounded,
        // pool bound and scanned count reported honestly.
        let (db, path) = temp_db();
        let (query, hit_key) = seed_deep_scope_corpus(&db, false);

        let (results, rc) = db
            .recall_with_completeness(&RecallParams {
                query: "top hit".to_string(),
                embedding: Some(query),
                mode: crate::models::SearchMode::Dense,
                limit: 1,
                workspace_hash: Some("ws-target".to_string()),
                skip_side_effects: true,
                ..RecallParams::default()
            })
            .unwrap();

        assert!(
            results.iter().any(|e| e.key == hit_key),
            "top-ranked in-scope hit must be returned"
        );
        assert_eq!(rc.completeness, crate::models::Completeness::Bounded);
        let scope = rc.scope.expect("candidate scope reported");
        assert_eq!(scope.scanned, 5, "one pass at the historical pool");
        assert_eq!(scope.pool_bound, Some(5));
        assert_eq!(
            scope.embedded_population, None,
            "population beyond the pool is unknown"
        );

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn hybrid_recall_reports_completeness_and_finds_deep_hits() {
        // Same deep corpus through the hybrid fusion (sparse arm finds
        // nothing: the query text matches no body/key; the dense arm governs).
        let (db, path) = temp_db();
        let (query, hit_key) = seed_deep_scope_corpus(&db, true);

        let (results, rc) = db
            .recall_with_completeness(&RecallParams {
                query: "deep hit".to_string(),
                embedding: Some(query),
                mode: crate::models::SearchMode::Hybrid,
                limit: 1,
                workspace_hash: Some("ws-target".to_string()),
                skip_side_effects: true,
                ..RecallParams::default()
            })
            .unwrap();

        assert!(
            results.iter().any(|e| e.key == hit_key),
            "hybrid adaptive over-fetch must recover deep in-scope hits, got {:?}",
            results.iter().map(|e| e.key.clone()).collect::<Vec<_>>()
        );
        assert_eq!(rc.completeness, crate::models::Completeness::Exact);
        assert_eq!(rc.scope.as_ref().map(|s| s.scanned), Some(302));

        let _ = fs::remove_file(&path);
    }

