    #[test]
    fn quantized_reindex_roundtrip_is_byte_lossless() {
        let (mut db, path) = temp_db();
        db.embedding_config.enabled = false;
        let dim = 384usize;
        let mut originals: Vec<(String, Vec<u8>)> = Vec::new();
        for i in 0..50 {
            let v = seeded_vec(i as u64 + 1, dim);
            let id = format!("qr-{i:04}");
            let blob: Vec<u8> = v.iter().flat_map(|f| f.to_le_bytes()).collect();
            insert_entity_with_embedding(&db, &id, &v, true);
            originals.push((id, blob));
        }
        assert_eq!(db.embedding_quant(), EmbeddingQuant::F32);

        // Migrate to bit.
        let report = db.reindex_embeddings(EmbeddingQuant::Bit).unwrap();
        assert_eq!(report["reindexed"], 50);
        assert_eq!(report["format_after"], "bit");
        assert_eq!(report["bytes_per_vector_after"], 49); // 1 tag + 48 sign bits
        assert_eq!(db.embedding_quant(), EmbeddingQuant::Bit);
        // Record mirrored.
        let stored: String = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT format FROM embedding_format WHERE id = 1",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(stored, "bit");
        // Snapshot holds every row's original bytes.
        let snap: i64 = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT COUNT(*) FROM entities_embedding_snapshot",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(snap, 50);
        // Blobs converted to tagged sign bits; emb_sig == payload (v18 invariant).
        let conn = db.conn().unwrap();
        for (id, _) in &originals {
            let blob: Vec<u8> = conn
                .query_row(
                    "SELECT embedding FROM entities WHERE id = ?1",
                    params![id],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(blob.len(), 1 + dim / 8);
            assert_eq!(blob[0], vector_quant::TAG_BIT);
            let sig: Vec<u8> = conn
                .query_row(
                    "SELECT emb_sig FROM entities WHERE id = ?1",
                    params![id],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(&blob[1..], &sig[..], "bit payload must equal emb_sig");
        }
        drop(conn);
        // Dense search still works in bit mode (query = the exact stored
        // vector of qr-0007, whose seed is i+1 = 8).
        let q = seeded_vec(8, dim);
        let top = db.dense_search(&q, 3).unwrap();
        assert!(
            top.iter().any(|(e, _)| e.id == "qr-0007"),
            "exact bit vector must rank in top-3 by Hamming"
        );
        assert!(!top.is_empty());

        // Rollback: restore is byte-lossless for every row that existed at
        // snapshot time.
        let restored = db.restore_embeddings_snapshot().unwrap();
        assert_eq!(restored["restored"], 50);
        assert_eq!(db.embedding_quant(), EmbeddingQuant::F32);
        let conn = db.conn().unwrap();
        for (id, orig_blob) in &originals {
            let now_blob: Vec<u8> = conn
                .query_row(
                    "SELECT embedding FROM entities WHERE id = ?1",
                    params![id],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(
                &now_blob, orig_blob,
                "restored embedding must be byte-identical to the original f32 blob"
            );
        }
        drop(conn);
        // Second migration reuses the snapshot (never overwrites).
        let report2 = db.reindex_embeddings(EmbeddingQuant::Bit).unwrap();
        assert_eq!(report2["snapshot_reused"], true);
        assert_eq!(report2["snapshot_rows"], 50);

        // int8 path: sizes and tag.
        let _ = db.restore_embeddings_snapshot().unwrap();
        let report3 = db.reindex_embeddings(EmbeddingQuant::Int8).unwrap();
        assert_eq!(report3["bytes_per_vector_after"], 1 + 4 + dim);
        let blob: Vec<u8> = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT embedding FROM entities WHERE id = 'qr-0007'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(blob[0], vector_quant::TAG_INT8);
        assert_eq!(blob.len(), 1 + 4 + dim);

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn quantized_reindex_refuses_lossy_paths() {
        let (mut db, path) = temp_db();
        db.embedding_config.enabled = false;
        let v = seeded_vec(1, 16);
        insert_entity_with_embedding(&db, "r1", &v, true);

        // float32 target is refused (quantization is lossy).
        assert!(db.reindex_embeddings(EmbeddingQuant::F32).is_err());
        // quantized → quantized is refused.
        db.reindex_embeddings(EmbeddingQuant::Bit).unwrap();
        assert!(db.reindex_embeddings(EmbeddingQuant::Int8).is_err());
        assert!(db.reindex_embeddings(EmbeddingQuant::Bit).is_err());
        // Restore works while the snapshot exists, then becomes impossible
        // once the operator drops it — but the store stays searchable.
        db.restore_embeddings_snapshot().unwrap();
        db.drop_embeddings_snapshot().unwrap();
        assert!(db.restore_embeddings_snapshot().is_err());
        // A fresh store that was never quantized has no snapshot either.
        let (mut db3, path3) = temp_db();
        db3.embedding_config.enabled = false;
        let v3 = seeded_vec(3, 16);
        insert_entity_with_embedding(&db3, "r3", &v3, true);
        assert!(db3.restore_embeddings_snapshot().is_err());
        // Everything still searchable after the failed/refused ops.
        let top = db.dense_search(&v, 1).unwrap();
        assert_eq!(top[0].0.id, "r1");
        let _ = fs::remove_file(&path);
        let _ = fs::remove_file(&path3);
    }

    #[test]
    fn quantized_write_format_follows_resolved_mode_and_ranks_by_hamming() {
        let (mut db, path) = temp_db();
        db.embedding_config.enabled = false;
        db.remember_skip_dedup(&make_entity(
            "qw-1",
            "insight",
            "qw-1",
            "{\"content\":\"qw-1\"}",
        ))
        .unwrap();
        let v = seeded_vec(42, 32);
        // Default: raw f32 blob.
        db.store_embedding("qw-1", &v).unwrap();
        assert_eq!(raw_embedding(&db, "qw-1").unwrap().len(), 32 * 4);
        // Migrate to bit, then a NEW write lands as tagged bits (in-process
        // mirror flips with the record).
        db.reindex_embeddings(EmbeddingQuant::Bit).unwrap();
        db.store_embedding("qw-1", &v).unwrap();
        let blob = raw_embedding(&db, "qw-1").unwrap();
        assert_eq!(blob[0], vector_quant::TAG_BIT);
        assert_eq!(blob.len(), 1 + 32 / 8);

        // Hamming ranking: exact vector beats a half-flipped cousin.
        db.remember_skip_dedup(&make_entity(
            "qw-2",
            "insight",
            "qw-2",
            "{\"content\":\"qw-2\"}",
        ))
        .unwrap();
        let mut cousin = v.clone();
        for i in 0..16 {
            cousin[i] = -cousin[i];
        }
        db.store_embedding("qw-2", &cousin).unwrap();
        let top = db.dense_search(&v, 2).unwrap();
        assert_eq!(top[0].0.id, "qw-1", "bit mode must rank by Hamming");
        assert_eq!(top[1].0.id, "qw-2");
        assert!(top[0].1 > top[1].1);
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn int8_mode_keeps_recall_parity_on_fixture_corpus() {
        let (mut db, path) = temp_db();
        db.embedding_config.enabled = false;
        let dim = 64usize;
        // 10 topic clusters × 4 members; the query is cluster-0's centroid
        // plus noise, so ground truth is the 4 cluster-0 members.
        let mut cluster0: Vec<Vec<f32>> = Vec::new();
        for c in 0..10 {
            let centroid = seeded_vec(1000 + c as u64, dim);
            let norm = centroid.iter().map(|x| x * x).sum::<f32>().sqrt().max(1e-6);
            let centroid: Vec<f32> = centroid.iter().map(|x| x / norm).collect();
            for m in 0..4 {
                // Member = centroid + 5% deterministic per-member noise.
                let noise = seeded_vec(2000 + c as u64 * 10 + m as u64, dim);
                let v: Vec<f32> = centroid
                    .iter()
                    .zip(noise.iter())
                    .map(|(c, n)| c + n * 0.05)
                    .collect();
                let norm = v.iter().map(|x| x * x).sum::<f32>().sqrt().max(1e-6);
                let v: Vec<f32> = v.iter().map(|x| x / norm).collect();
                let id = format!("ic-{c}-{m}");
                insert_entity_with_embedding(&db, &id, &v, true);
                if c == 0 {
                    cluster0.push(v);
                }
            }
        }
        let q = cluster0[0].clone();

        let f32_top: Vec<String> = db
            .dense_search(&q, 5)
            .unwrap()
            .into_iter()
            .map(|(e, _)| e.id)
            .collect();
        let f32_set: std::collections::HashSet<&str> = f32_top.iter().map(|s| s.as_str()).collect();

        // int8 mode (migrate store, same query) must keep every f32 top-5 hit.
        db.reindex_embeddings(EmbeddingQuant::Int8).unwrap();
        let int8_top: Vec<String> = db
            .dense_search(&q, 5)
            .unwrap()
            .into_iter()
            .map(|(e, _)| e.id)
            .collect();
        assert_eq!(
            int8_top.len(),
            5,
            "int8 dense search must still return limit rows"
        );
        let overlap: usize = int8_top
            .iter()
            .filter(|id| f32_set.contains(id.as_str()))
            .count();
        assert!(
            overlap >= 4,
            "int8 recall@5 must keep >=4/5 of the f32 top-5 (got {overlap}/5: f32={f32_top:?} int8={int8_top:?})"
        );
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn bit_mode_full_corpus_pool_ranks_globally_by_hamming() {
        // ≥ DENSE_SIG_PREFILTER_MIN_ROWS (2048) rows → the sig-cache prefilter
        // path with full-corpus pool in bit mode. Query = an exact stored
        // vector; its Hamming-0 row must be #1 even with the cache engaged.
        // dim 64 (not 8): the sign-bit space must be wide enough that no
        // other row shares the query's exact pattern (tie-breaking would
        // then be by stable fetch order, which is not what this test pins).
        let (mut db, path) = temp_db();
        db.embedding_config.enabled = false;
        let dim = 64usize;
        let n = 2100usize;
        for i in 0..n {
            let v = seeded_vec(i as u64 + 1, dim);
            insert_entity_with_embedding(&db, &format!("bc-{i:05}"), &v, true);
        }
        db.reindex_embeddings(EmbeddingQuant::Bit).unwrap();
        let target_id = "bc-01234";
        let q = {
            // Reconstruct the stored vector for bc-01234 (seed i+1).
            let i = 1234usize;
            seeded_vec(i as u64 + 1, dim)
        };
        let top = db
            .dense_search_with_opts(
                &q,
                5,
                100_000,
                DenseOpts {
                    use_sig_cache: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(top.len(), 5);
        assert_eq!(
            top[0].0.id,
            target_id,
            "bit mode + sig cache must rank the exact Hamming-0 row first (got {:?})",
            top.iter().map(|(e, _)| e.id.clone()).collect::<Vec<_>>()
        );
        assert_eq!(
            top[0].1, 1.0,
            "the exact row's Hamming similarity must be 1.0"
        );
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn restore_keeps_post_snapshot_rows_searchable_and_reported() {
        let (mut db, path) = temp_db();
        db.embedding_config.enabled = false;
        let v1 = seeded_vec(1, 16);
        insert_entity_with_embedding(&db, "pre-1", &v1, true);
        db.reindex_embeddings(EmbeddingQuant::Bit).unwrap();
        // Row written AFTER the snapshot: stored directly as bits.
        db.remember_skip_dedup(&make_entity(
            "post-1",
            "insight",
            "post-1",
            "{\"content\":\"post-1\"}",
        ))
        .unwrap();
        db.store_embedding("post-1", &v1).unwrap();
        let report = db.restore_embeddings_snapshot().unwrap();
        assert_eq!(report["restored"], 1, "only the pre-snapshot row restores");
        assert_eq!(report["still_quantized"], 1, "post-snapshot row reported");
        // Both rows remain searchable (mixed corpus decodes per-row).
        let top = db.dense_search(&v1, 2).unwrap();
        assert_eq!(top.len(), 2);
        assert!(top.iter().any(|(e, _)| e.id == "pre-1"));
        assert!(top.iter().any(|(e, _)| e.id == "post-1"));
        // New writes land as f32 again (record + in-process mirror flipped).
        let blob = raw_embedding(&db, "pre-1").unwrap();
        assert_eq!(blob.len(), 16 * 4);
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn set_embedding_quant_declares_fresh_store_and_fails_closed_on_existing() {
        // Fresh store: the declaration lands and is recorded.
        let (mut db, path) = temp_db();
        db.set_embedding_quant(EmbeddingQuant::Bit).unwrap();
        assert_eq!(db.embedding_quant(), EmbeddingQuant::Bit);
        let stored: String = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT format FROM embedding_format WHERE id = 1",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(stored, "bit");
        let _ = fs::remove_file(&path);

        // Store with existing embeddings: declaration refused (fail-closed).
        let (mut db2, path2) = temp_db();
        db2.embedding_config.enabled = false;
        let v = seeded_vec(9, 16);
        insert_entity_with_embedding(&db2, "x-1", &v, true);
        assert!(
            db2.set_embedding_quant(EmbeddingQuant::Bit).is_err(),
            "must refuse to flip the format on a store that already holds f32 embeddings"
        );
        assert_eq!(db2.embedding_quant(), EmbeddingQuant::F32);
        // Mismatch against a migrated store's record: refused.
        db2.reindex_embeddings(EmbeddingQuant::Bit).unwrap();
        assert!(
            db2.set_embedding_quant(EmbeddingQuant::Int8).is_err(),
            "must refuse a declaration that contradicts the store record"
        );
        assert!(db2.set_embedding_quant(EmbeddingQuant::Bit).is_ok());
        let _ = fs::remove_file(&path2);
    }

    /// #885 benchmark probe — storage bytes/vector, recall@k delta, latency
    /// delta between float32 / int8 / bit storage. `#[ignore]`d: not part of
    /// the suite; run explicitly:
    ///   cargo test --locked --no-default-features -- --ignored \
    ///     vector_quant_bench_probe --nocapture
    /// Numbers printed are the evidence for docs/specs/vector-compression.md.
    #[test]
    #[ignore]
    fn vector_quant_bench_probe() {
        let (mut db, path) = temp_db();
        db.embedding_config.enabled = false;
        let dim = 384usize;
        let clusters = 10usize;
        let members = 300usize; // 3000 rows total
                                // Corpus: 10 topic clusters; member = centroid + 5% noise, normalized.
        let mut queries: Vec<Vec<f32>> = Vec::new();
        for c in 0..clusters {
            let centroid = seeded_vec(50_000 + c as u64, dim);
            let norm = centroid.iter().map(|x| x * x).sum::<f32>().sqrt().max(1e-6);
            let centroid: Vec<f32> = centroid.iter().map(|x| x / norm).collect();
            for m in 0..members {
                let noise = seeded_vec(60_000 + c as u64 * 1000 + m as u64, dim);
                let v: Vec<f32> = centroid
                    .iter()
                    .zip(noise.iter())
                    .map(|(c, n)| c + n * 0.05)
                    .collect();
                let norm = v.iter().map(|x| x * x).sum::<f32>().sqrt().max(1e-6);
                let v: Vec<f32> = v.iter().map(|x| x / norm).collect();
                let id = format!("bm-{c:02}-{m:04}");
                insert_entity_with_embedding(&db, &id, &v, true);
            }
            // Query = centroid + noise (an unseen member of the cluster).
            let qnoise = seeded_vec(70_000 + c as u64, dim);
            let q: Vec<f32> = centroid
                .iter()
                .zip(qnoise.iter())
                .map(|(c, n)| c + n * 0.05)
                .collect();
            queries.push(q);
        }
        assert_eq!(queries.len(), clusters);

        let measure = |db: &Database, label: &str| {
            // Warmup (cache build + page cache).
            let _ = db.dense_search(&queries[0], 5).unwrap();
            let _ = db.dense_search(&queries[1], 5).unwrap();
            let mut r5 = Vec::new();
            let mut r10 = Vec::new();
            let mut lat = Vec::new();
            for (ci, q) in queries.iter().enumerate() {
                let prefix = format!("bm-{ci:02}-");
                let t = std::time::Instant::now();
                let top = db.dense_search(q, 10).unwrap();
                lat.push(t.elapsed().as_secs_f64() * 1000.0);
                let ids: Vec<String> = top.into_iter().map(|(e, _)| e.id).collect();
                let hit5 = ids
                    .iter()
                    .take(5)
                    .filter(|id| id.starts_with(&prefix))
                    .count();
                let hit10 = ids
                    .iter()
                    .take(10)
                    .filter(|id| id.starts_with(&prefix))
                    .count();
                r5.push(hit5 as f64 / 5.0);
                r10.push(hit10 as f64 / 10.0);
            }
            lat.sort_by(|a, b| a.partial_cmp(b).unwrap());
            let p50 = lat[lat.len() / 2];
            let mean: f64 = lat.iter().sum::<f64>() / lat.len() as f64;
            eprintln!(
                "[bench:{label}] recall@5={:.4} recall@10={:.4} latency_p50={:.2}ms mean={:.2}ms",
                r5.iter().sum::<f64>() / r5.len() as f64,
                r10.iter().sum::<f64>() / r10.len() as f64,
                p50,
                mean
            );
        };

        // float32 baseline.
        measure(&db, "float32");
        // int8.
        db.reindex_embeddings(EmbeddingQuant::Int8).unwrap();
        measure(&db, "int8");
        // bit (restore first — the snapshot is float32).
        db.restore_embeddings_snapshot().unwrap();
        db.reindex_embeddings(EmbeddingQuant::Bit).unwrap();
        measure(&db, "bit");

        // Storage bytes/vector (measured from the column).
        let conn = db.conn().unwrap();
        let len: i64 = conn
            .query_row("SELECT length(embedding) FROM entities LIMIT 1", [], |r| {
                r.get(0)
            })
            .unwrap();
        eprintln!("[bench:storage] bytes/vector(bit mode)={}", len);
        drop(conn);
        eprintln!(
            "[bench:note] float32=1536 int8=389 bit={} (dim {dim}) — seed anchors: \
             clusters=50_000+i, members=60_000+c*1000+m, queries=70_000+c",
            len
        );
        let _ = fs::remove_file(&path);
    }

    /// v18 (#507): the phase-0 signature scan and the embedded-row count must
    /// plan as USING COVERING INDEX — the whole point of
    /// idx_entities_dense_sig is that neither query touches an entity RECORD
    /// (embedding/emb_sig are late ALTER columns stored after body_json, so a
    /// record read walks the body's multi-KB overflow chain; that was the
    /// measured 390ms dense p50 at 100K). Pinning the plan text makes a
    /// schema or query-spelling drift fail loudly instead of silently
    /// reverting to ~30x slower dense recall.
    #[test]
    fn dense_phase0_queries_plan_as_covering_index() {
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        for q in [
            "SELECT COUNT(*) FROM entities WHERE archived = 0 AND emb_sig IS NOT NULL",
            "SELECT id, emb_sig FROM entities WHERE archived = 0 AND emb_sig IS NOT NULL LIMIT 50000",
        ] {
            let plan: String = conn
                .query_row(&format!("EXPLAIN QUERY PLAN {q}"), [], |r| r.get(3))
                .unwrap();
            assert!(
                plan.contains("COVERING INDEX idx_entities_dense_sig"),
                "dense phase-0 query must be covering, got plan: {plan} for {q}"
            );
        }
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn embedding_signature_packs_sign_bits_and_hamming_tracks_distance() {
        // bit i set iff v[i] > 0; zero and negative both clear.
        let sig = embedding_signature(&[1.0, -1.0, 0.0, 0.5, -0.2, 2.0, 0.0, -3.0, 0.1]);
        assert_eq!(sig.len(), 2, "9 dims pack into 2 bytes");
        assert_eq!(sig[0], 0b0010_1001);
        assert_eq!(sig[1], 0b0000_0001);

        let a = embedding_signature(&[1.0, 1.0, -1.0, -1.0]);
        let b = embedding_signature(&[1.0, -1.0, -1.0, 1.0]);
        assert_eq!(signature_hamming(&a, &a), 0);
        assert_eq!(signature_hamming(&a, &b), 2);
        // Dim mismatch can never win a candidate slot.
        assert_eq!(signature_hamming(&a, &sig), u32::MAX);
    }

    #[test]
    fn dense_search_signature_prefilter_finds_the_same_top_hits_at_scale() {
        // Above DENSE_SIG_PREFILTER_MIN_ROWS dense_search switches to the
        // Hamming-prefilter + exact-rerank path. Seed 2200 embedded rows with
        // a deterministic spread plus two engineered near-neighbors of the
        // query; the prefiltered path must surface both, exactly ranked by
        // true cosine, and never return an archived row.
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let dim = 16usize;
        let tx = conn.unchecked_transaction().unwrap();
        {
            let mut stmt = tx
                .prepare(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, emb_sig, archived)
                     VALUES (?1, 'insight', ?2, '{}', 'insight', 'active', 0, 0, 0,
                             1.0, 'working', ?3, ?4, ?5)",
                )
                .unwrap();
            // Deterministic filler vectors: sign pattern derived from the row
            // index bits, pointing all over the hypercube and away from the
            // all-positive query region. Starts at 1: i=0 hashes to the
            // all-positive pattern, which would tie the engineered exact hit
            // (2654435761 is odd, so no other i < 65536 hashes to it).
            for i in 1..=2200u32 {
                let v: Vec<f32> = (0..dim)
                    .map(|d| {
                        let bit = (i.wrapping_mul(2654435761) >> (d as u32 % 31)) & 1;
                        if bit == 1 {
                            -1.0
                        } else {
                            0.3
                        } // mixed signs, never all-positive
                    })
                    .collect();
                stmt.execute(params![
                    format!("filler-{:05}", i),
                    format!("filler-key-{:05}", i),
                    blob(&v),
                    embedding_signature(&v),
                    0i64
                ])
                .unwrap();
            }
            // Engineered hits: the query itself and a slightly-rotated cousin.
            let query: Vec<f32> = vec![1.0; dim];
            let mut near = query.clone();
            near[0] = 0.6;
            stmt.execute(params![
                "hit-exact",
                "hit-exact-key",
                blob(&query),
                embedding_signature(&query),
                0i64
            ])
            .unwrap();
            stmt.execute(params![
                "hit-near",
                "hit-near-key",
                blob(&near),
                embedding_signature(&near),
                0i64
            ])
            .unwrap();
            // An archived twin of the query must never surface.
            stmt.execute(params![
                "hit-archived",
                "hit-archived-key",
                blob(&query),
                embedding_signature(&query),
                1i64
            ])
            .unwrap();
        }
        tx.commit().unwrap();

        let query: Vec<f32> = vec![1.0; dim];
        let results = db.dense_search(&query, 5).unwrap();
        let ids: Vec<&str> = results.iter().map(|(e, _)| e.id.as_str()).collect();
        assert_eq!(ids[0], "hit-exact", "true nearest must rank first: {ids:?}");
        assert_eq!(
            ids[1], "hit-near",
            "second-nearest must rank second: {ids:?}"
        );
        assert!(
            !ids.contains(&"hit-archived"),
            "archived row leaked: {ids:?}"
        );
        assert!(
            results[0].1 > results[1].1,
            "scores must be exact-cosine ordered"
        );

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn dense_search_scan_bound_is_the_recall_dial_it_claims_to_be() {
        // #619 interim: `max_scan` bounds the brute-force scan, so a row that
        // lies beyond the ceiling is invisible at a small cap and found again
        // when the cap is lifted (0 = unbounded maps to i64::MAX upstream).
        // Seeded so the engineered hit is last in BOTH plausible scan orders
        // (rowid/insertion and id), making the small-cap miss deterministic.
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let dim = 16usize;
        let tx = conn.unchecked_transaction().unwrap();
        {
            let mut stmt = tx
                .prepare(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, emb_sig, archived)
                     VALUES (?1, 'insight', ?2, '{}', 'insight', 'active', 0, 0, 0,
                             1.0, 'working', ?3, ?4, 0)",
                )
                .unwrap();
            // 300 fillers pointing away from the all-positive query region.
            for i in 1..=300u32 {
                let v: Vec<f32> = (0..dim)
                    .map(|d| {
                        let bit = (i.wrapping_mul(2654435761) >> (d as u32 % 31)) & 1;
                        if bit == 1 {
                            -1.0
                        } else {
                            0.3
                        }
                    })
                    .collect();
                stmt.execute(params![
                    format!("filler-{:05}", i),
                    format!("filler-key-{:05}", i),
                    blob(&v),
                    embedding_signature(&v)
                ])
                .unwrap();
            }
            let query: Vec<f32> = vec![1.0; dim];
            stmt.execute(params![
                "zzz-hit",
                "zzz-hit-key",
                blob(&query),
                embedding_signature(&query)
            ])
            .unwrap();
        }
        tx.commit().unwrap();

        let query: Vec<f32> = vec![1.0; dim];

        // Cap below the corpus: the late row is beyond the scan ceiling.
        let capped = db.dense_search_scan_bounded(&query, 5, 100).unwrap();
        assert!(
            !capped.iter().any(|(e, _)| e.id == "zzz-hit"),
            "a 100-row scan bound must not reach the 301st row"
        );
        assert!(capped.len() <= 5 && !capped.is_empty());

        // Unbounded (what PERSEUS_VAULT_DENSE_MAX_SCAN=0 resolves to): exact recall.
        let exact = db
            .dense_search_scan_bounded(&query, 5, i64::MAX as usize)
            .unwrap();
        assert_eq!(
            exact[0].0.id, "zzz-hit",
            "unbounded scan must find the true nearest neighbor"
        );

        // Default entrypoint (env unset → 50k ceiling) covers the whole corpus.
        let default = db.dense_search(&query, 5).unwrap();
        assert_eq!(default[0].0.id, "zzz-hit");

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn dense_sig_cache_full_coverage_and_both_invalidation_stamps() {
        // #619: the resident sig cache ranks EVERY active signed row, so a hit
        // beyond a small `max_scan` is found anyway (full coverage is the
        // point), and the cache must go stale on BOTH stamp kinds: a count
        // change (archive/insert/delete) and a same-count in-place re-embed
        // (SIG_WRITE_GEN via the store_embedding helpers).
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let dim = 16usize;
        let tx = conn.unchecked_transaction().unwrap();
        {
            let mut stmt = tx
                .prepare(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, emb_sig, archived)
                     VALUES (?1, 'insight', ?2, '{}', 'insight', 'active', 0, 0, 0,
                             1.0, 'working', ?3, ?4, 0)",
                )
                .unwrap();
            // 2200 fillers (over DENSE_SIG_PREFILTER_MIN_ROWS so the sig path
            // runs), same deterministic spread as the prefilter scale test.
            for i in 1..=2200u32 {
                let v: Vec<f32> = (0..dim)
                    .map(|d| {
                        let bit = (i.wrapping_mul(2654435761) >> (d as u32 % 31)) & 1;
                        if bit == 1 {
                            -1.0
                        } else {
                            0.3
                        }
                    })
                    .collect();
                stmt.execute(params![
                    format!("filler-{:05}", i),
                    format!("filler-key-{:05}", i),
                    blob(&v),
                    embedding_signature(&v)
                ])
                .unwrap();
            }
            let query: Vec<f32> = vec![1.0; dim];
            stmt.execute(params![
                "zzz-hit",
                "zzz-hit-key",
                blob(&query),
                embedding_signature(&query)
            ])
            .unwrap();
        }
        tx.commit().unwrap();

        let query: Vec<f32> = vec![1.0; dim];

        // The SQL path at max_scan=100 cannot reach the 2201st row…
        let bounded = db
            .dense_search_with_opts(
                &query,
                5,
                100,
                DenseOpts {
                    use_sig_cache: Some(false),
                    ..Default::default()
                },
            )
            .unwrap();
        assert!(!bounded.iter().any(|(e, _)| e.id == "zzz-hit"));
        // …the cache path finds it despite the same bound: full coverage.
        let cached = db
            .dense_search_with_opts(
                &query,
                5,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(
            cached[0].0.id, "zzz-hit",
            "sig cache must cover the whole corpus"
        );

        // Stamp 1 — count change: archiving the hit must evict it on the very
        // next query (the cache rebuilds; archived rows are not in it).
        conn.execute("UPDATE entities SET archived = 1 WHERE id = 'zzz-hit'", [])
            .unwrap();
        let after_archive = db
            .dense_search_with_opts(
                &query,
                5,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert!(
            !after_archive.iter().any(|(e, _)| e.id == "zzz-hit"),
            "archived row leaked from a stale sig cache"
        );

        // Stamp 2 — same-count in-place re-embed: rewrite one filler to BE the
        // query vector through the store_embedding helper (bumps
        // SIG_WRITE_GEN; row count unchanged). The stale cache still holds its
        // old far-away signature — only the gen stamp can catch this.
        Database::store_embedding_with_conn(&conn, "filler-00042", &query, EmbeddingQuant::F32)
            .unwrap();
        let after_reembed = db
            .dense_search_with_opts(
                &query,
                5,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(
            after_reembed[0].0.id, "filler-00042",
            "in-place re-embed missed: SIG_WRITE_GEN stamp failed"
        );

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn asym_lut_score_equals_naive_signed_dot() {
        // #619 step 2a: the per-byte LUT sum must equal the direct
        // Σ q[i]·(bit i ? +1 : −1), including the ragged tail byte (dims
        // beyond q.len() contribute 0).
        let q: Vec<f32> = (0..19).map(|i| (i as f32 * 0.37).sin()).collect();
        let v: Vec<f32> = (0..19).map(|i| (i as f32 * 0.91).cos()).collect();
        let sig = embedding_signature(&v); // 3 bytes for 19 dims
        let luts = build_asym_luts(&q, sig.len());
        let got = asym_sig_score(&luts, &sig);
        let want: f32 = (0..19)
            .map(|i| if v[i] > 0.0 { q[i] } else { -q[i] })
            .sum::<f32>()
            // dims 19..24 of the padded 3rd byte: bits clear, q padded 0 → 0
            + (19..24).map(|_| 0.0f32).sum::<f32>();
        assert!((got - want).abs() < 1e-4, "LUT {got} != naive {want}");
    }

    #[test]
    fn asym_scoring_rescues_true_neighbor_that_symmetric_hamming_exiles() {
        // #619 step 2a, the failure mode this ships to fix: 2,500 decoys that
        // are BIT-close to the query (Hamming 1 — only the dominant dim's
        // sign differs) but truly far (cosine < 0), plus ONE true neighbor
        // that is bit-far (Hamming 15 — every minor dim's sign differs) but
        // truly near (cosine ≈ 1). Symmetric Hamming ranks the neighbor
        // 2,501st — outside any pool ≤ 2,500, unrecoverable by the exact
        // rerank. The asymmetric score ⟨q, sign(v)⟩ keeps the query's
        // magnitudes: neighbor ≈ +0.85, decoys ≈ −0.85 — top of the pool.
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let dim = 16usize;
        let tx = conn.unchecked_transaction().unwrap();
        {
            let mut stmt = tx
                .prepare(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, emb_sig, archived)
                     VALUES (?1, 'insight', ?2, '{}', 'insight', 'active', 0, 0, 0,
                             1.0, 'working', ?3, ?4, 0)",
                )
                .unwrap();
            let mut decoy = vec![0.05f32; dim];
            decoy[0] = -1.0;
            for i in 1..=2500u32 {
                stmt.execute(params![
                    format!("decoy-{:05}", i),
                    format!("decoy-key-{:05}", i),
                    blob(&decoy),
                    embedding_signature(&decoy)
                ])
                .unwrap();
            }
            let mut neighbor = vec![-0.01f32; dim];
            neighbor[0] = 2.0;
            stmt.execute(params![
                "true-neighbor",
                "true-neighbor-key",
                blob(&neighbor),
                embedding_signature(&neighbor)
            ])
            .unwrap();
        }
        tx.commit().unwrap();

        let mut q = vec![0.01f32; dim];
        q[0] = 1.0;
        // Force the cache path; default scoring is asymmetric (step 2a).
        let top = db
            .dense_search_with_opts(
                &q,
                1,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(
            top[0].0.id, "true-neighbor",
            "asymmetric prefilter must surface the magnitude-dominant true \
             neighbor that symmetric Hamming ranks dead last"
        );

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn sig4_adc_score_approximates_the_true_dot() {
        // #619 step 2b: scale·ΣLUT ≈ ⟨q, v⟩ within quantization error. The
        // per-dim error is ≤ scale/2, so |ADC − dot| ≤ Σ|q_i|·scale/2.
        let q: Vec<f32> = (0..37).map(|i| (i as f32 * 0.43).sin()).collect();
        let v: Vec<f32> = (0..37).map(|i| (i as f32 * 0.77).cos() * 1.7).collect();
        let blob = embedding_sig4(&v);
        assert_eq!(blob.len(), 4 + 19, "37 dims → 4B scale + 19 nibble bytes");
        let luts = build_sig4_luts(&q, 19);
        let got = sig4_score(&luts, &blob).expect("well-formed blob scores");
        let dot: f32 = q.iter().zip(&v).map(|(a, b)| a * b).sum();
        let scale = v.iter().fold(0f32, |m, &x| m.max(x.abs())) / 7.0;
        let bound: f32 = q.iter().map(|x| x.abs()).sum::<f32>() * scale * 0.5 + 1e-3;
        assert!(
            (got - dot).abs() <= bound,
            "ADC {got} vs dot {dot} exceeds quantization bound {bound}"
        );
        // Foreign-length blob refuses to score instead of mis-ranking.
        assert!(sig4_score(&luts, &blob[..10]).is_none());
    }

    #[test]
    fn int4_refine_separates_rows_the_one_bit_prefilter_cannot() {
        // #619 step 2b, the failure mode it ships to fix: rows with IDENTICAL
        // sign patterns are indistinguishable to any 1-bit scoring (symmetric
        // or asymmetric) — the coarse rank degenerates to the id tie-break.
        // 2,500 all-positive low-magnitude decoys + one all-positive
        // high-magnitude true neighbor whose id sorts LAST: without the int4
        // tier the tie-break exiles it below any pool ≤ 2,500; the int4 ADC
        // (which sees magnitudes) must put it first.
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let dim = 16usize;
        let tx = conn.unchecked_transaction().unwrap();
        {
            let mut stmt = tx
                .prepare(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, emb_sig, emb_sig4, archived)
                     VALUES (?1, 'insight', ?2, '{}', 'insight', 'active', 0, 0, 0,
                             1.0, 'working', ?3, ?4, ?5, 0)",
                )
                .unwrap();
            // sign(decoy) == sign(neighbor) == sign(q): every 1-bit scoring
            // ties all rows. Alternating magnitudes keep the decoys OFF the
            // query direction (cosine ≈ 0.95 < 1.0) so the exact rerank has a
            // true winner once the int4 tier gets the neighbor into the pool.
            let decoy: Vec<f32> = (0..dim)
                .map(|d| if d % 2 == 0 { 0.05f32 } else { 0.10f32 })
                .collect();
            for i in 1..=2500u32 {
                stmt.execute(params![
                    format!("decoy-{:05}", i),
                    format!("decoy-key-{:05}", i),
                    blob(&decoy),
                    embedding_signature(&decoy),
                    embedding_sig4(&decoy)
                ])
                .unwrap();
            }
            let neighbor = vec![1.0f32; dim];
            stmt.execute(params![
                "zzz-neighbor",
                "zzz-neighbor-key",
                blob(&neighbor),
                embedding_signature(&neighbor),
                embedding_sig4(&neighbor)
            ])
            .unwrap();
        }
        tx.commit().unwrap();

        let q = vec![1.0f32; dim];
        // Force the cache + the (post-#663 opt-in) disk refine. limit 1 →
        // pool 512 < 2,501, so the tie-break alone would exile zzz-neighbor.
        let top = db
            .dense_search_with_opts(
                &q,
                1,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    sig4_refine: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(
            top[0].0.id, "zzz-neighbor",
            "int4 refine must surface the magnitude-dominant neighbor that \
             every 1-bit scoring ties with the decoys (and the id tie-break \
             then exiles)"
        );

        // #619 step 2c′: the RESIDENT int4 coarse must reach the same answer
        // with no disk fetch — the ADC score ranks the whole corpus directly.
        let top = db
            .dense_search_with_opts(
                &q,
                1,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    sig4_resident: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(
            top[0].0.id, "zzz-neighbor",
            "resident int4 coarse must surface the neighbor 1-bit scoring ties away"
        );

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn rows_without_sig4_still_reach_the_pool_after_scored_rows() {
        // Transitional safety (#619 step 2b): rows written by a pre-v19
        // binary after migration have NULL emb_sig4. They must not vanish
        // from dense recall — they append after ADC-ranked rows and still
        // reach the exact rerank when the pool has room.
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let dim = 16usize;
        let tx = conn.unchecked_transaction().unwrap();
        {
            let mut stmt = tx
                .prepare(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, emb_sig, emb_sig4, archived)
                     VALUES (?1, 'insight', ?2, '{}', 'insight', 'active', 0, 0, 0,
                             1.0, 'working', ?3, ?4, ?5, 0)",
                )
                .unwrap();
            // Fillers point away from the query; all carry sig4.
            for i in 1..=2200u32 {
                let v: Vec<f32> = (0..dim)
                    .map(|d| {
                        let bit = (i.wrapping_mul(2654435761) >> (d as u32 % 31)) & 1;
                        if bit == 1 {
                            -1.0
                        } else {
                            0.3
                        }
                    })
                    .collect();
                stmt.execute(params![
                    format!("filler-{:05}", i),
                    format!("filler-key-{:05}", i),
                    blob(&v),
                    embedding_signature(&v),
                    embedding_sig4(&v)
                ])
                .unwrap();
            }
        }
        // The true nearest neighbor, written WITHOUT sig4 (old-binary shape).
        let query: Vec<f32> = vec![1.0; dim];
        conn.execute(
            "INSERT INTO entities (id, category, key, body_json, type, status,
                retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                decay_score, layer, embedding, emb_sig, emb_sig4, archived)
             VALUES ('zzz-nosig4', 'insight', 'zzz-nosig4-key', '{}', 'insight',
                     'active', 0, 0, 0, 1.0, 'working', ?1, ?2, NULL, 0)",
            params![blob(&query), embedding_signature(&query)],
        )
        .unwrap();
        tx.commit().unwrap();

        let results = db
            .dense_search_with_opts(
                &query,
                5,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    sig4_refine: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(
            results[0].0.id, "zzz-nosig4",
            "a NULL-sig4 row must still reach the exact rerank (which then \
             ranks it by its true cosine), not vanish from dense recall"
        );

        // #619 2c′: same guarantee through the RESIDENT tier — the missing
        // row rides the reserved pool share instead of vanishing.
        let results = db
            .dense_search_with_opts(
                &query,
                5,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    sig4_resident: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(
            results[0].0.id, "zzz-nosig4",
            "a NULL-sig4 row must ride the resident tier's reservation to the rerank"
        );

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn pure_1bit_no_rerank_returns_hamming_order() {
        // #630: DenseOpts.rerank = Some(false) (env PERSEUS_VAULT_DENSE_SIG_RERANK=0)
        // must return the 1-bit Hamming-pool order directly — no exact-cosine
        // rerank. Defining property: results are ordered by NON-DECREASING
        // Hamming distance from the query signature. The default (rerank on)
        // reorders the same pool by exact cosine (scores descending).
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let dim = 16usize;
        let tx = conn.unchecked_transaction().unwrap();
        {
            let mut stmt = tx
                .prepare(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, emb_sig, emb_sig4, archived)
                     VALUES (?1, 'insight', ?2, '{}', 'insight', 'active', 0, 0, 0,
                             1.0, 'working', ?3, ?4, ?5, 0)",
                )
                .unwrap();
            // >= DENSE_SIG_PREFILTER_MIN_ROWS (2048) so the signature path engages.
            for i in 1..=2300u32 {
                let v: Vec<f32> = (0..dim)
                    .map(|d| {
                        let bit = (i.wrapping_mul(2654435761) >> (d as u32 % 31)) & 1;
                        if bit == 1 {
                            -1.0
                        } else {
                            0.3
                        }
                    })
                    .collect();
                stmt.execute(params![
                    format!("row-{:05}", i),
                    format!("key-{:05}", i),
                    blob(&v),
                    embedding_signature(&v),
                    embedding_sig4(&v)
                ])
                .unwrap();
            }
        }
        tx.commit().unwrap();

        let query: Vec<f32> = vec![1.0; dim];
        let query_sig = embedding_signature(&query);
        let ham = |id: &str| -> u32 {
            let sig: Vec<u8> = conn
                .query_row(
                    "SELECT emb_sig FROM entities WHERE id = ?1",
                    params![id],
                    |r| r.get(0),
                )
                .unwrap();
            signature_hamming(&query_sig, &sig)
        };

        // Pure 1-bit: rerank OFF.
        let pure = db
            .dense_search_with_opts(
                &query,
                10,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    rerank: Some(false),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(pure.len(), 10, "pure-1-bit must return `limit` rows");
        let dists: Vec<u32> = pure.iter().map(|(e, _)| ham(&e.id)).collect();
        for w in dists.windows(2) {
            assert!(
                w[0] <= w[1],
                "pure-1-bit results must be in non-decreasing Hamming order, got {dists:?}"
            );
        }

        // Deterministic across calls.
        let pure2 = db
            .dense_search_with_opts(
                &query,
                10,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    rerank: Some(false),
                    ..Default::default()
                },
            )
            .unwrap();
        let ids1: Vec<&str> = pure.iter().map(|(e, _)| e.id.as_str()).collect();
        let ids2: Vec<&str> = pure2.iter().map(|(e, _)| e.id.as_str()).collect();
        assert_eq!(ids1, ids2, "pure-1-bit ordering must be deterministic");

        // Default (rerank ON) still returns `limit` rows in cosine-descending
        // order — the shipped behavior is unchanged.
        let reranked = db
            .dense_search_with_opts(
                &query,
                10,
                100,
                DenseOpts {
                    use_sig_cache: Some(true),
                    rerank: Some(true),
                    ..Default::default()
                },
            )
            .unwrap();
        assert_eq!(reranked.len(), 10);
        for w in reranked.windows(2) {
            assert!(
                w[0].1 >= w[1].1,
                "rerank-on results must be cosine-descending"
            );
        }

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn dense_sig_cache_auto_engages_exactly_when_corpus_outgrows_the_bound() {
        // #619 default-on: AUTO (use_sig_cache = None) must engage the cache
        // when embedded rows exceed max_scan — the point where the bounded
        // scan starts sampling — and stay off (bounded semantics, including
        // the bound's recall limitation) when the scan still covers the
        // corpus. Corpus shape mirrors the scan-bound test: 2200 fillers plus
        // a late-sorting engineered hit at both plausible scan orders.
        let (db, path) = temp_db();
        let conn = db.conn().unwrap();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let dim = 16usize;
        let tx = conn.unchecked_transaction().unwrap();
        {
            let mut stmt = tx
                .prepare(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, emb_sig, archived)
                     VALUES (?1, 'insight', ?2, '{}', 'insight', 'active', 0, 0, 0,
                             1.0, 'working', ?3, ?4, 0)",
                )
                .unwrap();
            for i in 1..=2200u32 {
                let v: Vec<f32> = (0..dim)
                    .map(|d| {
                        let bit = (i.wrapping_mul(2654435761) >> (d as u32 % 31)) & 1;
                        if bit == 1 {
                            -1.0
                        } else {
                            0.3
                        }
                    })
                    .collect();
                stmt.execute(params![
                    format!("filler-{:05}", i),
                    format!("filler-key-{:05}", i),
                    blob(&v),
                    embedding_signature(&v)
                ])
                .unwrap();
            }
            let query: Vec<f32> = vec![1.0; dim];
            stmt.execute(params![
                "zzz-hit",
                "zzz-hit-key",
                blob(&query),
                embedding_signature(&query)
            ])
            .unwrap();
        }
        tx.commit().unwrap();

        let query: Vec<f32> = vec![1.0; dim];

        // 2201 rows > max_scan 100: AUTO engages the cache → full coverage.
        let auto_over = db
            .dense_search_with_opts(&query, 5, 100, DenseOpts::default())
            .unwrap();
        assert_eq!(
            auto_over[0].0.id, "zzz-hit",
            "AUTO must engage the sig cache once the corpus outgrows max_scan"
        );

        // max_scan covers the corpus: AUTO stays on the bounded path and the
        // result matches the forced-off bounded scan exactly.
        let auto_under = db
            .dense_search_with_opts(&query, 5, 50_000, DenseOpts::default())
            .unwrap();
        let bounded = db
            .dense_search_with_opts(
                &query,
                5,
                50_000,
                DenseOpts {
                    use_sig_cache: Some(false),
                    ..Default::default()
                },
            )
            .unwrap();
        let ids = |v: &Vec<(Entity, f64)>| v.iter().map(|(e, _)| e.id.clone()).collect::<Vec<_>>();
        assert_eq!(
            ids(&auto_under),
            ids(&bounded),
            "AUTO under the bound must be the plain bounded scan"
        );
        assert_eq!(auto_under[0].0.id, "zzz-hit");

        let _ = fs::remove_file(&path);
    }

    // #226: dense/hybrid recall must embed the query, not silently fall back to
    // FTS5. With no embedding backend configured, a dense recall over a
    // non-empty query surfaces the backend error instead of returning keyword
    // results — the silent fallback was what masked the missing embedding.
    #[test]
    fn dense_recall_without_backend_errors_instead_of_silent_fts5() {
        let (mut db, path) = temp_db();
        // Explicitly disable the embedding backend. With bundled-embeddings now on
        // by default (#237) the default Db *has* a backend, so to exercise the
        // "no backend" path (#226) we turn it off here — keeping this test valid in
        // both the default and --no-default-features builds.
        db.embedding_config.enabled = false;
        // Seed a row a keyword search WOULD match, so the pre-fix silent FTS5
        // fallback would have wrongly returned it as an Ok result.
        db.conn()
            .unwrap()
            .execute(
                "INSERT INTO entities (id, category, key, body_json, type, status,
                    retrieval_count, last_accessed_unix_ms, created_at_unix_ms, decay_score, layer)
                 VALUES ('e1', 'insight', 'alpha', '{\"content\":\"alpha beta\"}', 'insight', 'active', 0, 0, 0, 1.0, 'working')",
                params![],
            )
            .unwrap();

        let res = db.recall(&RecallParams {
            query: "alpha".to_string(),
            mode: crate::models::SearchMode::Dense,
            limit: 5,
            skip_side_effects: true,
            ..RecallParams::default()
        });

        assert!(
            res.is_err(),
            "dense recall with no embedding backend must error, not silently return FTS5 results"
        );
        let msg = format!("{}", res.unwrap_err());
        assert!(
            msg.contains("embedding backend"),
            "error should name the missing embedding backend, got: {msg}"
        );

        let _ = fs::remove_file(&path);
    }

    // #1030: a HYBRID query with no dense leg available (embedding tier off,
    // no fingerprint tier) degrades to the sparse arm with an explicit
    // degraded marker — integrations on lean binaries still get keyword
    // hits instead of a hard error or a silent empty. Dense keeps the
    // hard error (previous test).
    #[test]
    fn hybrid_recall_without_dense_leg_degrades_to_sparse_with_marker() {
        let (mut db, path) = temp_db();
        db.embedding_config.enabled = false;
        db.set_embedding_fingerprint(false);
        // Seed through the real write path so the FTS index sees the row.
        crate::tools::handle_remember(
            &db,
            serde_json::json!({
                "category": "insight",
                "key": "alpha",
                "body_json": "{\"content\":\"alpha beta\"}",
            }),
        )
        .expect("remember should succeed");

        let (entities, completeness) = db
            .recall_with_completeness(&RecallParams {
                query: "alpha".to_string(),
                mode: crate::models::SearchMode::Hybrid,
                limit: 5,
                skip_side_effects: true,
                ..RecallParams::default()
            })
            .unwrap();

        assert_eq!(entities.len(), 1, "hybrid must serve the sparse arm");
        assert_eq!(entities[0].key, "alpha");
        let degraded = completeness
            .degraded
            .expect("degraded marker must be present when the dense leg is missing");
        assert!(
            degraded.contains("embedding backend"),
            "degraded reason should name the missing backend, got: {degraded}"
        );

        let _ = fs::remove_file(&path);
    }

    // #1020: strict flag parse — documented spellings accepted, garbage
    // rejected (fail-closed, never a silent off).
    #[test]
    fn parse_fingerprint_flag_accepts_documented_spellings_and_rejects_garbage() {
        assert_eq!(Database::parse_fingerprint_flag("on"), Ok(true));
        assert_eq!(Database::parse_fingerprint_flag(" ON "), Ok(true));
        assert_eq!(Database::parse_fingerprint_flag("true"), Ok(true));
        assert_eq!(Database::parse_fingerprint_flag("1"), Ok(true));
        assert_eq!(Database::parse_fingerprint_flag("yes"), Ok(true));
        assert_eq!(Database::parse_fingerprint_flag("off"), Ok(false));
        assert_eq!(Database::parse_fingerprint_flag("false"), Ok(false));
        assert_eq!(Database::parse_fingerprint_flag("0"), Ok(false));
        assert_eq!(Database::parse_fingerprint_flag("no"), Ok(false));
        assert_eq!(Database::parse_fingerprint_flag(""), Ok(false));
        assert!(Database::parse_fingerprint_flag("maybe").is_err());
        assert!(Database::parse_fingerprint_flag("2").is_err());
    }

    // #1020: write-path semantics — enabled writes store the fingerprint of
    // the plaintext body, content changes recompute it, disabled writes
    // store NULL (a fingerprint for a body the row no longer has is wrong
    // in any configuration, the same rule as the embedding clear).
    #[test]
    fn fingerprint_write_path_stores_recomputes_and_clears() {
        let (mut db, _path) = temp_db();
        db.embedding_config.enabled = false; // the fingerprint tier needs no backend
        db.set_embedding_fingerprint(true);

        let body_a = "the rusty sprocket lives in the tool drawer";
        db.remember_skip_dedup(&make_entity("fp-a", "insight", "fp-a", body_a))
            .unwrap();
        let fp_a = crate::fingerprint::fingerprint_bytes(body_a);
        let stored: Option<Vec<u8>> = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT fingerprint FROM entities WHERE id = 'fp-a'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(stored.as_deref(), Some(fp_a.as_slice()));

        // Content change -> recomputed from the new body.
        let body_b = "the rusty sprocket was moved to the garden shed";
        db.remember_skip_dedup(&make_entity("fp-a", "insight", "fp-a", body_b))
            .unwrap();
        let fp_b = crate::fingerprint::fingerprint_bytes(body_b);
        let stored: Option<Vec<u8>> = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT fingerprint FROM entities WHERE id = 'fp-a'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(stored.as_deref(), Some(fp_b.as_slice()));
        assert_ne!(fp_a, fp_b);

        // Disabled process -> next content change CLEARS the fingerprint so
        // a later re-enablement can never serve a stale one.
        db.set_embedding_fingerprint(false);
        db.remember_skip_dedup(&make_entity(
            "fp-a",
            "insight",
            "fp-a",
            "completely different body text now",
        ))
        .unwrap();
        let stored: Option<Vec<u8>> = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT fingerprint FROM entities WHERE id = 'fp-a'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert!(
            stored.is_none(),
            "disabled writes must clear the fingerprint"
        );

        // Fresh create while disabled -> NULL.
        db.remember_skip_dedup(&make_entity("fp-b", "insight", "fp-b", "another body"))
            .unwrap();
        let stored: Option<Vec<u8>> = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT fingerprint FROM entities WHERE id = 'fp-b'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert!(stored.is_none());
    }

    // #1020: zero-API fallback — with the tier enabled, a dense recall whose
    // embedding backend is unavailable degrades to deterministic Hamming
    // ranking over fingerprints instead of the #226 error, and the near-miss
    // (lexical-adjacent) candidate tops the ranking.
    #[test]
    fn fingerprint_fallback_ranks_without_embedding_backend() {
        let (mut db, _path) = temp_db();
        db.embedding_config.enabled = false; // no local backend
        db.set_embedding_fingerprint(true);
        db.remember_skip_dedup(&make_entity(
            "f1",
            "insight",
            "turing",
            "Alan Turing broke the Enigma cipher at Bletchley Park",
        ))
        .unwrap();
        db.remember_skip_dedup(&make_entity(
            "f2",
            "insight",
            "hopper",
            "Grace Hopper wrote the first compiler",
        ))
        .unwrap();
        db.remember_skip_dedup(&make_entity(
            "f3",
            "insight",
            "tesla",
            "Nikola Tesla pioneered alternating current",
        ))
        .unwrap();

        // Near-miss query: separator/case variant of the stored body's key
        // phrase — lexical-adjacent, exactly this tier's contract.
        let res = db.recall(&RecallParams {
            query: "alan turing enigma bletchley".to_string(),
            mode: crate::models::SearchMode::Dense,
            limit: 3,
            skip_side_effects: true,
            ..RecallParams::default()
        });
        let hits = res.expect("fingerprint fallback must rank, not error");
        assert!(!hits.is_empty(), "fallback must return ranked candidates");
        assert_eq!(
            hits[0].id, "f1",
            "near-miss candidate must top the fallback ranking"
        );
    }

