    #[cfg(feature = "bundled-embeddings")]
    #[test]
    fn hybrid_recall_surfaces_linked_neighbor_via_graph_arm() {
        // The core claim of the graph-expansion RRF arm: an entity that is
        // WEAK on both dense and sparse relevance to the query, but is
        // directly linked to the strongest dense/sparse hit, should still
        // surface in hybrid results -- something plain dense+sparse fusion
        // cannot do.
        let (db, path) = temp_db();
        let insert = |id: &str, key: &str, body: &str, emb: &[f32]| {
            let mut e = make_entity(id, "architecture", key, body);
            e.embedding = Some(emb.to_vec());
            db.remember(&e).unwrap();
        };

        // Strong hit: matches the query on both semantic + keyword grounds.
        insert(
            "g-strong",
            "checkout-service",
            r#"{"note":"checkout payment processing service"}"#,
            &[1.0, 0.0, 0.0],
        );
        // Weak/irrelevant to the query on its own, but linked to the strong hit.
        insert(
            "g-weak-linked",
            "fraud-rules-engine",
            r#"{"note":"totally unrelated rules configuration"}"#,
            &[0.0, 0.0, 1.0],
        );
        // A distractor: equally irrelevant, NOT linked to anything.
        insert(
            "g-distractor",
            "unrelated-widget",
            r#"{"note":"totally unrelated widget config nothing to do with anything"}"#,
            &[0.0, 1.0, 0.0],
        );

        db.link(
            "architecture",
            "checkout-service",
            "g-weak-linked",
            "depends_on",
        )
        .unwrap();
        flush_embeds(&db); // #393: the dense arm needs the deferred auto-embeds landed

        let params = crate::models::RecallParams {
            query: "checkout payment processing service".to_string(),
            mode: crate::models::SearchMode::Hybrid,
            limit: 5,
            ..crate::models::RecallParams::default()
        };
        let results = db.recall(&params).unwrap();
        let ids: Vec<&str> = results.iter().map(|e| e.id.as_str()).collect();

        assert!(
            ids.contains(&"g-strong"),
            "the directly-matching entity must be in results, got {:?}",
            ids
        );
        assert!(
            ids.contains(&"g-weak-linked"),
            "an entity linked to the top hit must surface via the graph arm even though \
             it doesn't independently match the query, got {:?}",
            ids
        );
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn fts5_bm25_search_filters_stopwords_and_is_read_only() {
        // Regression for #247: the hybrid keyword arm drops stopwords (so a
        // natural-language paraphrase query doesn't match the whole corpus on
        // function words) and never mutates access state.
        let (db, path) = temp_db();
        db.remember(&make_entity(
            "espresso",
            "habit",
            "coffee",
            r#"{"note": "I drink a strong espresso every morning"}"#,
        ))
        .unwrap();
        db.remember(&make_entity(
            "bike",
            "habit",
            "commute",
            r#"{"note": "I usually bike to the office on weekdays"}"#,
        ))
        .unwrap();

        // All-stopword query ("does the user...") → no content terms → empty arm.
        let stop = db
            .fts5_bm25_search(&RecallParams {
                query: "does the user have any".to_string(),
                limit: 10,
                ..RecallParams::default()
            })
            .unwrap();
        assert!(
            stop.is_empty(),
            "a query of only stopwords must yield no keyword matches, got {:?}",
            stop.iter().map(|(e, _)| &e.id).collect::<Vec<_>>()
        );

        // A content term still matches, and scores are relevance (higher better).
        let hit = db
            .fts5_bm25_search(&RecallParams {
                query: "the espresso".to_string(),
                limit: 10,
                ..RecallParams::default()
            })
            .unwrap();
        assert!(
            hit.iter().any(|(e, _)| e.id == "espresso"),
            "content term 'espresso' must match its memory"
        );

        // Read-only: retrieval_count must be unchanged after the keyword search.
        let count: i64 = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT retrieval_count FROM entities WHERE id = 'espresso'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(count, 0, "fts5_bm25_search must not mutate retrieval_count");

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn fts5_bm25_two_phase_pool_survives_filter_heavy_corpora() {
        // #511: the sparse arm now ranks rowids INSIDE the FTS index (no join)
        // and hydrates + metadata-filters only a bounded pool. When the filters
        // (here: the default exclusion of the `conversation` category, #298)
        // eat the entire first pool, the arm must widen its fetch and still
        // return every in-scope hit — never silently truncate the arm, and
        // never leak an excluded row.
        let (db, path) = temp_db();
        let insert = |id: &str, category: &str, body: &str| {
            let conn = db.conn().unwrap();
            conn.execute(
                "INSERT INTO entities (id, category, key, body_json, type, status,
                    retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                    decay_score, layer, archived)
                 VALUES (?1, ?2, ?1, ?3, 'insight', 'active', 0, 0, 0, 1.0, 'working', 0)",
                params![id, category, body],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO entities_fts (rowid, body_json)
                 VALUES ((SELECT rowid FROM entities WHERE id = ?1), ?2)",
                params![id, body],
            )
            .unwrap();
        };

        // 300 excluded-category rows that match the term strongly (high term
        // frequency, short bodies) — they own the top of the raw bm25 ranking
        // and overflow the first 128-row pool.
        for i in 0..300 {
            insert(
                &format!("noise-{i:04}"),
                "conversation",
                &format!(r#"{{"note":"zebrafinch zebrafinch zebrafinch turn {i}"}}"#),
            );
        }
        // 3 in-scope rows that match the same term weakly (single mention,
        // longer body) — bm25 ranks them below every noise row.
        for i in 0..3 {
            insert(
                &format!("wanted-{i}"),
                "insight",
                &format!(
                    r#"{{"note":"one zebrafinch note {i} with a much longer body of trailing prose to depress its bm25 relevance well below the chatty noise rows"}}"#
                ),
            );
        }

        let out = db
            .fts5_bm25_search(&RecallParams {
                query: "zebrafinch".to_string(),
                limit: 10,
                ..RecallParams::default()
            })
            .unwrap();
        let ids: Vec<&str> = out.iter().map(|(e, _)| e.id.as_str()).collect();
        assert!(
            !ids.iter().any(|id| id.starts_with("noise-")),
            "excluded-category rows must never leak into the sparse arm, got {ids:?}"
        );
        assert_eq!(
            ids.len(),
            3,
            "all in-scope hits must survive a filter-heavy pool (widened fetch), got {ids:?}"
        );
        for i in 0..3 {
            assert!(
                ids.contains(&format!("wanted-{i}").as_str()),
                "wanted-{i} missing from {ids:?}"
            );
        }

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn fts5_bm25_capped_scan_matches_exact_plan_when_cap_covers_matches() {
        // #589: the bounded-scan path (PERSEUS_VAULT_BM25_SCAN_CAP) must be an exact
        // no-op whenever the cap is >= the true match count — same rows, same
        // order, same scores as the exact two-phase plan — and must never
        // mutate access state. It is tested directly (not via the env var,
        // which is process-global and would race the parallel test runner);
        // the public entry point just reads that var and delegates here.
        let (db, path) = temp_db();
        let insert = |id: &str, body: &str| {
            let conn = db.conn().unwrap();
            conn.execute(
                "INSERT INTO entities (id, category, key, body_json, type, status,
                    retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                    decay_score, layer, archived)
                 VALUES (?1, 'insight', ?1, ?2, 'insight', 'active', 0, 0, 0, 1.0, 'working', 0)",
                params![id, body],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO entities_fts (rowid, body_json)
                 VALUES ((SELECT rowid FROM entities WHERE id = ?1), ?2)",
                params![id, body],
            )
            .unwrap();
        };
        // 40 rows matching "orbital" with varied term frequency + body length,
        // so bm25 produces a non-trivial ranking (not docid order).
        for i in 0..40 {
            let reps = "orbital ".repeat(1 + (i % 5));
            insert(
                &format!("row-{i:03}"),
                &format!(
                    r#"{{"note":"{reps}mechanics discussion number {i} with trailing prose"}}"#
                ),
            );
        }

        let qp = RecallParams {
            query: "orbital".to_string(),
            limit: 10,
            ..RecallParams::default()
        };

        // Exact plan (cap off).
        let exact = db.fts5_bm25_search(&qp).unwrap();
        assert_eq!(exact.len(), 10, "sanity: exact plan returns the top 10");

        // Capped plan with cap >= the full match set (40) must be identical.
        let conn = db.conn().unwrap();
        let fts_query = "\"orbital\"*".to_string();
        let capped = db
            .fts5_bm25_search_capped(&conn, &fts_query, &qp, 10, 4096)
            .unwrap();
        let exact_ids: Vec<&str> = exact.iter().map(|(e, _)| e.id.as_str()).collect();
        let capped_ids: Vec<&str> = capped.iter().map(|(e, _)| e.id.as_str()).collect();
        assert_eq!(
            capped_ids, exact_ids,
            "cap covering the whole match set must reproduce the exact plan's order"
        );
        for ((e_ex, s_ex), (e_cap, s_cap)) in exact.iter().zip(capped.iter()) {
            assert_eq!(e_ex.id, e_cap.id);
            assert!(
                (s_ex - s_cap).abs() < 1e-9,
                "scores must match exactly for {}: {s_ex} vs {s_cap}",
                e_ex.id
            );
        }

        // A cap far below the match set still returns <= cap valid hits (a
        // recall trade, never a crash or an over-long result).
        let tiny = db
            .fts5_bm25_search_capped(&conn, &fts_query, &qp, 10, 5)
            .unwrap();
        assert!(
            tiny.len() <= 5 && !tiny.is_empty(),
            "a cap of 5 bounds the candidate set to 5, got {}",
            tiny.len()
        );

        // Read-only: no retrieval_count mutation from either capped call.
        let touched: i64 = conn
            .query_row(
                "SELECT COALESCE(SUM(retrieval_count), 0) FROM entities",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(touched, 0, "capped sparse arm must not mutate access state");

        drop(conn);
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn hybrid_recall_is_read_only_and_idempotent() {
        // Regression for #247: like dense mode, hybrid recall issues no
        // access-state writes — repeated recalls return identical results and
        // never bump retrieval_count/last_accessed/decay. A caller-supplied query
        // embedding drives the dense arm so the test needs no ONNX backend.
        let (db, path) = temp_db();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let insert = |id: &str, key: &str, body: &str, emb: &[f32]| {
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, archived)
                     VALUES (?1, 'insight', ?2, ?3, 'insight', 'active', 0, 0, 0, 1.0, 'working', ?4, 0)",
                    params![id, key, body, blob(emb)],
                )
                .unwrap();
            // Keep the FTS index in sync so the keyword arm can match.
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities_fts (rowid, body_json)
                     VALUES ((SELECT rowid FROM entities WHERE id = ?1), ?2)",
                    params![id, body],
                )
                .unwrap();
        };
        insert(
            "e-coffee",
            "coffee",
            r#"{"note":"espresso every morning"}"#,
            &[1.0, 0.0, 0.0],
        );
        insert(
            "e-bike",
            "commute",
            r#"{"note":"bike to the office"}"#,
            &[0.0, 1.0, 0.0],
        );

        let params = RecallParams {
            query: "espresso".to_string(), // exercises the keyword arm too
            mode: crate::models::SearchMode::Hybrid,
            embedding: Some(vec![1.0, 0.0, 0.0]),
            limit: 10,
            ..RecallParams::default()
        };

        let first = db.recall(&params).unwrap();
        assert!(
            first.iter().any(|e| e.id == "e-coffee"),
            "hybrid recall should surface the matching entity"
        );

        // No access-state writes: counts/timestamps stay at their seeded zero.
        let (rc, la): (i64, i64) = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT retrieval_count, last_accessed_unix_ms FROM entities WHERE id = 'e-coffee'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(rc, 0, "hybrid recall must not bump retrieval_count");
        assert_eq!(la, 0, "hybrid recall must not touch last_accessed_unix_ms");

        // Idempotent: a second identical recall returns the same ordering.
        let second = db.recall(&params).unwrap();
        let ids1: Vec<&str> = first.iter().map(|e| e.id.as_str()).collect();
        let ids2: Vec<&str> = second.iter().map(|e| e.id.as_str()).collect();
        assert_eq!(ids1, ids2, "repeated hybrid recall must be idempotent");

        let _ = fs::remove_file(&path);
    }

    // ─── scope as a ranking multiplier (#485) ────────────────────

    #[test]
    fn scope_weight_widens_fts5_to_global_but_never_other_workspaces() {
        let (db, path) = temp_db();
        let insert = |id: &str, key: &str, ws: &str| {
            let body = r#"{"note":"grafana dashboard conventions for the fleet"}"#;
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, archived, workspace_hash)
                     VALUES (?1, 'insight', ?2, ?3, 'insight', 'active', 0, 0, 0, 1.0, 'working', 0, ?4)",
                    params![id, key, body, ws],
                )
                .unwrap();
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities_fts (rowid, body_json)
                     VALUES ((SELECT rowid FROM entities WHERE id = ?1), ?2)",
                    params![id, body],
                )
                .unwrap();
        };
        insert("s-local", "local-fact", "ws-a");
        insert("s-global", "global-fact", "");
        insert("s-other", "other-fact", "ws-b");

        let strict = RecallParams {
            query: "grafana".to_string(),
            workspace_hash: Some("ws-a".to_string()),
            limit: 10,
            skip_side_effects: true,
            ..RecallParams::default()
        };
        let hits = db.recall(&strict).unwrap();
        assert_eq!(
            hits.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(),
            vec!["s-local"],
            "no scope_weight = strict filter, byte-identical to before"
        );

        let widened = RecallParams {
            scope_weight: Some(0.5),
            ..strict
        };
        let hits = db.recall(&widened).unwrap();
        assert_eq!(
            hits.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(),
            vec!["s-local", "s-global"],
            "scope_weight widens to global with current scope first — and \
             NEVER surfaces another workspace's rows"
        );
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn scope_weight_ranks_current_scope_above_equal_global_in_hybrid() {
        // #485 acceptance: current-scope hits outrank EQUALLY-RELEVANT
        // broader-scope hits without dropping them. Identical bodies +
        // embeddings tie every arm; the global twin's id ("e-aaa") would win
        // the deterministic tie-break, so only the scope multiplier can put
        // the workspace twin first.
        let (db, path) = temp_db();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let insert = |id: &str, key: &str, ws: &str| {
            let body = r#"{"note":"postgres connection pool sizing guidance"}"#;
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, archived, workspace_hash)
                     VALUES (?1, 'insight', ?2, ?3, 'insight', 'active', 0, 0, 0, 1.0, 'working', ?4, 0, ?5)",
                    params![id, key, body, blob(&[1.0, 0.0, 0.0]), ws],
                )
                .unwrap();
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities_fts (rowid, body_json)
                     VALUES ((SELECT rowid FROM entities WHERE id = ?1), ?2)",
                    params![id, body],
                )
                .unwrap();
        };
        insert("e-aaa", "global-twin", "");
        insert("e-bbb", "local-twin", "ws-a");

        let recall_params = RecallParams {
            query: "postgres".to_string(),
            mode: crate::models::SearchMode::Hybrid,
            embedding: Some(vec![1.0, 0.0, 0.0]),
            workspace_hash: Some("ws-a".to_string()),
            scope_weight: Some(0.5),
            limit: 10,
            ..RecallParams::default()
        };
        let hits = db.recall(&recall_params).unwrap();
        assert_eq!(
            hits.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(),
            vec!["e-bbb", "e-aaa"],
            "current scope outranks its equally-relevant global twin, which \
             is down-weighted but NOT dropped"
        );

        // Without scope_weight the strict filter drops the global twin.
        let strict = RecallParams {
            scope_weight: None,
            ..recall_params
        };
        let hits = db.recall(&strict).unwrap();
        assert_eq!(
            hits.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(),
            vec!["e-bbb"],
            "zero params = zero behavior change"
        );
        let _ = fs::remove_file(&path);
    }

    // ─── derived_from usefulness (#487) ──────────────────────────

    #[test]
    fn usefulness_weight_is_log_damped_and_capped() {
        assert_eq!(usefulness_weight(0), 1.0, "no citations = no boost");
        assert_eq!(
            usefulness_weight(-3),
            1.0,
            "negative counts clamp to no boost"
        );
        assert!(usefulness_weight(1) > 1.0 && usefulness_weight(1) < 1.1);
        assert!(usefulness_weight(10) > usefulness_weight(1), "monotonic");
        assert!(
            usefulness_weight(1_000_000) <= 1.4 + 1e-12,
            "citation counts must never drown out relevance (cap 1.4)"
        );
    }

    #[test]
    fn derived_from_usefulness_slows_decay() {
        // #487 acceptance: repeatedly-derived-from memories survive a decay
        // pass longer than equally-stale never-reused ones.
        let (db, path) = temp_db();
        // Exactly one half-life stale: base decay ≈ e^-1 ≈ 0.368, comfortably
        // above the auto-archive threshold so both rows stay live and the
        // ordering assertion is about decay_score, not archival.
        let old = now_ms() - 7 * 24 * 60 * 60 * 1000;
        {
            let conn = db.conn().unwrap();
            let insert = |id: &str, key: &str, usefulness: i64| {
                conn.execute(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, archived, usefulness_count)
                     VALUES (?1, 'insight', ?2, '{}', 'insight', 'active', 0, ?3, ?3, 0.5, 'working', 0, ?4)",
                    params![id, key, old, usefulness],
                )
                .unwrap();
            };
            insert("d-plain", "plain", 0);
            insert("d-cited", "cited", 10);
        }
        db.decay_tick().unwrap();
        let conn = db.conn().unwrap();
        let get = |id: &str| -> f64 {
            conn.query_row(
                "SELECT decay_score FROM entities WHERE id = ?1",
                params![id],
                |r| r.get(0),
            )
            .unwrap()
        };
        assert!(
            get("d-cited") > get("d-plain"),
            "cited-and-reused memories must decay slower: cited={} plain={}",
            get("d-cited"),
            get("d-plain")
        );
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn hybrid_rank_boosts_derived_from_usefulness() {
        // #487 acceptance: a repeatedly-derived-from memory ranks above an
        // EQUALLY-RELEVANT never-reused one. Identical bodies + identical
        // embeddings make every arm tie, so without the usefulness term the
        // deterministic id tie-break puts "e-aaa" first; the boost on
        // "e-bbb" must flip that — and only ranking may change (the boost is
        // read-only, preserving #247 idempotence).
        let (db, path) = temp_db();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let insert = |id: &str, key: &str, usefulness: i64| {
            let body = r#"{"note":"espresso machine maintenance checklist"}"#;
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, archived, usefulness_count)
                     VALUES (?1, 'insight', ?2, ?3, 'insight', 'active', 0, 0, 0, 1.0, 'working', ?4, 0, ?5)",
                    params![id, key, body, blob(&[1.0, 0.0, 0.0]), usefulness],
                )
                .unwrap();
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities_fts (rowid, body_json)
                     VALUES ((SELECT rowid FROM entities WHERE id = ?1), ?2)",
                    params![id, body],
                )
                .unwrap();
        };
        insert("e-aaa", "twin-a", 0);
        insert("e-bbb", "twin-b", 5);

        let recall_params = RecallParams {
            query: "espresso".to_string(),
            mode: crate::models::SearchMode::Hybrid,
            embedding: Some(vec![1.0, 0.0, 0.0]),
            limit: 10,
            ..RecallParams::default()
        };
        let hits = db.recall(&recall_params).unwrap();
        assert_eq!(hits.len(), 2);
        assert_eq!(
            hits[0].id, "e-bbb",
            "the cited-and-reused twin must outrank its never-reused equal"
        );

        // Read-only: the boost queried but never wrote.
        let (u, la): (i64, i64) = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT usefulness_count, last_accessed_unix_ms FROM entities WHERE id = 'e-bbb'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(u, 5, "rank boost must not write usefulness_count");
        assert_eq!(la, 0, "rank boost must not touch last_accessed_unix_ms");

        // Deterministic and idempotent across repeated recalls.
        let again = db.recall(&recall_params).unwrap();
        assert_eq!(
            hits.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(),
            again.iter().map(|e| e.id.as_str()).collect::<Vec<_>>()
        );
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn hybrid_recall_reinforce_flag_bumps_returned_hits_opt_in_only() {
        // Opt-in counterpart to hybrid_recall_is_read_only_and_idempotent:
        // reinforce=true applies the standard side-effects to the returned
        // hits; skip_side_effects still wins over it.
        let (db, path) = temp_db();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        db.conn()
            .unwrap()
            .execute(
                "INSERT INTO entities (id, category, key, body_json, type, status,
                    retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                    decay_score, layer, embedding, archived)
                 VALUES ('e-r', 'insight', 'reinf', '{\"note\":\"espresso ritual\"}',
                         'insight', 'active', 0, 0, 0, 0.5, 'buffer', ?1, 0)",
                params![blob(&[1.0, 0.0, 0.0])],
            )
            .unwrap();
        db.conn()
            .unwrap()
            .execute(
                "INSERT INTO entities_fts (rowid, body_json)
                 VALUES ((SELECT rowid FROM entities WHERE id = 'e-r'), '{\"note\":\"espresso ritual\"}')",
                [],
            )
            .unwrap();

        // skip_side_effects wins over reinforce: still a pure read.
        let pure = RecallParams {
            query: "espresso".to_string(),
            mode: crate::models::SearchMode::Hybrid,
            embedding: Some(vec![1.0, 0.0, 0.0]),
            limit: 10,
            reinforce: true,
            skip_side_effects: true,
            ..RecallParams::default()
        };
        db.recall(&pure).unwrap();
        let rc: i64 = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT retrieval_count FROM entities WHERE id = 'e-r'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(rc, 0, "skip_side_effects must override reinforce");

        // reinforce alone: returned hit gets the standard side-effects.
        let reinforcing = RecallParams {
            skip_side_effects: false,
            ..pure
        };
        let hits = db.recall(&reinforcing).unwrap();
        assert!(hits.iter().any(|e| e.id == "e-r"), "hit expected");
        let (rc2, la2, ds2): (i64, i64, f64) = db
            .conn()
            .unwrap()
            .query_row(
                "SELECT retrieval_count, last_accessed_unix_ms, decay_score FROM entities WHERE id = 'e-r'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .unwrap();
        assert_eq!(rc2, 1, "reinforce must bump retrieval_count");
        assert!(la2 > 0, "reinforce must touch last_accessed");
        assert!(ds2 > 0.5, "reinforce must boost decay_score, got {ds2}");

        let _ = fs::remove_file(&path);
    }

    #[test]
    fn hybrid_over_fetches_arms_before_fusion() {
        // Each hybrid arm is fetched at a candidate pool LARGER than `limit`, then
        // RRF truncates to `limit`. This surfaces a cross-arm "consensus" hit that
        // ranks just past `limit` in BOTH arms individually: pre-truncating each
        // arm to `limit` would drop it from both inputs entirely, so it could
        // never win — even though appearing in both arms gives it the best fused
        // score. With limit=1: A is dense rank-1 (no keyword), B is keyword rank-1
        // (no dense), and W is rank-2 in *both*. Only over-fetch lets W win.
        //
        // C is a dense-only distractor (dense rank-3, no keyword) that pushes the
        // keyword-only B down to dense rank-4. Under equal-weight RRF (#309) this
        // keeps the cross-arm consensus W ahead of the single-arm leaders A and B,
        // so the test asserts the over-fetch property rather than a weight tie.
        let (db, path) = temp_db();
        let blob = |v: &[f32]| -> Vec<u8> { v.iter().flat_map(|f| f.to_le_bytes()).collect() };
        let insert = |id: &str, key: &str, body: &str, emb: &[f32]| {
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities (id, category, key, body_json, type, status,
                        retrieval_count, last_accessed_unix_ms, created_at_unix_ms,
                        decay_score, layer, embedding, archived)
                     VALUES (?1, 'insight', ?2, ?3, 'insight', 'active', 0, 0, 0, 1.0, 'working', ?4, 0)",
                    params![id, key, body, blob(emb)],
                )
                .unwrap();
            db.conn()
                .unwrap()
                .execute(
                    "INSERT INTO entities_fts (rowid, body_json)
                     VALUES ((SELECT rowid FROM entities WHERE id = ?1), ?2)",
                    params![id, body],
                )
                .unwrap();
        };
        // A: best dense (cos 1.0), no "zenith" → dense-only, dense rank 1.
        insert(
            "a-dense",
            "k1",
            r#"{"note":"alpha aurora"}"#,
            &[1.0, 0.0, 0.0],
        );
        // B: best keyword (zenith x4), worst dense (cos 0) → sparse-only, sparse rank 1.
        insert(
            "b-keyword",
            "k2",
            r#"{"note":"zenith zenith zenith zenith"}"#,
            &[0.0, 0.0, 1.0],
        );
        // W: rank 2 in BOTH arms — strong-ish dense (cos ~0.9) AND one "zenith".
        insert(
            "w-both",
            "k3",
            r#"{"note":"zenith alpha"}"#,
            &[0.9, 0.44, 0.0],
        );
        // C: dense-only distractor (cos 0.5, no "zenith") → dense rank 3, pushing
        // the keyword-only B to dense rank 4 so the consensus W wins at equal weight.
        insert(
            "c-dense2",
            "k4",
            r#"{"note":"alpha nebula"}"#,
            &[0.5, 0.866, 0.0],
        );

        let params = RecallParams {
            query: "zenith".to_string(),
            mode: crate::models::SearchMode::Hybrid,
            embedding: Some(vec![1.0, 0.0, 0.0]),
            limit: 1,
            ..RecallParams::default()
        };

        let out = db.recall(&params).unwrap();
        assert_eq!(out.len(), 1, "limit=1 must return exactly one result");
        assert_eq!(
            out[0].id, "w-both",
            "the cross-arm consensus hit (rank 2 in both arms) must win once arms \
             are over-fetched; pre-truncation would have dropped it and returned a-dense"
        );

        let _ = fs::remove_file(&path);
    }

