    #[test]
    fn deletion_residue_trace_corpus_runner() {
        // #990: runner wiring for the shared authority-trace corpus — the
        // deletion-residue traces describe states the residue model must
        // classify exactly; build each state through public surfaces and
        // assert the model outcome against the corpus contract.
        let corpus_path = format!(
            "{}/benchmark/security/traces/authority_traces.json",
            env!("CARGO_MANIFEST_DIR")
        );
        let corpus: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(&corpus_path).expect("read authority_traces.json"),
        )
        .expect("parse authority_traces.json");
        let traces: Vec<&serde_json::Value> = corpus["traces"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|t| t["residue_model"].is_object())
            .collect();
        assert!(
            !traces.is_empty(),
            "corpus must carry deletion-residue traces"
        );
        for trace in traces {
            let trace_id = trace["trace_id"].as_str().unwrap();
            let (db, _path) = temp_db();
            let mut supersede_seq = 0usize;
            for ev in trace["events"].as_array().unwrap() {
                let op = ev["operation"].as_str().unwrap();
                match op {
                    "remember_entity" => {
                        let entity = make_entity(
                            ev["entity_id"].as_str().unwrap(),
                            ev["category"].as_str().unwrap_or("insight"),
                            ev["key"].as_str().unwrap(),
                            ev["body"].as_str().unwrap(),
                        );
                        db.remember(&entity).unwrap();
                    }
                    "supersede_entity" => {
                        // Same (category, key) under a fresh id accumulates a
                        // retained superseded version in entity_history.
                        supersede_seq += 1;
                        let entity = make_entity(
                            &format!("{}-sup{}", ev["entity_id"].as_str().unwrap(), supersede_seq),
                            ev["category"].as_str().unwrap_or("insight"),
                            ev["key"].as_str().unwrap(),
                            ev["body"].as_str().unwrap(),
                        );
                        db.remember(&entity).unwrap();
                    }
                    "embed_entity" => {
                        let id = ev["target"].as_str().unwrap().trim_start_matches("entity:");
                        let vec: Vec<f32> = (0..8)
                            .map(|i| (id.as_bytes().get(i).copied().unwrap_or(0) as f32) / 255.0)
                            .collect();
                        let conn = db.conn().unwrap();
                        Database::store_embedding_with_conn(&conn, id, &vec, EmbeddingQuant::F32)
                            .unwrap();
                    }
                    "snapshot_entity" => {
                        let id = ev["target"].as_str().unwrap().trim_start_matches("entity:");
                        let conn = db.conn().unwrap();
                        conn.execute(
                            "INSERT INTO entities_embedding_snapshot (id, embedding, created_at_unix_ms)
                             VALUES (?1, X'00', ?2)",
                            params![id, now_ms()],
                        )
                        .unwrap();
                    }
                    "archive_entity" => {
                        db.forget(
                            ev["category"].as_str().unwrap_or("insight"),
                            ev["key"].as_str().unwrap(),
                            "trace-archive",
                        )
                        .unwrap();
                    }
                    "purge" => {
                        let expected = trace["expected_decision"].as_str().unwrap();
                        match db.purge(false) {
                            Ok(_) => assert_eq!(
                                expected, "accept",
                                "{trace_id}: purge accepted but corpus expects {expected}"
                            ),
                            Err(e) => assert_eq!(
                                expected, "reject",
                                "{trace_id}: purge refused ({e}) but corpus expects {expected}"
                            ),
                        }
                    }
                    "sweep" => { /* asserted below */ }
                    other => panic!("{trace_id}: unknown corpus operation {other}"),
                }
            }
            // Final independent sweep must match the corpus contract.
            let sweep = db.residue_sweep().unwrap();
            let model = &trace["residue_model"];
            assert_eq!(
                sweep.undeclared_total,
                model["expected_undeclared_total"].as_u64().unwrap() as usize,
                "{trace_id}: undeclared total mismatch"
            );
            assert_eq!(
                sweep.hard_gate_passed,
                model["expected_gate"].as_bool().unwrap(),
                "{trace_id}: hard gate mismatch"
            );
        }
    }

    #[test]
    fn remediation_trace_corpus_runner() {
        // #1032: runner wiring for the remediation/compensation trace family —
        // each event replays through the live AAR surfaces (authority_set /
        // action_intent / action_complete / authority_revoke /
        // finding_record) and the outcome + reason code are asserted against
        // the corpus contract. Refs of the form "ref:<event_id>" resolve to
        // the real record ids created during replay.
        let corpus_path = format!(
            "{}/benchmark/security/traces/authority_traces.json",
            env!("CARGO_MANIFEST_DIR")
        );
        let corpus: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(&corpus_path).expect("read authority_traces.json"),
        )
        .expect("parse authority_traces.json");
        let traces: Vec<&serde_json::Value> = corpus["traces"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|t| t["remediation_model"].is_object())
            .collect();
        assert!(
            traces.len() >= 4,
            "corpus must carry the remediation trace family"
        );

        let ws = "ws-trace-rem";

        fn resolve(refs: &std::collections::HashMap<String, String>, r: &str) -> String {
            match r.strip_prefix("ref:") {
                Some(ev) => refs
                    .get(ev)
                    .cloned()
                    .unwrap_or_else(|| panic!("unresolved corpus ref {r}")),
                None => r.to_string(),
            }
        }

        for trace in traces {
            let trace_id = trace["trace_id"].as_str().unwrap();
            let (db, _path) = temp_db();
            let mut refs: std::collections::HashMap<String, String> =
                std::collections::HashMap::new();
            for ev in trace["events"].as_array().unwrap() {
                let op = ev["operation"].as_str().unwrap();
                match op {
                    "grant" => {
                        let agent = ev["actor_id"].as_str().unwrap();
                        db.agent_upsert(agent, "Trace", 3, "trace").unwrap();
                        let caps: Vec<String> = ev["allowed_capabilities"]
                            .as_array()
                            .unwrap()
                            .iter()
                            .map(|c| c.as_str().unwrap().to_string())
                            .collect();
                        let manifest = db
                            .authority_set(
                                &crate::models::AuthorityManifestInput {
                                    agent_id: agent.to_string(),
                                    workspace_hash: ws.to_string(),
                                    allowed_capabilities: caps,
                                    approval_required_capabilities: vec![],
                                    scope_anchors: vec!["trace-scope".to_string()],
                                    approver_principals: vec![],
                                    allowed_inbound_principals: vec![],
                                    permitted_external_ref_prefixes: vec!["trace-ref".to_string()],
                                    max_parallel_actions: 8,
                                    mode: "enforce".to_string(),
                                    expires_at_unix_ms: None,
                                    capability_constraints_json: "{}".to_string(),
                                },
                                "admin",
                            )
                            .unwrap();
                        refs.insert(
                            ev["event_id"].as_str().unwrap().to_string(),
                            manifest.id.clone(),
                        );
                    }
                    "execute_action" => {
                        let agent = ev["actor_id"].as_str().unwrap();
                        let action = db
                            .action_intent(
                                agent,
                                ws,
                                "trace-scope",
                                "trace-ref",
                                ev["capability"].as_str().unwrap(),
                                ev["action_key"].as_str().unwrap(),
                                &"c".repeat(64),
                                Some("{}"),
                                &[],
                                None,
                            )
                            .unwrap();
                        let action = db
                            .action_complete(&action.id, agent, "executed", &"d".repeat(64))
                            .unwrap();
                        refs.insert(
                            ev["event_id"].as_str().unwrap().to_string(),
                            action.id.clone(),
                        );
                    }
                    "record_finding" => {
                        let covers: Vec<String> = ev["covers"]
                            .as_array()
                            .unwrap()
                            .iter()
                            .map(|c| resolve(&refs, c.as_str().unwrap()))
                            .collect();
                        db.finding_record(
                            ws,
                            ev["actor_id"].as_str().unwrap(),
                            ev["finding_ref"].as_str().unwrap(),
                            "insight",
                            "fact",
                            "",
                            ev["cited_head"].as_str().unwrap(),
                            &covers,
                            ev["basis"].as_str().unwrap(),
                        )
                        .unwrap();
                    }
                    "revoke" => {
                        let manifest_id = resolve(&refs, ev["grant_ref"].as_str().unwrap());
                        db.authority_revoke(&manifest_id, "operator", "trace revoke")
                            .unwrap();
                    }
                    "handoff" => {
                        let agent = ev["actor_id"].as_str().unwrap();
                        let effects: Vec<String> = ev["original_effects"]
                            .as_array()
                            .unwrap()
                            .iter()
                            .map(|e| resolve(&refs, e.as_str().unwrap()))
                            .collect();
                        let constraints = serde_json::json!({
                            "beneficiary_agent_id": ev["beneficiary_agent_id"].as_str().unwrap(),
                            "original_effects": effects,
                        })
                        .to_string();
                        let action = db
                            .action_intent(
                                agent,
                                ws,
                                "trace-scope",
                                "trace-ref",
                                "remediation_handoff",
                                "handoff",
                                &"e".repeat(64),
                                Some(&constraints),
                                &[],
                                None,
                            )
                            .unwrap();
                        let action = db
                            .action_complete(&action.id, agent, "executed", &"f".repeat(64))
                            .unwrap();
                        refs.insert(
                            ev["event_id"].as_str().unwrap().to_string(),
                            action.id.clone(),
                        );
                    }
                    "compensate" => {
                        let agent = ev["actor_id"].as_str().unwrap();
                        let effect = resolve(&refs, ev["compensates_for"].as_str().unwrap());
                        let handoff = if ev["handoff_receipt_ref"].as_str().unwrap_or("").is_empty()
                        {
                            String::new()
                        } else {
                            resolve(&refs, ev["handoff_receipt_ref"].as_str().unwrap())
                        };
                        let linkage = crate::models::CompensationLinkage {
                            compensates_for: effect.clone(),
                            finding_ref: ev["finding_ref"].as_str().unwrap_or("").to_string(),
                            superseding_head: ev["superseding_head"]
                                .as_str()
                                .unwrap_or("")
                                .to_string(),
                            handoff_receipt_ref: handoff,
                        };
                        let result = db.action_intent(
                            agent,
                            ws,
                            "trace-scope",
                            "trace-ref",
                            "execute_action",
                            "compensation",
                            &"c".repeat(64),
                            Some("{}"),
                            &[],
                            Some(&linkage),
                        );
                        if trace["expected_decision"] == "reject"
                            || ev["expected_reason_code"].is_string()
                        {
                            let err = result
                                .expect_err(&format!("{trace_id}: compensation should fail"))
                                .to_string();
                            if let Some(code) = ev["expected_reason_code"].as_str() {
                                assert!(
                                    err.contains(code),
                                    "{trace_id}: expected reason code {code:?} in: {err}"
                                );
                            }
                        } else {
                            let action =
                                result.expect(&format!("{trace_id}: compensation should pass"));
                            assert_eq!(action.compensates_for, effect);
                            assert_eq!(action.finding_ref, ev["finding_ref"].as_str().unwrap());
                            assert_eq!(
                                action.superseding_head,
                                ev["superseding_head"].as_str().unwrap()
                            );
                            let handoff_ref = ev["handoff_receipt_ref"].as_str().unwrap();
                            assert_eq!(
                                action.handoff_receipt_ref,
                                resolve(&refs, handoff_ref),
                                "{trace_id}: handoff receipt must be part of the evidence set"
                            );
                        }
                    }
                    other => panic!("{trace_id}: unknown remediation operation {other}"),
                }
            }

            // Corpus-contract assertions.
            let model = &trace["remediation_model"];
            if model["historical_authenticity"].is_object()
                && model["historical_authenticity"]["retained"] == serde_json::Value::Bool(true)
            {
                let effect_event_id = trace["events"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .find(|e| e["operation"] == "execute_action")
                    .expect("remediation trace must contain an execute_action event")["event_id"]
                    .as_str()
                    .unwrap()
                    .to_string();
                let effect = refs
                    .get(&effect_event_id)
                    .cloned()
                    .unwrap_or_else(|| panic!("{trace_id}: effect id not mapped"));
                let original = db
                    .action_receipt_get(&effect)
                    .unwrap()
                    .expect("original effect receipt must still verify historically");
                assert_eq!(original.status, "action_executed");
            }
            if model["no_compensation_effect"] == serde_json::Value::Bool(true) {
                let count: i64 = db
                    .conn()
                    .unwrap()
                    .query_row(
                        "SELECT COUNT(*) FROM authorized_actions WHERE compensates_for != ''",
                        [],
                        |r| r.get(0),
                    )
                    .unwrap();
                assert_eq!(
                    count, 0,
                    "{trace_id}: a compensation effect record was created"
                );
            }
            if let Some(state) = model["finding_final_state"].as_str() {
                let finding_ref = trace["events"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .find(|e| e["operation"] == "record_finding")
                    .expect("remediation trace must record a finding")["finding_ref"]
                    .as_str()
                    .unwrap();
                let finding = db
                    .finding_get(ws, finding_ref)
                    .unwrap()
                    .expect("finding must exist");
                assert_eq!(finding.status, state, "{trace_id}: finding state mismatch");
            }
        }
    }

    #[test]
    fn purge_dry_run_dedupes_journal_rows_shared_across_workspaces() {
        let (db, path) = temp_db();
        let mut e1 = make_entity("e-ws-a", "facts", "shared", r#"{"n":"a"}"#);
        e1.workspace_hash = "wsA".to_string();
        db.remember(&e1).unwrap();
        let mut e2 = make_entity("e-ws-b", "facts", "shared", r#"{"n":"b"}"#);
        e2.workspace_hash = "wsB".to_string();
        db.remember(&e2).unwrap();

        // One journal row referencing the key only (no entity_id): both
        // doomed entities match it via the category/key predicate.
        db.journal(&crate::models::JournalEvent {
            id: "jrn-ws-shared".to_string(),
            event_type: "decision".to_string(),
            evaluated_json: r#"{"k":"shared"}"#.to_string(),
            acted_json: "{}".to_string(),
            forward_json: "{}".to_string(),
            category: "facts".to_string(),
            key: "shared".to_string(),
            entity_id: String::new(),
            agent_id: "test".to_string(),
            workspace_hash: String::new(),
            created_at_unix_ms: now_ms(),
        })
        .unwrap();

        assert!(db.forget("facts", "shared", "test").unwrap()); // archives both
        let dry = db.purge(true).unwrap();
        assert_eq!(dry.entities_deleted, 2);
        assert_eq!(
            dry.journal_rows_redacted, 3,
            "the shared row once, plus one interference telemetry row per entity"
        );
        let actual = db.purge(false).unwrap();
        assert_eq!(dry.journal_rows_redacted, actual.journal_rows_redacted);
        assert_eq!(dry.history_rows_deleted, actual.history_rows_deleted);
        let _ = fs::remove_file(&path);
    }

    /// #417: purging one workspace's entity must NOT redact another workspace's
    /// LIVE same-key journal rows. Before the workspace_hash column the
    /// (category, key) redaction match was workspace-blind and scrubbed
    /// workspace B's audit payloads when workspace A was purged.
    #[test]
    fn purge_does_not_redact_other_workspace_live_journal_rows() {
        let (db, path) = temp_db();

        // Two LIVE entities: same (category, key), different workspaces. Identity
        // is (category, key, workspace_hash) (#339), so neither supersedes the other.
        let mut e_a = make_entity("e-a", "facts", "k", r#"{"n":"a"}"#);
        e_a.workspace_hash = "wsA".to_string();
        db.remember(&e_a).unwrap();
        let mut e_b = make_entity("e-b", "facts", "k", r#"{"n":"b"}"#);
        e_b.workspace_hash = "wsB".to_string();
        db.remember(&e_b).unwrap();

        // One journal row per entity, referenced by id. journal() derives and
        // stamps each row's workspace from the referenced entity.
        db.journal(&crate::models::JournalEvent {
            id: "jrn-a".to_string(),
            event_type: "decision".to_string(),
            evaluated_json: r#"{"secret":"A-only"}"#.to_string(),
            acted_json: "{}".to_string(),
            forward_json: "{}".to_string(),
            category: "facts".to_string(),
            key: "k".to_string(),
            entity_id: "e-a".to_string(),
            agent_id: "test".to_string(),
            workspace_hash: String::new(),
            created_at_unix_ms: now_ms(),
        })
        .unwrap();
        db.journal(&crate::models::JournalEvent {
            id: "jrn-b".to_string(),
            event_type: "decision".to_string(),
            evaluated_json: r#"{"keep":"B-live"}"#.to_string(),
            acted_json: "{}".to_string(),
            forward_json: "{}".to_string(),
            category: "facts".to_string(),
            key: "k".to_string(),
            entity_id: "e-b".to_string(),
            agent_id: "test".to_string(),
            workspace_hash: String::new(),
            created_at_unix_ms: now_ms() + 1,
        })
        .unwrap();

        // journal() must have stamped each row with its referenced entity's workspace.
        {
            let conn = db.conn().unwrap();
            let ws_a: String = conn
                .query_row(
                    "SELECT workspace_hash FROM journal WHERE id='jrn-a'",
                    [],
                    |r| r.get(0),
                )
                .unwrap();
            let ws_b: String = conn
                .query_row(
                    "SELECT workspace_hash FROM journal WHERE id='jrn-b'",
                    [],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(
                ws_a, "wsA",
                "journal() must stamp the referenced entity's workspace"
            );
            assert_eq!(ws_b, "wsB");
        }

        // Archive ONLY workspace A's entity, then purge. (forget by (category,
        // key) is workspace-blind, so archive e-a directly to isolate wsA.)
        {
            let conn = db.conn().unwrap();
            conn.execute("UPDATE entities SET archived = 1 WHERE id = 'e-a'", [])
                .unwrap();
        }
        let report = db.purge(false).unwrap();
        assert_eq!(report.entities_deleted, 1);
        assert_eq!(
            report.journal_rows_redacted, 2,
            "workspace A's journal row AND its interference_scored telemetry row redacted"
        );

        let conn = db.conn().unwrap();
        // wsA's row is redacted...
        let a_type: String = conn
            .query_row("SELECT event_type FROM journal WHERE id='jrn-a'", [], |r| {
                r.get(0)
            })
            .unwrap();
        assert_eq!(a_type, "redacted");
        // ...but wsB's LIVE row is untouched — payload and identity intact.
        let (b_type, b_eval, b_cat): (String, String, String) = conn
            .query_row(
                "SELECT event_type, evaluated_json, category FROM journal WHERE id='jrn-b'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .unwrap();
        assert_eq!(
            b_type, "decision",
            "another workspace's live journal row must not be redacted (#417)"
        );
        assert!(
            b_eval.contains("B-live"),
            "another workspace's payload must survive"
        );
        assert_eq!(b_cat, "facts");

        drop(conn);
        verify_audit_chain(&db).expect("audit chain must survive workspace-scoped redaction");

        let _ = fs::remove_file(&path);
    }

    fn retention_policy(
        age: Option<i64>,
        cap: Option<i64>,
        bytes: Option<i64>,
        tombstones: bool,
    ) -> crate::models::HistoryRetentionPolicy {
        crate::models::HistoryRetentionPolicy {
            max_age_days: age,
            max_versions_per_key: cap,
            max_bytes: bytes,
            tombstones,
        }
    }

    /// Write `n` distinct versions of facts/versioned-key, 3ms apart, and
    /// return the first version's recorded_at. n remembers → n-1 history rows.
    fn seed_versions(db: &Database, n: usize) -> i64 {
        use std::thread::sleep;
        use std::time::Duration;
        let mut t_first = 0i64;
        for i in 0..n {
            db.remember(&make_entity(
                &format!("e-ret-{i}"),
                "facts",
                "versioned-key",
                &format!(r#"{{"note":"version {i} with some padding body text"}}"#),
            ))
            .unwrap();
            if i == 0 {
                let conn = db.conn().unwrap();
                t_first = conn
                    .query_row(
                        "SELECT COALESCE(recorded_at_unix_ms, created_at_unix_ms) \
                         FROM entities WHERE category='facts' AND key='versioned-key'",
                        [],
                        |r| r.get(0),
                    )
                    .unwrap();
            }
            sleep(Duration::from_millis(3));
        }
        t_first
    }

    fn history_count(db: &Database) -> i64 {
        let conn = db.conn().unwrap();
        conn.query_row("SELECT COUNT(*) FROM entity_history", [], |r| r.get(0))
            .unwrap()
    }

    /// #398: default policy (no knobs) must be a guaranteed no-op — today's
    /// keep-everything behavior is preserved unless an operator opts in.
    #[test]
    fn history_retention_is_a_noop_with_no_knobs_set() {
        let (db, path) = temp_db();
        seed_versions(&db, 4);
        let before = history_count(&db);
        assert_eq!(before, 3);
        let report = db
            .enforce_history_retention(&retention_policy(None, None, None, true), false)
            .unwrap();
        assert_eq!(report.rows_evicted, 0);
        assert_eq!(
            history_count(&db),
            before,
            "unlimited policy must not touch history"
        );
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn encrypted_invalidate_indexes_history_fts_with_blind_tokens() {
        let (mut db, path) = temp_db();
        let (key_path, _) = temp_key_file();
        db.set_encryption(&key_path).unwrap();
        db.remember_skip_dedup(&make_entity(
            "invalidate-winner",
            "facts",
            "winner",
            r#"{"note":"winner"}"#,
        ))
        .unwrap();
        db.remember_skip_dedup(&make_entity(
            "invalidate-loser",
            "facts",
            "loser",
            r#"{"note":"invalidation-history-fts-sentinel-1180"}"#,
        ))
        .unwrap();

        assert!(db
            .invalidate_entity("invalidate-loser", "invalidate-winner")
            .unwrap());

        let conn = db.conn().unwrap();
        let history: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM entity_history WHERE id = 'invalidate-loser'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let indexed: String = conn
            .query_row(
                "SELECT body_json FROM entity_history_fts WHERE rowid = (\
                 SELECT rowid FROM entity_history WHERE id = 'invalidate-loser')",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(history, 1, "invalidated entity must remain in history");
        assert!(
            indexed.split_whitespace().all(|token| {
                token.len() == 64 && token.bytes().all(|byte| byte.is_ascii_hexdigit())
            }),
            "encrypted history FTS must contain only blind tokens: {indexed}"
        );
        assert!(
            !indexed.contains("invalidation-history-fts-sentinel-1180"),
            "history FTS must not contain the plaintext body"
        );
        drop(conn);
        let _ = fs::remove_file(&key_path);
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn encrypted_invalidate_reencrypts_legacy_plaintext_history_body() {
        let (mut db, path) = temp_db();
        let (key_path, _) = temp_key_file();
        db.set_encryption(&key_path).unwrap();
        db.remember_skip_dedup(&make_entity(
            "invalidate-legacy-winner",
            "facts",
            "winner",
            r#"{"note":"winner"}"#,
        ))
        .unwrap();
        db.remember_skip_dedup(&make_entity(
            "invalidate-legacy-loser",
            "facts",
            "loser",
            r#"{"note":"legacy invalidation body"}"#,
        ))
        .unwrap();

        let legacy = r#"{"note":"legacy invalidation body"}"#;
        let conn = db.conn().unwrap();
        conn.execute(
            "UPDATE entities SET body_json = ?1 WHERE id = ?2",
            params![legacy, "invalidate-legacy-loser"],
        )
        .unwrap();
        drop(conn);

        assert!(db
            .invalidate_entity("invalidate-legacy-loser", "invalidate-legacy-winner")
            .unwrap());

        let conn = db.conn().unwrap();
        let history_body: String = conn
            .query_row(
                "SELECT body_json FROM entity_history WHERE id = ?1",
                params!["invalidate-legacy-loser"],
                |row| row.get(0),
            )
            .unwrap();
        assert_ne!(
            history_body, legacy,
            "invalidation must not copy a legacy plaintext body into history"
        );
        assert!(
            !history_body.contains("legacy invalidation body"),
            "invalidation history body must not retain plaintext"
        );

        let history_index: String = conn
            .query_row(
                "SELECT body_json FROM entity_history_fts WHERE rowid = (\
                 SELECT rowid FROM entity_history WHERE id = ?1)",
                params!["invalidate-legacy-loser"],
                |row| row.get(0),
            )
            .unwrap();
        assert!(
            history_index.split_whitespace().all(|token| {
                token.len() == 64 && token.bytes().all(|byte| byte.is_ascii_hexdigit())
            }),
            "encrypted invalidation history FTS must contain only blind tokens"
        );
        assert!(
            !history_index.contains("legacy invalidation body"),
            "invalidation history FTS must not contain plaintext"
        );
        drop(conn);
        drop(db);
        let _ = std::fs::remove_file(&key_path);
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn encrypted_erase_removes_history_fts_rows_before_history() {
        let (mut db, path) = temp_db();
        let (key_path, _) = temp_key_file();
        db.set_encryption(&key_path).unwrap();
        seed_versions(&db, 4);

        let before: i64 = db
            .conn()
            .unwrap()
            .query_row("SELECT COUNT(*) FROM entity_history_fts", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert!(before > 0);

        db.erase_entity("facts", "versioned-key", "", "test-agent", false)
            .unwrap();

        let conn = db.conn().unwrap();
        let history: i64 = conn
            .query_row("SELECT COUNT(*) FROM entity_history", [], |row| row.get(0))
            .unwrap();
        let fts: i64 = conn
            .query_row("SELECT COUNT(*) FROM entity_history_fts", [], |row| {
                row.get(0)
            })
            .unwrap();
        let orphans: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM entity_history_fts AS f
                 WHERE NOT EXISTS (SELECT 1 FROM entity_history AS h WHERE h.rowid = f.rowid)",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(history, 0, "erase must remove all history rows");
        assert_eq!(fts, 0, "erase must remove all history FTS rows");
        assert_eq!(orphans, 0, "erase must not leave orphaned history FTS rows");
        drop(conn);
        let _ = fs::remove_file(&key_path);
        let _ = fs::remove_file(&path);
    }

    #[test]
    fn encrypted_history_retention_encrypts_tombstones_and_rebuilds_fts() {
        let (mut db, path) = temp_db();
        let (key_path, _) = temp_key_file();
        db.set_encryption(&key_path).unwrap();
        seed_versions(&db, 4); // 3 encrypted history rows

        let report = db
            .enforce_history_retention(&retention_policy(None, Some(1), None, true), false)
            .unwrap();
        assert_eq!(report.rows_evicted, 2);
        assert_eq!(report.tombstones_written, 1);

        let conn = db.conn().unwrap();
        let tombstone: String = conn
            .query_row(
                "SELECT body_json FROM entity_history WHERE status = 'compacted'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert!(
            !tombstone.starts_with('{'),
            "encrypted retention tombstone must not be plaintext: {tombstone}"
        );
        let missing: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM entity_history AS h
                 WHERE NOT EXISTS (SELECT 1 FROM entity_history_fts AS f WHERE f.rowid = h.rowid)",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(missing, 0, "retention must keep history FTS synchronized");
        let invalid_tokens: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM entity_history_fts
                 WHERE body_json <> '' AND body_json GLOB '*[^0-9A-Fa-f ]*'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            invalid_tokens, 0,
            "encrypted history FTS must remain blind-token only"
        );
        drop(conn);

        let marker = db
            .history_versions("facts", "versioned-key")
            .unwrap()
            .into_iter()
            .find(|entity| entity.status == "compacted")
            .expect("retained compacted history must remain readable");
        assert_eq!(marker.status, "compacted");
        assert!(marker.body_json.contains("\"compacted\":true"));
        let _ = fs::remove_file(&key_path);
        let _ = fs::remove_file(&path);
    }

    /// #398: per-key version cap evicts the oldest run, replaces it with ONE
    /// tombstone, and as_of inside the compacted window returns the explicit
    /// 'compacted' marker instead of silence or wrong data. Instants covered
    /// by surviving rows are answered exactly as before.
    #[test]
    fn history_retention_version_cap_writes_tombstone_and_as_of_marks_it() {
        let (db, path) = temp_db();
        let t_first = seed_versions(&db, 6); // 5 history rows
        assert_eq!(history_count(&db), 5);

        let report = db
            .enforce_history_retention(&retention_policy(None, Some(2), None, true), false)
            .unwrap();
        assert_eq!(report.rows_evicted, 3, "5 stored - cap 2 = 3 evicted");
        assert_eq!(report.tombstones_written, 1);
        assert_eq!(report.keys_affected, 1);
        assert_eq!(history_count(&db), 3, "2 survivors + 1 tombstone");

        // The tombstone carries count + digest and spans the evicted windows.
        let conn = db.conn().unwrap();
        let (status, body): (String, String) = conn
            .query_row(
                "SELECT status, body_json FROM entity_history WHERE status='compacted'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
        assert_eq!(status, "compacted");
        let marker: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(marker["compacted"], serde_json::json!(true));
        assert_eq!(marker["versions"], serde_json::json!(3));
        assert!(marker["digest"].as_str().unwrap().len() == 16);
        drop(conn);

        // as_of inside the compacted window → explicit marker.
        let inside = db
            .as_of("facts", "versioned-key", t_first)
            .unwrap()
            .expect("compacted window must still answer, with a marker");
        assert_eq!(inside.status, "compacted");
        assert!(inside.body_json.contains("\"versions\":3"));
        // Public history must not re-expand arbitrary metadata from the
        // compacted Entity row. This sentinel simulates stale/tampered metadata
        // that is not part of the compacted audit marker allowlist.
        let conn = db.conn().unwrap();
        conn.execute(
            "UPDATE entity_history SET tags='[\"HISTORY METADATA SENTINEL\"]',
                    archive_reason='HISTORY ARCHIVE SENTINEL',
                    source='HISTORY SOURCE SENTINEL',
                    agent_id='HISTORY AGENT SENTINEL',
                    visibility='private'
             WHERE status='compacted'",
            [],
        )
        .unwrap();
        drop(conn);
        let history = crate::tools::handle_history(
            &db,
            serde_json::json!({
                "category": "facts",
                "key": "versioned-key",
                "limit": 100,
                "offset": 0
            }),
        )
        .unwrap();
        assert!(!history.contains("HISTORY METADATA SENTINEL"));
        assert!(!history.contains("HISTORY ARCHIVE SENTINEL"));
        assert!(!history.contains("HISTORY SOURCE SENTINEL"));
        assert!(!history.contains("HISTORY AGENT SENTINEL"));

        // as_of inside a SURVIVING window → the real old version, unchanged.
        let conn = db.conn().unwrap();
        let (surv_rec,): (i64,) = conn
            .query_row(
                "SELECT COALESCE(recorded_at_unix_ms, created_at_unix_ms) FROM entity_history \
                 WHERE status != 'compacted' ORDER BY invalidated_at_unix_ms DESC LIMIT 1",
                [],
                |r| Ok((r.get(0)?,)),
            )
            .unwrap();
        drop(conn);
        let survivor = db
            .as_of("facts", "versioned-key", surv_rec)
            .unwrap()
            .expect("surviving window must answer normally");
        assert_ne!(survivor.status, "compacted");
        assert!(survivor.body_json.contains("version 4"));

        let _ = fs::remove_file(&path);
    }

    /// #398: age bound evicts only rows invalidated before the cutoff.
    #[test]
    fn history_retention_age_bound_evicts_only_old_rows() {
        let (db, path) = temp_db();
        seed_versions(&db, 5); // 4 history rows
                               // Back-date the 2 oldest versions by 3 days.
        {
            let conn = db.conn().unwrap();
            conn.execute(
                "UPDATE entity_history SET \
                     invalidated_at_unix_ms = invalidated_at_unix_ms - 259200000, \
                     recorded_at_unix_ms = COALESCE(recorded_at_unix_ms, created_at_unix_ms) - 259200000, \
                     created_at_unix_ms = created_at_unix_ms - 259200000 \
                 WHERE history_id IN (SELECT history_id FROM entity_history \
                                      ORDER BY invalidated_at_unix_ms ASC LIMIT 2)",
                [],
            )
            .unwrap();
        }
        let report = db
            .enforce_history_retention(&retention_policy(Some(1), None, None, true), false)
            .unwrap();
        assert_eq!(report.rows_evicted, 2, "only the back-dated rows age out");
        assert_eq!(report.tombstones_written, 1);
        assert_eq!(history_count(&db), 3, "2 fresh survivors + 1 tombstone");
        let _ = fs::remove_file(&path);
    }

    /// #398: global byte budget evicts globally-oldest until under budget.
    #[test]
    fn history_retention_byte_budget_evicts_globally_oldest_first() {
        let (db, path) = temp_db();
        seed_versions(&db, 5); // 4 history rows, equal-sized bodies
        let conn = db.conn().unwrap();
        let (total, per_row, oldest_id): (i64, i64, String) = conn
            .query_row(
                "SELECT SUM(LENGTH(body_json)), MAX(LENGTH(body_json)), \
                        (SELECT history_id FROM entity_history ORDER BY invalidated_at_unix_ms ASC LIMIT 1) \
                 FROM entity_history",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .unwrap();
        drop(conn);
        // Budget that forces exactly one eviction (equal-sized rows).
        let budget = total - 1;
        let report = db
            .enforce_history_retention(&retention_policy(None, None, Some(budget), true), false)
            .unwrap();
        assert_eq!(report.rows_evicted, 1, "one row over budget → one eviction");
        assert!(report.bytes_evicted >= per_row - 2 && report.bytes_evicted <= per_row);
        let conn = db.conn().unwrap();
        let gone: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM entity_history WHERE history_id = ?1",
                params![oldest_id],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(gone, 0, "the globally-oldest row must be the one evicted");
        let _ = fs::remove_file(&path);
    }

    /// #398: dry_run computes the identical eviction set — counts match the
    /// subsequent real run exactly, and nothing is mutated.
    #[test]
    fn history_retention_dry_run_counts_match_actual_run() {
        let (db, path) = temp_db();
        seed_versions(&db, 6); // 5 history rows
        let policy = retention_policy(None, Some(2), None, true);

        let before = history_count(&db);
        let dry = db.enforce_history_retention(&policy, true).unwrap();
        assert!(dry.dry_run);
        assert_eq!(history_count(&db), before, "dry_run must not mutate");

        let actual = db.enforce_history_retention(&policy, false).unwrap();
        assert_eq!(dry.rows_evicted, actual.rows_evicted);
        assert_eq!(dry.bytes_evicted, actual.bytes_evicted);
        assert_eq!(dry.tombstones_written, actual.tombstones_written);
        assert_eq!(dry.keys_affected, actual.keys_affected);
        let _ = fs::remove_file(&path);
    }

    /// #398: a later pass folds the existing tombstone into the new one —
    /// version counts accumulate and exactly one tombstone remains per key.
    #[test]
    fn history_retention_second_pass_merges_prior_tombstone() {
        use std::thread::sleep;
        use std::time::Duration;
        let (db, path) = temp_db();
        seed_versions(&db, 6); // h1..h5
        let policy = retention_policy(None, Some(2), None, true);
        db.enforce_history_retention(&policy, false).unwrap(); // tomb(3) + h4,h5

        let conn = db.conn().unwrap();
        let first_digest: String = conn
            .query_row(
                "SELECT body_json FROM entity_history WHERE status='compacted'",
                [],
                |r| r.get(0),
            )
            .map(|b: String| {
                serde_json::from_str::<serde_json::Value>(&b).unwrap()["digest"]
                    .as_str()
                    .unwrap()
                    .to_string()
            })
            .unwrap();
        drop(conn);

        // Three more versions, then enforce again.
        for i in 0..3 {
            sleep(Duration::from_millis(3));
            db.remember(&make_entity(
                &format!("e-ret2-{i}"),
                "facts",
                "versioned-key",
                &format!(r#"{{"note":"second wave {i}"}}"#),
            ))
            .unwrap();
        }
        // rows now: tomb(3), h4, h5, h6 (+2 newest) = 6 → cap 2 evicts 4.
        let report = db.enforce_history_retention(&policy, false).unwrap();
        assert_eq!(report.rows_evicted, 4);

        let conn = db.conn().unwrap();
        let tombs: Vec<String> = {
            let mut stmt = conn
                .prepare("SELECT body_json FROM entity_history WHERE status='compacted'")
                .unwrap();
            let rows = stmt
                .query_map([], |r| r.get::<_, String>(0))
                .unwrap()
                .collect::<Result<Vec<_>, _>>()
                .unwrap();
            rows
        };
        assert_eq!(
            tombs.len(),
            1,
            "successive passes keep ONE tombstone per key"
        );
        let marker: serde_json::Value = serde_json::from_str(&tombs[0]).unwrap();
        assert_eq!(
            marker["versions"],
            serde_json::json!(6),
            "merged tombstone must carry 3 (prior roll-up) + 3 (new) versions"
        );
        assert_ne!(marker["digest"].as_str().unwrap(), first_digest);
        let _ = fs::remove_file(&path);
    }

    /// #398: with tombstones disabled the evicted prefix is hard-deleted and
    /// as_of inside the window finds nothing (the degenerate option-1 mode).
    #[test]
    fn history_retention_hard_delete_when_tombstones_disabled() {
        let (db, path) = temp_db();
        let t_first = seed_versions(&db, 3); // 2 history rows
        let report = db
            .enforce_history_retention(&retention_policy(None, Some(1), None, false), false)
            .unwrap();
        assert_eq!(report.rows_evicted, 1);
        assert_eq!(report.tombstones_written, 0);
        assert_eq!(history_count(&db), 1, "hard delete: no tombstone row");
        assert!(
            db.as_of("facts", "versioned-key", t_first)
                .unwrap()
                .is_none(),
            "hard-deleted window answers nothing"
        );
        let _ = fs::remove_file(&path);
    }

    /// #398 rider (review-probed): a compacted version that was RETROACTIVELY
    /// valid (valid_from in the far past) answered valid_at(past) before
    /// compaction — so the tombstone must carry the run's earliest effective
    /// valid_from, not first_recorded_at (transaction time), or the
    /// valid-time axis silently loses the whole retroactive window and
    /// valid_at(past) flips from "answer" to None with no marker.
    #[test]
    fn history_retention_tombstone_preserves_retroactive_valid_from() {
        use std::thread::sleep;
        use std::time::Duration;
        let (db, path) = temp_db();
        let vf = now_ms() - 30 * 86_400_000; // true since a month ago

        db.remember_with_validity(
            &make_entity("e-retro-1", "facts", "retro-key", r#"{"note":"retro v1"}"#),
            Some(vf),
            None,
        )
        .unwrap();
        sleep(Duration::from_millis(3));
        db.remember(&make_entity(
            "e-retro-2",
            "facts",
            "retro-key",
            r#"{"note":"v2"}"#,
        ))
        .unwrap();
        sleep(Duration::from_millis(3));
        db.remember(&make_entity(
            "e-retro-3",
            "facts",
            "retro-key",
            r#"{"note":"v3"}"#,
        ))
        .unwrap(); // history: h1 (retro v1, valid_from=vf), h2 (v2)

        // Sanity: pre-compaction, the retroactive instant answers with v1.
        let pre = db
            .valid_at("facts", "retro-key", vf + 3_600_000)
            .unwrap()
            .expect("retroactive window must answer pre-compaction");
        assert!(pre.entity.body_json.contains("retro v1"));

        // Evict everything but the newest stored version (h1 goes).
        let report = db
            .enforce_history_retention(&retention_policy(None, Some(1), None, true), false)
            .unwrap();
        assert_eq!(report.rows_evicted, 1);
        assert_eq!(report.tombstones_written, 1);

        // The compacted window must still answer on the VALID-time axis —
        // with the explicit marker, not None (pre-fix: tombstone valid_from
        // was first_recorded_at, discarding vf, so this returned None).
        let post = db
            .valid_at("facts", "retro-key", vf + 3_600_000)
            .unwrap()
            .expect(
                "valid_at inside a compacted retroactive window must return the \
                 compacted marker, not None",
            );
        assert_eq!(post.entity.status, "compacted");
        assert!(post.entity.body_json.contains("\"compacted\":true"));
        // Strictly before the retroactive opening → still None (no window).
        assert!(db.valid_at("facts", "retro-key", vf - 1).unwrap().is_none());

        let _ = fs::remove_file(&path);
    }

    /// #398: perseus_vault_stats surfaces history growth — rows, stored bytes, and
